INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.KUSIKI.T1_KUSIKILIZA_NA_KUJIBU.MAZUNGUMZO', 'KISW.G7.KUSIKI.T1_KUSIKILIZA_NA_KUJIBU', 'kiswahili', 7, 'Sikiliza na ujibu mazungumzo ipasavyo', ARRAY['KISW.G7.KUSIKI.T1_KUSIKILIZA_NA_KUJIBU.a', 'KISW.G7.KUSIKI.T1_KUSIKILIZA_NA_KUJIBU.b', 'KISW.G7.KUSIKI.T1_KUSIKILIZA_NA_KUJIBU.c']::text[], 'Names the features to keep in this kind of talk (mazungumzo), picks the better of two ways to listen or reply in a situation on usafi wa kibinafsi, and takes part in one in standard Kiswahili, judged by the teacher with the KICD rubric; in the app, 8 of 10 new items right.', '["chagua jibu bora","tambua kosa la mzungumzaji","igiza (mwalimu anasikiliza)"]'::jsonb, '["application","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.RS_HABARI', 'KISW.G7.KUSOMA.T1_KUSOMA_KWA_UFAHAMU', 'kiswahili', 7, 'Dondoa habari mahususi katika kifungu cha simulizi', ARRAY['KISW.G7.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.a']::text[], 'Mtoto hupata jibu kwenye kifungu na huchagua lile linalojibu swali lote, wala hachagui jambo dogo, kinyume au jambo lisilomo kwenye matini. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika matini ya pili"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.RS_MATUKIO', 'KISW.G7.KUSOMA.T1_KUSOMA_KWA_UFAHAMU', 'kiswahili', 7, 'Panga matukio yanavyofuatana katika simulizi', ARRAY['KISW.G7.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.b']::text[], 'Mtoto hupata jibu kwenye kifungu na huchagua lile linalojibu swali lote, wala hachagui jambo dogo, kinyume au jambo lisilomo kwenye matini. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika matini ya pili"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.RS_UTABIRI', 'KISW.G7.KUSOMA.T1_KUSOMA_KWA_UFAHAMU', 'kiswahili', 7, 'Fanya utabiri na ufasiri kutokana na simulizi', ARRAY['KISW.G7.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.c']::text[], 'Mtoto hupata jibu kwenye kifungu na huchagua lile linalojibu swali lote, wala hachagui jambo dogo, kinyume au jambo lisilomo kwenye matini. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika matini ya pili"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.RS_MSAMIATI', 'KISW.G7.KUSOMA.T1_KUSOMA_KWA_UFAHAMU', 'kiswahili', 7, 'Eleza msamiati katika simulizi', ARRAY['KISW.G7.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.d']::text[], 'Mtoto hupata jibu kwenye kifungu na huchagua lile linalojibu swali lote, wala hachagui jambo dogo, kinyume au jambo lisilomo kwenye matini. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika matini ya pili"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.KUANDI.T1_VIAKIFISHI.HERUFI_KUBWA', 'KISW.G7.KUANDI.T1_VIAKIFISHI', 'kiswahili', 7, 'Tumia herufi kubwa na kikomo', ARRAY['KISW.G7.KUANDI.T1_VIAKIFISHI.a', 'KISW.G7.KUANDI.T1_VIAKIFISHI.b', 'KISW.G7.KUANDI.T1_VIAKIFISHI.c']::text[], 'Mtoto hutumia herufi kubwa mwanzoni mwa sentensi na kwa majina ya pekee, na kikomo (.) mwishoni mwa sentensi ya kawaida. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.SARUFI.T1_AINA_ZA_NOMINO.NOMINO_PEKEE', 'KISW.G7.SARUFI.T1_AINA_ZA_NOMINO', 'kiswahili', 7, 'Tambua nomino za pekee na za kawaida', ARRAY['KISW.G7.SARUFI.T1_AINA_ZA_NOMINO.a', 'KISW.G7.SARUFI.T1_AINA_ZA_NOMINO.b', 'KISW.G7.SARUFI.T1_AINA_ZA_NOMINO.c']::text[], 'Mtoto hutambua nomino ya pekee (jina la mtu, mahali au kitu kimoja mahususi) na nomino ya kawaida (jina la jumla), na huandika ya pekee kwa herufi kubwa. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.KUSIKI.T2_KUSIKILIZA_KWA_KINA.MATAMSHI', 'KISW.G7.KUSIKI.T2_KUSIKILIZA_KWA_KINA', 'kiswahili', 7, 'Tofautisha sauti /dh/ na /th/ katika silabi, maneno na vitanzandimi', ARRAY['KISW.G7.KUSIKI.T2_KUSIKILIZA_KWA_KINA.a', 'KISW.G7.KUSIKI.T2_KUSIKILIZA_KWA_KINA.b', 'KISW.G7.KUSIKI.T2_KUSIKILIZA_KWA_KINA.c']::text[], 'Hears, says and writes the right sound in syllables and words with /dh/ na /th/ (dhamini and thamini, dhibiti and thibiti), picks the word that matches the meaning, and tells a real kitanzandimi from an ordinary sentence, in 8 of 10 new items.', '["chagua neno ulilosikia","chagua maana ya neno","jaza pengo kwa neno sahihi","tambua kitanzandimi"]'::jsonb, '["recall","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.KUSOMA.T2_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'KISW.G7.KUSOMA.T2_KUSOMA_KWA_MAPANA', 'kiswahili', 7, 'Chagua matini ya kusoma na ueleze ujumbe wake', ARRAY['KISW.G7.KUSOMA.T2_KUSOMA_KWA_MAPANA.a', 'KISW.G7.KUSOMA.T2_KUSOMA_KWA_MAPANA.b', 'KISW.G7.KUSOMA.T2_KUSOMA_KWA_MAPANA.c']::text[], 'Chooses a text that suits his reading level and interest from its title, blurb and first page (not from the cover alone), tells the kind of text (hadithi, shairi, makala, gazeti), says its message in one sentence, and works out a new word from the sentence around it, in 8 of 10 new items.', '["chagua matini ifaayo","chagua ujumbe","tambua aina ya matini","eleza maana ya neno"]'::jsonb, '["evaluation","inference"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.KUANDI.T2_BARUA_YA_KIRAFIKI_YA.BARUA_MWALIKO', 'KISW.G7.KUANDI.T2_BARUA_YA_KIRAFIKI_YA', 'kiswahili', 7, 'Tambua muundo wa barua ya kirafiki ya mwaliko', ARRAY['KISW.G7.KUANDI.T2_BARUA_YA_KIRAFIKI_YA.a', 'KISW.G7.KUANDI.T2_BARUA_YA_KIRAFIKI_YA.c', 'KISW.G7.KUANDI.T2_BARUA_YA_KIRAFIKI_YA.b']::text[], 'Mtoto hutambua vipengele vya barua ya kirafiki (anwani, tarehe, salamu, ujumbe, hitimisho, jina) na umuhimu wa mwaliko. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.KUANDI.T2_BARUA_YA_KIRAFIKI_YA.KUANDIKA_MWALIKO', 'KISW.G7.KUANDI.T2_BARUA_YA_KIRAFIKI_YA', 'kiswahili', 7, 'Andika barua ya kirafiki ya kutoa mwaliko', ARRAY['KISW.G7.KUANDI.T2_BARUA_YA_KIRAFIKI_YA.d']::text[], 'Tells barua ya kirafiki from other kinds of writing and its parts, and writes a friendly letter with the address, date, greeting, asking after the friend, the news, and a friendly closing; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.SARUFI.T2_AINA_ZA_NOMINO.NOMINO_MAKUNDI', 'KISW.G7.SARUFI.T2_AINA_ZA_NOMINO', 'kiswahili', 7, 'Tambua nomino za makundi na za dhahania', ARRAY['KISW.G7.SARUFI.T2_AINA_ZA_NOMINO.a', 'KISW.G7.SARUFI.T2_AINA_ZA_NOMINO.b']::text[], 'Mtoto hutambua nomino za makundi (kundi la viumbe au vitu, k.m. kikosi, jeshi) na za dhahania (mambo yasiyoshikika, k.m. upendo, furaha). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.KUSIKI.T3_TANZU_ZA_FASIHI.FASIHI_TANZU', 'KISW.G7.KUSIKI.T3_TANZU_ZA_FASIHI', 'kiswahili', 7, 'Eleza maana ya fasihi na tanzu zake', ARRAY['KISW.G7.KUSIKI.T3_TANZU_ZA_FASIHI.a', 'KISW.G7.KUSIKI.T3_TANZU_ZA_FASIHI.b', 'KISW.G7.KUSIKI.T3_TANZU_ZA_FASIHI.c', 'KISW.G7.KUSIKI.T3_TANZU_ZA_FASIHI.d']::text[], 'Mtoto hueleza fasihi, hutambua fasihi simulizi (kutumia mdomo) na andishi (kuandikwa), na hutambua tanzu kama hadithi, methali na ushairi. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.KUSOMA.T3_KUSOMA_KWA_KINA.NOVELA_UTANZU', 'KISW.G7.KUSOMA.T3_KUSOMA_KWA_KINA', 'kiswahili', 7, 'Eleza maana na sifa za novela', ARRAY['KISW.G7.KUSOMA.T3_KUSOMA_KWA_KINA.a', 'KISW.G7.KUSOMA.T3_KUSOMA_KWA_KINA.b']::text[], 'Explains the utanzu of a novela read in class ("Kisima cha Matumaini") with a correct term, gives evidence from the text for every point, and says why it matters to the work, in 8 of 10 new items (longer written answers marked by the teacher).', '["chagua jibu sahihi","toa ushahidi kutoka kazi","tambua kosa katika uchambuzi","jibu fupi la kuandika"]'::jsonb, '["analysis","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.KUANDI.T3_INSHA_ZA_KUBUNI.KUBUNI_VIDOKEZO', 'KISW.G7.KUANDI.T3_INSHA_ZA_KUBUNI', 'kiswahili', 7, 'Teua mada, andaa vidokezo na uandike insha ya kubuni', ARRAY['KISW.G7.KUANDI.T3_INSHA_ZA_KUBUNI.a', 'KISW.G7.KUANDI.T3_INSHA_ZA_KUBUNI.b', 'KISW.G7.KUANDI.T3_INSHA_ZA_KUBUNI.c', 'KISW.G7.KUANDI.T3_INSHA_ZA_KUBUNI.d']::text[], 'Tells insha ya kubuni from other kinds of writing and its parts, and writes a creative story built paragraph by paragraph, with characters, a setting and vivid language; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.SARUFI.T3_AINA_ZA_NOMINO.NOMINO_WINGI', 'KISW.G7.SARUFI.T3_AINA_ZA_NOMINO', 'kiswahili', 7, 'Tambua nomino za wingi na vitenzi-jina', ARRAY['KISW.G7.SARUFI.T3_AINA_ZA_NOMINO.a', 'KISW.G7.SARUFI.T3_AINA_ZA_NOMINO.b']::text[], 'Mtoto hutambua nomino za wingi (maji, mafuta) na kitenzi-jina (kuimba, kusoma) kinachoanza kwa ku-. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.KUSIKI.T4_NYIMBO.NYIMBO', 'KISW.G7.KUSIKI.T4_NYIMBO', 'kiswahili', 7, 'Eleza maana, aina na sifa za nyimbo', ARRAY['KISW.G7.KUSIKI.T4_NYIMBO.a', 'KISW.G7.KUSIKI.T4_NYIMBO.b', 'KISW.G7.KUSIKI.T4_NYIMBO.c', 'KISW.G7.KUSIKI.T4_NYIMBO.d']::text[], 'Explains the maana of nyimbo (bembelezi, wimbo wa watoto) with the right terms and examples, gives evidence or a reason for each point, and presents one with its formula, voice, gestures and audience part (presentation scored by the teacher), in 8 of 10 new items.', '["chagua jibu sahihi","toa mfano","tambua kosa","wasilisha (mwalimu anasikiliza)"]'::jsonb, '["analysis","performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.KUSOMA.T4_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'KISW.G7.KUSOMA.T4_KUSOMA_KWA_UFASAHA', 'kiswahili', 7, 'Soma kifungu kwa sauti kwa matamshi bora, kasi ifaayo, sauti ifaayo na ishara', ARRAY['KISW.G7.KUSOMA.T4_KUSOMA_KWA_UFASAHA.a', 'KISW.G7.KUSOMA.T4_KUSOMA_KWA_UFASAHA.b', 'KISW.G7.KUSOMA.T4_KUSOMA_KWA_UFASAHA.c', 'KISW.G7.KUSOMA.T4_KUSOMA_KWA_UFASAHA.d']::text[], 'Reads a short passage aloud at a speaking pace, pauses at the koma and the kikomo, raises the voice for a question and shows feeling for an exclamation, says every sound clearly (no l for r), and uses a matching gesture, judged by the teacher with the KICD rubric; in the app picks the better reading of a line in 8 of 10 new items.', '["chagua usomaji bora","tambua kosa la usomaji","kusoma kwa sauti (mwalimu anasikiliza)"]'::jsonb, '["application","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.KUANDI.T4_INSHA_ZA_KUBUNI.KUBUNI_LUGHA', 'KISW.G7.KUANDI.T4_INSHA_ZA_KUBUNI', 'kiswahili', 7, 'Andika insha ya masimulizi kwa lugha ya kiubunifu, wahusika na mandhari', ARRAY['KISW.G7.KUANDI.T4_INSHA_ZA_KUBUNI.a', 'KISW.G7.KUANDI.T4_INSHA_ZA_KUBUNI.b', 'KISW.G7.KUANDI.T4_INSHA_ZA_KUBUNI.c', 'KISW.G7.KUANDI.T4_INSHA_ZA_KUBUNI.d', 'KISW.G7.KUANDI.T4_INSHA_ZA_KUBUNI.e']::text[], 'Tells insha ya kubuni from other kinds of writing and its parts, and writes a creative story built paragraph by paragraph, with characters, a setting and vivid language; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.SARUFI.T4_NYAKATI_NA_HALI.NYAKATI_MSINGI', 'KISW.G7.SARUFI.T4_NYAKATI_NA_HALI', 'kiswahili', 7, 'Tambua wakati uliopo, uliopita na ujao', ARRAY['KISW.G7.SARUFI.T4_NYAKATI_NA_HALI.a', 'KISW.G7.SARUFI.T4_NYAKATI_NA_HALI.b']::text[], 'Mtoto hutambua kiambishi -na- (uliopo), -li- (uliopita) na -ta- (ujao), na hutumia wakati unaofaa. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.KUSIKI.T5_MAZUNGUMZO_MAHUSUSI.MAAMKUZI_JAMII', 'KISW.G7.KUSIKI.T5_MAZUNGUMZO_MAHUSUSI', 'kiswahili', 7, 'Tumia maamkuzi na maagano ya nyakati na makundi mbalimbali ya kijamii', ARRAY['KISW.G7.KUSIKI.T5_MAZUNGUMZO_MAHUSUSI.a', 'KISW.G7.KUSIKI.T5_MAZUNGUMZO_MAHUSUSI.b', 'KISW.G7.KUSIKI.T5_MAZUNGUMZO_MAHUSUSI.c', 'KISW.G7.KUSIKI.T5_MAZUNGUMZO_MAHUSUSI.d']::text[], 'Greets and takes leave to fit the time of day (alfajiri, asubuhi, mchana, jioni, usiku) and the group (elders, age-mates, religious groups with Bwana asifiwe or Salaam aleikum, the bereaved), and gives the right reply, in 8 of 10 new items.', '["chagua salamu ifaayo","chagua jibu la salamu","tambua kosa","igiza (mwalimu anasikiliza)"]'::jsonb, '["application"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.RS_UFAHAMU5', 'KISW.G7.KUSOMA.T5_KUSOMA_KWA_UFAHAMU', 'kiswahili', 7, 'Dondoa habari, eleza kwa ufupi na eleza msamiati katika kifungu cha ufahamu', ARRAY['KISW.G7.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.a', 'KISW.G7.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.b', 'KISW.G7.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.c']::text[], 'Mtoto hupata jibu kwenye kifungu na huchagua lile linalojibu swali lote, wala hachagui jambo dogo, kinyume au jambo lisilomo kwenye matini. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika matini ya pili"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.KUANDI.T5_INSHA_YA_MAELEKEZO.MAELEKEZO', 'KISW.G7.KUANDI.T5_INSHA_YA_MAELEKEZO', 'kiswahili', 7, 'Tambua na andika insha ya maelekezo', ARRAY['KISW.G7.KUANDI.T5_INSHA_YA_MAELEKEZO.a', 'KISW.G7.KUANDI.T5_INSHA_YA_MAELEKEZO.b', 'KISW.G7.KUANDI.T5_INSHA_YA_MAELEKEZO.c', 'KISW.G7.KUANDI.T5_INSHA_YA_MAELEKEZO.d', 'KISW.G7.KUANDI.T5_INSHA_YA_MAELEKEZO.e']::text[], 'Tells insha ya maelekezo from other kinds of writing and its parts, and writes instructions with their purpose, the materials, the steps in order as commands, and safety warnings; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.SARUFI.T5_NYAKATI_NA_HALI.NYAKATI_KUENDELEA', 'KISW.G7.SARUFI.T5_NYAKATI_NA_HALI', 'kiswahili', 7, 'Tambua uliopita hali ya kuendelea na ujao hali ya kuendelea', ARRAY['KISW.G7.SARUFI.T5_NYAKATI_NA_HALI.a', 'KISW.G7.SARUFI.T5_NYAKATI_NA_HALI.b']::text[], 'Mtoto hutambua alikuwa akisoma (uliopita hali ya kuendelea) na atakuwa akisoma (ujao hali ya kuendelea). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.KUSIKI.T6_KUSIKILIZA_KWA_KUFAS.LS_MASUALA', 'KISW.G7.KUSIKI.T6_KUSIKILIZA_KWA_KUFAS', 'kiswahili', 7, 'Eleza masuala na msamiati katika matini ya kusikiliza', ARRAY['KISW.G7.KUSIKI.T6_KUSIKILIZA_KWA_KUFAS.a', 'KISW.G7.KUSIKI.T6_KUSIKILIZA_KWA_KUFAS.c', 'KISW.G7.KUSIKI.T6_KUSIKILIZA_KWA_KUFAS.b', 'KISW.G7.KUSIKI.T6_KUSIKILIZA_KWA_KUFAS.d']::text[], 'Mtoto hukumbuka alichosikia na huchagua jibu linalolingana na matini yote, wala hachagui jambo dogo, kinyume au jambo lisilomo kwenye matini. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika matini ya pili"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.KUSOMA.T6_KUSOMA_KWA_KINA.NOVELA_MAUDHUI', 'KISW.G7.KUSOMA.T6_KUSOMA_KWA_KINA', 'kiswahili', 7, 'Jadili maudhui na dhamira katika novela', ARRAY['KISW.G7.KUSOMA.T6_KUSOMA_KWA_KINA.a', 'KISW.G7.KUSOMA.T6_KUSOMA_KWA_KINA.b', 'KISW.G7.KUSOMA.T6_KUSOMA_KWA_KINA.c', 'KISW.G7.KUSOMA.T6_KUSOMA_KWA_KINA.d']::text[], 'Explains the maudhui of a novela read in class ("Kisima cha Matumaini") with a correct term, gives evidence from the text for every point, and says why it matters to the work, in 8 of 10 new items (longer written answers marked by the teacher).', '["chagua jibu sahihi","toa ushahidi kutoka kazi","tambua kosa katika uchambuzi","jibu fupi la kuandika"]'::jsonb, '["analysis","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.KUANDI.T6_INSHA_ZA_KUBUNI.KUBUNI_PICHA', 'KISW.G7.KUANDI.T6_INSHA_ZA_KUBUNI', 'kiswahili', 7, 'Andika kisa chenye maelezo dhahiri kutokana na picha', ARRAY['KISW.G7.KUANDI.T6_INSHA_ZA_KUBUNI.a', 'KISW.G7.KUANDI.T6_INSHA_ZA_KUBUNI.b', 'KISW.G7.KUANDI.T6_INSHA_ZA_KUBUNI.c']::text[], 'Tells insha ya kubuni from other kinds of writing and its parts, and writes a creative story built paragraph by paragraph, with characters, a setting and vivid language; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.SARUFI.T6_VITENZI.VITENZI_VIKUU', 'KISW.G7.SARUFI.T6_VITENZI', 'kiswahili', 7, 'Tambua vitenzi vikuu na visaidizi', ARRAY['KISW.G7.SARUFI.T6_VITENZI.a', 'KISW.G7.SARUFI.T6_VITENZI.b']::text[], 'Mtoto hutambua kitenzi kikuu (hubeba tendo) na kisaidizi (hutangulia kikuu na kusaidia, k.m. alikuwa, atakuwa). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.KUSIKI.T7_KUSIKILIZA_KWA_UFAHA.LS_UJUMBE', 'KISW.G7.KUSIKI.T7_KUSIKILIZA_KWA_UFAHA', 'kiswahili', 7, 'Tambua ujumbe na msamiati katika ufahamu wa kusikiliza', ARRAY['KISW.G7.KUSIKI.T7_KUSIKILIZA_KWA_UFAHA.a', 'KISW.G7.KUSIKI.T7_KUSIKILIZA_KWA_UFAHA.b', 'KISW.G7.KUSIKI.T7_KUSIKILIZA_KWA_UFAHA.c']::text[], 'Mtoto hukumbuka alichosikia na huchagua jibu linalolingana na matini yote, wala hachagui jambo dogo, kinyume au jambo lisilomo kwenye matini. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika matini ya pili"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.KUSOMA.T7_UFUPISHO.UFUPISHO', 'KISW.G7.KUSOMA.T7_UFUPISHO', 'kiswahili', 7, 'Eleza maana ya ufupisho na habari kuu', ARRAY['KISW.G7.KUSOMA.T7_UFUPISHO.a', 'KISW.G7.KUSOMA.T7_UFUPISHO.b', 'KISW.G7.KUSOMA.T7_UFUPISHO.c']::text[], 'Mtoto hueleza ufupisho (kutoa habari kuu bila kupoteza maana) na hutambua habari kuu ya aya. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.KUANDI.T7_INSHA_ZA_KUBUNI.MAELEZO_MSAMIATI', 'KISW.G7.KUANDI.T7_INSHA_ZA_KUBUNI', 'kiswahili', 7, 'Tumia msamiati ufaao katika insha ya maelezo', ARRAY['KISW.G7.KUANDI.T7_INSHA_ZA_KUBUNI.a', 'KISW.G7.KUANDI.T7_INSHA_ZA_KUBUNI.b', 'KISW.G7.KUANDI.T7_INSHA_ZA_KUBUNI.c', 'KISW.G7.KUANDI.T7_INSHA_ZA_KUBUNI.d']::text[], 'Tells insha ya maelezo from other kinds of writing and its parts, and writes a description or explanation with exact vocabulary, ordered paragraphs and vivid language; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.SARUFI.T7_VITENZI_VISHIRIKISHI.VISHIRIKISHI', 'KISW.G7.SARUFI.T7_VITENZI_VISHIRIKISHI', 'kiswahili', 7, 'Tambua na utumie vitenzi vishirikishi', ARRAY['KISW.G7.SARUFI.T7_VITENZI_VISHIRIKISHI.a', 'KISW.G7.SARUFI.T7_VITENZI_VISHIRIKISHI.b']::text[], 'Mtoto hutambua kitenzi kishirikishi (ni, si, yuko, wako, ndiye, ndio) na hukitumia sentensi. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.KUSIKI.T8_KUZUNGUMZA_ILI_KUPAS.KUPASHA_HABARI', 'KISW.G7.KUSIKI.T8_KUZUNGUMZA_ILI_KUPAS', 'kiswahili', 7, 'Zungumza ili kupasha habari', ARRAY['KISW.G7.KUSIKI.T8_KUZUNGUMZA_ILI_KUPAS.a', 'KISW.G7.KUSIKI.T8_KUZUNGUMZA_ILI_KUPAS.b', 'KISW.G7.KUSIKI.T8_KUZUNGUMZA_ILI_KUPAS.c', 'KISW.G7.KUSIKI.T8_KUZUNGUMZA_ILI_KUPAS.d']::text[], 'Names the features to keep in this kind of talk (kupasha), picks the better of two ways to listen or reply in a situation on tahadhari kuhusu ulaguzi wa binadamu, and takes part in one in standard Kiswahili, judged by the teacher with the KICD rubric; in the app, 8 of 10 new items right.', '["chagua jibu bora","tambua kosa la mzungumzaji","igiza (mwalimu anasikiliza)"]'::jsonb, '["application","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.KUSOMA.T8_KUSOMA_KWA_KINA.NOVELA_MANDHARI', 'KISW.G7.KUSOMA.T8_KUSOMA_KWA_KINA', 'kiswahili', 7, 'Eleza mandhari na ploti ya novela', ARRAY['KISW.G7.KUSOMA.T8_KUSOMA_KWA_KINA.a', 'KISW.G7.KUSOMA.T8_KUSOMA_KWA_KINA.b', 'KISW.G7.KUSOMA.T8_KUSOMA_KWA_KINA.c', 'KISW.G7.KUSOMA.T8_KUSOMA_KWA_KINA.d']::text[], 'Explains the mandhari of a novela read in class ("Kisima cha Matumaini") with a correct term, gives evidence from the text for every point, and says why it matters to the work, in 8 of 10 new items (longer written answers marked by the teacher).', '["chagua jibu sahihi","toa ushahidi kutoka kazi","tambua kosa katika uchambuzi","jibu fupi la kuandika"]'::jsonb, '["analysis","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.KUANDI.T8_VIAKIFISHI.KIULIZI_KOMA', 'KISW.G7.KUANDI.T8_VIAKIFISHI', 'kiswahili', 7, 'Tumia kiulizi na koma', ARRAY['KISW.G7.KUANDI.T8_VIAKIFISHI.a', 'KISW.G7.KUANDI.T8_VIAKIFISHI.b']::text[], 'Mtoto hutumia kiulizi (?) mwishoni mwa swali na koma (,) kutenganisha vitu katika orodha na baada ya salamu au kiunganishi. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.SARUFI.T8_NGELI_NA_UPATANISHO_.NGELI_AWA_UI', 'KISW.G7.SARUFI.T8_NGELI_NA_UPATANISHO_', 'kiswahili', 7, 'Tumia ngeli za A-WA na U-I na upatanisho wa kisarufi', ARRAY['KISW.G7.SARUFI.T8_NGELI_NA_UPATANISHO_.a', 'KISW.G7.SARUFI.T8_NGELI_NA_UPATANISHO_.b', 'KISW.G7.SARUFI.T8_NGELI_NA_UPATANISHO_.c']::text[], 'Mtoto hutambua nomino za A-WA (mtu, mtoto, mnyama: wa-) na U-I (mti, mlima: mi-) na hutumia viambishi vya upatanisho (a-/wa-, u-/i-). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.KUSIKI.T9_KUSIKILIZA_KWA_KINA.MATAMSHI', 'KISW.G7.KUSIKI.T9_KUSIKILIZA_KWA_KINA', 'kiswahili', 7, 'Tofautisha sauti /d/ na /nd/ katika silabi, maneno na vitanzandimi', ARRAY['KISW.G7.KUSIKI.T9_KUSIKILIZA_KWA_KINA.a', 'KISW.G7.KUSIKI.T9_KUSIKILIZA_KWA_KINA.b']::text[], 'Hears, says and writes the right sound in syllables and words with /d/ na /nd/ (doa and ndoa, dama and ndama), picks the word that matches the meaning, and tells a real kitanzandimi from an ordinary sentence, in 8 of 10 new items.', '["chagua neno ulilosikia","chagua maana ya neno","jaza pengo kwa neno sahihi","tambua kitanzandimi"]'::jsonb, '["recall","discrimination"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.RS_USHAWISHI', 'KISW.G7.KUSOMA.T9_KUSOMA_KWA_UFAHAMU', 'kiswahili', 7, 'Soma kifungu cha kushawishi: habari, msamiati na ufupi', ARRAY['KISW.G7.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.a', 'KISW.G7.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.b', 'KISW.G7.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.c']::text[], 'Mtoto hupata jibu kwenye kifungu na huchagua lile linalojibu swali lote, wala hachagui jambo dogo, kinyume au jambo lisilomo kwenye matini. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika matini ya pili"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.KUANDI.T9_INSHA_ZA_KUBUNI.KUBUNI_AYA', 'KISW.G7.KUANDI.T9_INSHA_ZA_KUBUNI', 'kiswahili', 7, 'Andika insha ya masimulizi ukikuza wazo katika kila aya', ARRAY['KISW.G7.KUANDI.T9_INSHA_ZA_KUBUNI.a', 'KISW.G7.KUANDI.T9_INSHA_ZA_KUBUNI.b', 'KISW.G7.KUANDI.T9_INSHA_ZA_KUBUNI.c']::text[], 'Tells insha ya kubuni from other kinds of writing and its parts, and writes a creative story built paragraph by paragraph, with characters, a setting and vivid language; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.SARUFI.T9_NGELI_NA_UPATANISHO_.NGELI_KIVI_LIYA', 'KISW.G7.SARUFI.T9_NGELI_NA_UPATANISHO_', 'kiswahili', 7, 'Tumia ngeli za KI-VI na LI-YA na upatanisho wa kisarufi', ARRAY['KISW.G7.SARUFI.T9_NGELI_NA_UPATANISHO_.a', 'KISW.G7.SARUFI.T9_NGELI_NA_UPATANISHO_.b', 'KISW.G7.SARUFI.T9_NGELI_NA_UPATANISHO_.c']::text[], 'Mtoto hutambua nomino za KI-VI (kitabu: vi-) na LI-YA (jiwe: ma-) na hutumia viambishi vya upatanisho (ki-/vi-, li-/ya-). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.KUSIKI.T10_NYIMBO.NYIMBO', 'KISW.G7.KUSIKI.T10_NYIMBO', 'kiswahili', 7, 'Eleza maana, aina na sifa za nyimbo', ARRAY['KISW.G7.KUSIKI.T10_NYIMBO.a', 'KISW.G7.KUSIKI.T10_NYIMBO.b', 'KISW.G7.KUSIKI.T10_NYIMBO.c', 'KISW.G7.KUSIKI.T10_NYIMBO.d']::text[], 'Explains the maana of nyimbo (wimbo wa kazi, wimbo wa dini) with the right terms and examples, gives evidence or a reason for each point, and presents one with its formula, voice, gestures and audience part (presentation scored by the teacher), in 8 of 10 new items.', '["chagua jibu sahihi","toa mfano","tambua kosa","wasilisha (mwalimu anasikiliza)"]'::jsonb, '["analysis","performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.KUSOMA.T10_KUSOMA_KWA_KINA.NOVELA_WAHUSIKA', 'KISW.G7.KUSOMA.T10_KUSOMA_KWA_KINA', 'kiswahili', 7, 'Chambua wahusika na sifa zao katika novela', ARRAY['KISW.G7.KUSOMA.T10_KUSOMA_KWA_KINA.a', 'KISW.G7.KUSOMA.T10_KUSOMA_KWA_KINA.b', 'KISW.G7.KUSOMA.T10_KUSOMA_KWA_KINA.c', 'KISW.G7.KUSOMA.T10_KUSOMA_KWA_KINA.d', 'KISW.G7.KUSOMA.T10_KUSOMA_KWA_KINA.e']::text[], 'Explains the wahusika of a novela read in class ("Kisima cha Matumaini") with a correct term, gives evidence from the text for every point, and says why it matters to the work, in 8 of 10 new items (longer written answers marked by the teacher).', '["chagua jibu sahihi","toa ushahidi kutoka kazi","tambua kosa katika uchambuzi","jibu fupi la kuandika"]'::jsonb, '["analysis","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.KUANDI.T10_BARUA_RASMI_YA_KUOMB.BARUA_MSAMAHA', 'KISW.G7.KUANDI.T10_BARUA_RASMI_YA_KUOMB', 'kiswahili', 7, 'Tambua muundo wa barua rasmi ya kuomba msamaha', ARRAY['KISW.G7.KUANDI.T10_BARUA_RASMI_YA_KUOMB.a', 'KISW.G7.KUANDI.T10_BARUA_RASMI_YA_KUOMB.c', 'KISW.G7.KUANDI.T10_BARUA_RASMI_YA_KUOMB.b']::text[], 'Mtoto hutambua vipengele vya barua rasmi (anwani mbili, tarehe, salamu rasmi, kichwa, ujumbe, hitimisho) na lugha ya heshima. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.KUANDI.T10_BARUA_RASMI_YA_KUOMB.KUANDIKA_MSAMAHA', 'KISW.G7.KUANDI.T10_BARUA_RASMI_YA_KUOMB', 'kiswahili', 7, 'Andika barua rasmi ya kuomba msamaha', ARRAY['KISW.G7.KUANDI.T10_BARUA_RASMI_YA_KUOMB.d']::text[], 'Tells barua rasmi from other kinds of writing and its parts, and writes an official letter with two addresses, the date, a formal greeting, a KUH: line, the message and Wako mtiifu with a signature; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.SARUFI.T10_VINYUME.VINYUME', 'KISW.G7.SARUFI.T10_VINYUME', 'kiswahili', 7, 'Eleza na tumia vinyume vya nomino na vivumishi', ARRAY['KISW.G7.SARUFI.T10_VINYUME.a', 'KISW.G7.SARUFI.T10_VINYUME.b', 'KISW.G7.SARUFI.T10_VINYUME.c']::text[], 'Mtoto hueleza kinyume cha neno (neno lenye maana kinyume) na hutambua vinyume vya nomino na vivumishi. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.KUSIKI.T11_KUZUNGUMZA_KWA_KUAMB.ISHARA', 'KISW.G7.KUSIKI.T11_KUZUNGUMZA_KWA_KUAMB', 'kiswahili', 7, 'Zungumza ukiambatanisha vitendo na ishara', ARRAY['KISW.G7.KUSIKI.T11_KUZUNGUMZA_KWA_KUAMB.a', 'KISW.G7.KUSIKI.T11_KUZUNGUMZA_KWA_KUAMB.b', 'KISW.G7.KUSIKI.T11_KUZUNGUMZA_KWA_KUAMB.c', 'KISW.G7.KUSIKI.T11_KUZUNGUMZA_KWA_KUAMB.d']::text[], 'Names the features to keep in this kind of talk (ishara), picks the better of two ways to listen or reply in a situation on majukumu ya watoto nyumbani, and takes part in one in standard Kiswahili, judged by the teacher with the KICD rubric; in the app, 8 of 10 new items right.', '["chagua jibu bora","tambua kosa la mzungumzaji","igiza (mwalimu anasikiliza)"]'::jsonb, '["application","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.KUSOMA.T11_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'KISW.G7.KUSOMA.T11_KUSOMA_KWA_MAPANA', 'kiswahili', 7, 'Chagua matini ya kusoma na ueleze ujumbe wake', ARRAY['KISW.G7.KUSOMA.T11_KUSOMA_KWA_MAPANA.a', 'KISW.G7.KUSOMA.T11_KUSOMA_KWA_MAPANA.b', 'KISW.G7.KUSOMA.T11_KUSOMA_KWA_MAPANA.c', 'KISW.G7.KUSOMA.T11_KUSOMA_KWA_MAPANA.d']::text[], 'Chooses a text that suits his reading level and interest from its title, blurb and first page (not from the cover alone), tells the kind of text (hadithi, shairi, makala, gazeti), says its message in one sentence, and works out a new word from the sentence around it, in 8 of 10 new items.', '["chagua matini ifaayo","chagua ujumbe","tambua aina ya matini","eleza maana ya neno"]'::jsonb, '["evaluation","inference"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.KUANDI.T11_INSHA_ZA_KUBUNI.MAELEZO_MPANGILIO', 'KISW.G7.KUANDI.T11_INSHA_ZA_KUBUNI', 'kiswahili', 7, 'Andika insha ya maelezo kwa mpangilio ufaao', ARRAY['KISW.G7.KUANDI.T11_INSHA_ZA_KUBUNI.a', 'KISW.G7.KUANDI.T11_INSHA_ZA_KUBUNI.b', 'KISW.G7.KUANDI.T11_INSHA_ZA_KUBUNI.c']::text[], 'Tells insha ya maelezo from other kinds of writing and its parts, and writes a description or explanation with exact vocabulary, ordered paragraphs and vivid language; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.SARUFI.T11_MNYAMBULIKO_WA_VITEN.KAULI', 'KISW.G7.SARUFI.T11_MNYAMBULIKO_WA_VITEN', 'kiswahili', 7, 'Tambua kauli za kutenda, kutendea na kutendwa', ARRAY['KISW.G7.SARUFI.T11_MNYAMBULIKO_WA_VITEN.a', 'KISW.G7.SARUFI.T11_MNYAMBULIKO_WA_VITEN.b']::text[], 'Mtoto hutambua kutenda (pika), kutendea (pikia) na kutendwa (pikwa) na hutumia kitenzi katika kauli inayofaa. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.KUSIKI.T12_KUSIKILIZA_KWA_MAKIN.LS_HOJA', 'KISW.G7.KUSIKI.T12_KUSIKILIZA_KWA_MAKIN', 'kiswahili', 7, 'Tambua hoja muhimu katika habari aliyosikiliza', ARRAY['KISW.G7.KUSIKI.T12_KUSIKILIZA_KWA_MAKIN.a', 'KISW.G7.KUSIKI.T12_KUSIKILIZA_KWA_MAKIN.b']::text[], 'Mtoto hukumbuka alichosikia na huchagua jibu linalolingana na matini yote, wala hachagui jambo dogo, kinyume au jambo lisilomo kwenye matini. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika matini ya pili"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.KUSOMA.T12_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'KISW.G7.KUSOMA.T12_KUSOMA_KWA_UFASAHA', 'kiswahili', 7, 'Soma kifungu kwa sauti kwa matamshi bora, kasi ifaayo, sauti ifaayo na ishara', ARRAY['KISW.G7.KUSOMA.T12_KUSOMA_KWA_UFASAHA.a', 'KISW.G7.KUSOMA.T12_KUSOMA_KWA_UFASAHA.b', 'KISW.G7.KUSOMA.T12_KUSOMA_KWA_UFASAHA.c', 'KISW.G7.KUSOMA.T12_KUSOMA_KWA_UFASAHA.d']::text[], 'Reads a short passage aloud at a speaking pace, pauses at the koma and the kikomo, raises the voice for a question and shows feeling for an exclamation, says every sound clearly (no l for r), and uses a matching gesture, judged by the teacher with the KICD rubric; in the app picks the better reading of a line in 8 of 10 new items.', '["chagua usomaji bora","tambua kosa la usomaji","kusoma kwa sauti (mwalimu anasikiliza)"]'::jsonb, '["application","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.KUANDI.T12_HOTUBA_YA_KUPASHA_HA.HOTUBA_KUPASHA', 'KISW.G7.KUANDI.T12_HOTUBA_YA_KUPASHA_HA', 'kiswahili', 7, 'Tambua na andika hotuba', ARRAY['KISW.G7.KUANDI.T12_HOTUBA_YA_KUPASHA_HA.a', 'KISW.G7.KUANDI.T12_HOTUBA_YA_KUPASHA_HA.b', 'KISW.G7.KUANDI.T12_HOTUBA_YA_KUPASHA_HA.c', 'KISW.G7.KUANDI.T12_HOTUBA_YA_KUPASHA_HA.d']::text[], 'Tells hotuba from other kinds of writing and its parts, and writes a speech with the itifaki, words spoken to the audience, facts the listener can use and a closing with thanks; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.SARUFI.T12_AINA_ZA_SENTENSI.SENTENSI', 'KISW.G7.SARUFI.T12_AINA_ZA_SENTENSI', 'kiswahili', 7, 'Tofautisha sentensi sahili na ambatano', ARRAY['KISW.G7.SARUFI.T12_AINA_ZA_SENTENSI.a', 'KISW.G7.SARUFI.T12_AINA_ZA_SENTENSI.b', 'KISW.G7.SARUFI.T12_AINA_ZA_SENTENSI.c']::text[], 'Mtoto hutambua sentensi sahili (wazo moja) na ambatano (mawazo mawili au zaidi yaliyounganishwa kwa kiunganishi). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.KUSIKI.T13_WAHUSIKA_KATIKA_NYIM.WAHUSIKA_NYIMBO', 'KISW.G7.KUSIKI.T13_WAHUSIKA_KATIKA_NYIM', 'kiswahili', 7, 'Chambua wahusika katika nyimbo', ARRAY['KISW.G7.KUSIKI.T13_WAHUSIKA_KATIKA_NYIM.a', 'KISW.G7.KUSIKI.T13_WAHUSIKA_KATIKA_NYIM.b', 'KISW.G7.KUSIKI.T13_WAHUSIKA_KATIKA_NYIM.c']::text[], 'Explains the wahusika of nyimbo (wimbo wa kazi, wimbo wa watoto) with the right terms and examples, gives evidence or a reason for each point, and presents one with its formula, voice, gestures and audience part (presentation scored by the teacher), in 8 of 10 new items.', '["chagua jibu sahihi","toa mfano","tambua kosa","wasilisha (mwalimu anasikiliza)"]'::jsonb, '["analysis","performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.KUSOMA.T13_KUSOMA_KWA_KINA.NOVELA_MBINU', 'KISW.G7.KUSOMA.T13_KUSOMA_KWA_KINA', 'kiswahili', 7, 'Tambua mbinu za lugha na umuhimu wake katika novela', ARRAY['KISW.G7.KUSOMA.T13_KUSOMA_KWA_KINA.a', 'KISW.G7.KUSOMA.T13_KUSOMA_KWA_KINA.b', 'KISW.G7.KUSOMA.T13_KUSOMA_KWA_KINA.c']::text[], 'Explains the mbinu of a novela read in class ("Kisima cha Matumaini") with a correct term, gives evidence from the text for every point, and says why it matters to the work, in 8 of 10 new items (longer written answers marked by the teacher).', '["chagua jibu sahihi","toa ushahidi kutoka kazi","tambua kosa katika uchambuzi","jibu fupi la kuandika"]'::jsonb, '["analysis","evaluation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.KUANDI.T13_INSHA_ZA_KUBUNI.MAELEZO_SIFA_MTU', 'KISW.G7.KUANDI.T13_INSHA_ZA_KUBUNI', 'kiswahili', 7, 'Andika insha ya maelezo inayodhihirisha sifa za mtu', ARRAY['KISW.G7.KUANDI.T13_INSHA_ZA_KUBUNI.a', 'KISW.G7.KUANDI.T13_INSHA_ZA_KUBUNI.b']::text[], 'Tells insha ya wasifu from other kinds of writing and its parts, and writes a description of a person, place or thing with describing words that agree with their nouns and no story of events; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.SARUFI.T13_UKANUSHAJI_KWA_KUZIN.UKANUSHAJI', 'KISW.G7.SARUFI.T13_UKANUSHAJI_KWA_KUZIN', 'kiswahili', 7, 'Kanusha sentensi katika nyakati tatu', ARRAY['KISW.G7.SARUFI.T13_UKANUSHAJI_KWA_KUZIN.c', 'KISW.G7.SARUFI.T13_UKANUSHAJI_KWA_KUZIN.d', 'KISW.G7.SARUFI.T13_UKANUSHAJI_KWA_KUZIN.a', 'KISW.G7.SARUFI.T13_UKANUSHAJI_KWA_KUZIN.b']::text[], 'Mtoto hukanusha sentensi katika wakati uliopo (hasomi), uliopita (hakusoma) na ujao (hatasoma). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.KUSIKI.T14_LUGHA_KATIKA_NYIMBO.LUGHA_NYIMBO', 'KISW.G7.KUSIKI.T14_LUGHA_KATIKA_NYIMBO', 'kiswahili', 7, 'Tambua vipengele vya lugha katika nyimbo', ARRAY['KISW.G7.KUSIKI.T14_LUGHA_KATIKA_NYIMBO.a', 'KISW.G7.KUSIKI.T14_LUGHA_KATIKA_NYIMBO.b']::text[], 'Explains the lugha of nyimbo (wimbo wa kazi, wimbo wa watoto) with the right terms and examples, gives evidence or a reason for each point, and presents one with its formula, voice, gestures and audience part (presentation scored by the teacher), in 8 of 10 new items.', '["chagua jibu sahihi","toa mfano","tambua kosa","wasilisha (mwalimu anasikiliza)"]'::jsonb, '["analysis","performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.KUSOMA.T14_KUSOMA_KWA_UFAHAMU.RS_MJADALA', 'KISW.G7.KUSOMA.T14_KUSOMA_KWA_UFAHAMU', 'kiswahili', 7, 'Soma kifungu cha mjadala: habari, msamiati na mitazamo', ARRAY['KISW.G7.KUSOMA.T14_KUSOMA_KWA_UFAHAMU.a', 'KISW.G7.KUSOMA.T14_KUSOMA_KWA_UFAHAMU.b', 'KISW.G7.KUSOMA.T14_KUSOMA_KWA_UFAHAMU.d', 'KISW.G7.KUSOMA.T14_KUSOMA_KWA_UFAHAMU.c']::text[], 'Mtoto hupata jibu kwenye kifungu na huchagua lile linalojibu swali lote, wala hachagui jambo dogo, kinyume au jambo lisilomo kwenye matini. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika matini ya pili"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.KUANDI.T14_INSHA_YA_MAELEKEZO.MAELEKEZO', 'KISW.G7.KUANDI.T14_INSHA_YA_MAELEKEZO', 'kiswahili', 7, 'Tambua na andika insha ya maelekezo', ARRAY['KISW.G7.KUANDI.T14_INSHA_YA_MAELEKEZO.a', 'KISW.G7.KUANDI.T14_INSHA_YA_MAELEKEZO.b', 'KISW.G7.KUANDI.T14_INSHA_YA_MAELEKEZO.c', 'KISW.G7.KUANDI.T14_INSHA_YA_MAELEKEZO.d']::text[], 'Tells insha ya maelekezo from other kinds of writing and its parts, and writes instructions with their purpose, the materials, the steps in order as commands, and safety warnings; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.SARUFI.T14_UKUBWA_WA_NOMINO.UKUBWA', 'KISW.G7.SARUFI.T14_UKUBWA_WA_NOMINO', 'kiswahili', 7, 'Tambua nomino katika hali ya ukubwa', ARRAY['KISW.G7.SARUFI.T14_UKUBWA_WA_NOMINO.a', 'KISW.G7.SARUFI.T14_UKUBWA_WA_NOMINO.b', 'KISW.G7.SARUFI.T14_UKUBWA_WA_NOMINO.c']::text[], 'Mtoto hutambua hali ya ukubwa (jibwa, jitu, jumba), viambishi vya ji- na ma- vya ukubwa, na hutumia nomino ipasavyo. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.KUSIKI.T15_KUSIKILIZA_HABARI_NA.LS_HABARI', 'KISW.G7.KUSIKI.T15_KUSIKILIZA_HABARI_NA', 'kiswahili', 7, 'Tambua masuala na msamiati katika habari aliyosikiliza', ARRAY['KISW.G7.KUSIKI.T15_KUSIKILIZA_HABARI_NA.a', 'KISW.G7.KUSIKI.T15_KUSIKILIZA_HABARI_NA.b', 'KISW.G7.KUSIKI.T15_KUSIKILIZA_HABARI_NA.d', 'KISW.G7.KUSIKI.T15_KUSIKILIZA_HABARI_NA.c']::text[], 'Mtoto hukumbuka alichosikia na huchagua jibu linalolingana na matini yote, wala hachagui jambo dogo, kinyume au jambo lisilomo kwenye matini. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika matini ya pili"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.KUSOMA.T15_UFUPISHO.RS_UFUPISHO', 'KISW.G7.KUSOMA.T15_UFUPISHO', 'kiswahili', 7, 'Eleza ujumbe wa kifungu kwa ufupi', ARRAY['KISW.G7.KUSOMA.T15_UFUPISHO.a', 'KISW.G7.KUSOMA.T15_UFUPISHO.b', 'KISW.G7.KUSOMA.T15_UFUPISHO.c']::text[], 'Mtoto hupata jibu kwenye kifungu na huchagua lile linalojibu swali lote, wala hachagui jambo dogo, kinyume au jambo lisilomo kwenye matini. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika matini ya pili"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.KUANDI.T15_KUANDIKA_KIDIJITALI.BARUAPEPE_RAFIKI', 'KISW.G7.KUANDI.T15_KUANDIKA_KIDIJITALI', 'kiswahili', 7, 'Andika baruapepe kwa rafiki kwa ujumbe, lugha na muundo ufaao', ARRAY['KISW.G7.KUANDI.T15_KUANDIKA_KIDIJITALI.a', 'KISW.G7.KUANDI.T15_KUANDIKA_KIDIJITALI.b', 'KISW.G7.KUANDI.T15_KUANDIKA_KIDIJITALI.c', 'KISW.G7.KUANDI.T15_KUANDIKA_KIDIJITALI.d']::text[], 'Tells baruapepe from other kinds of writing and its parts, and writes an email with the receiver''s address, a short subject, a greeting, the message in correct Kiswahili and a closing; the teacher marks the writing with the KICD rubric, and in the app the child picks the right sentence, order or part in 8 of 10 new items.', '["chagua sentensi ifaayo","panga sehemu au matukio","tambua kosa katika insha","kuandika (mwalimu anasahihisha)"]'::jsonb, '["application","creation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('KISW.G7.SARUFI.T15_USEMI_HALISI_NA_USEM.USEMI', 'KISW.G7.SARUFI.T15_USEMI_HALISI_NA_USEM', 'kiswahili', 7, 'Badilisha usemi halisi kuwa usemi wa taarifa', ARRAY['KISW.G7.SARUFI.T15_USEMI_HALISI_NA_USEM.a', 'KISW.G7.SARUFI.T15_USEMI_HALISI_NA_USEM.b', 'KISW.G7.SARUFI.T15_USEMI_HALISI_NA_USEM.c']::text[], 'Mtoto hutambua usemi halisi (maneno ya msemaji kwa alama za usemi) na wa taarifa, na hubadilisha mtu na wakati ipasavyo. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["chagua jibu sahihi","chagua jibu katika hadithi fupi","tafuta hatua yenye kosa"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
