INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T1_KUSIKILIZA_NA_KUJIBU.MAZUNGUMZO.M7_ORL_REPLY_T1', 'KISW.G7.KUSIKI.T1_KUSIKILIZA_NA_KUJIBU.MAZUNGUMZO', 'Replies with one word and gives nothing back, so the conversation stops.', '{"question":"Rafiki anakuuliza: \"Unafanyaje kudumisha usafi wako?\" Jibu lipi linaendeleza mazungumzo?","wrong_answer":"Sijui.","correct_answer":"Ninaoga kila siku na kufua nguo zangu. Wewe je?"}'::jsonb, 'The child answers questions as in a test.', 'The question "Rafiki anakuuliza: "Unafanyaje kudumisha usafi wako?" Jibu lipi linaendeleza mazungumzo?" with "Sijui." among the options.', 'Practise answer + one detail + a question back.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T1_KUSIKILIZA_NA_KUJIBU.MAZUNGUMZO.M7_ORL_INTERRUPT_T1', 'KISW.G7.KUSIKI.T1_KUSIKILIZA_NA_KUJIBU.MAZUNGUMZO', 'Interrupts the speaker before he finishes.', '{"question":"Mwenzako bado anazungumza na una jambo la kusema. Ufanye nini?","wrong_answer":"mkatize ili usisahau","correct_answer":"subiri amalize, kisha uombe nafasi"}'::jsonb, 'The child fears losing his idea.', 'The question "Mwenzako bado anazungumza na una jambo la kusema. Ufanye nini?" with "mkatize ili usisahau" among the options.', 'Note the idea on paper; wait for the pause.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T1_KUSIKILIZA_NA_KUJIBU.MAZUNGUMZO.M7_ORL_EYES_T1', 'KISW.G7.KUSIKI.T1_KUSIKILIZA_NA_KUJIBU.MAZUNGUMZO', 'Listens or speaks without looking at the other person (looks down or away).', '{"question":"Ni ishara ipi inaonyesha unasikiliza kwa makini?","wrong_answer":"kuangalia chini muda wote","correct_answer":"kumwangalia mzungumzaji na kutikisa kichwa"}'::jsonb, 'Looking away is a sign of respect at home for some children; in class talk it reads as not listening.', 'The question "Ni ishara ipi inaonyesha unasikiliza kwa makini?" with "kuangalia chini muda wote" among the options.', 'Practise in pairs: listen with eyes on the speaker and nods; then swap.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T1_KUSIKILIZA_NA_KUJIBU.MAZUNGUMZO.M7_ORL_OFFTOPIC_T1', 'KISW.G7.KUSIKI.T1_KUSIKILIZA_NA_KUJIBU.MAZUNGUMZO', 'Answers or speaks on something other than the topic (usafi wa kibinafsi).', '{"question":"Mada ni usafi wa kibinafsi. Ni mchango upi unafaa?","wrong_answer":"Jana nilitazama filamu nzuri sana.","correct_answer":"Tunaweza kuchangia usafi wa kibinafsi kwa njia hii..."}'::jsonb, 'The child says what is on his mind.', 'The question "Mada ni usafi wa kibinafsi. Ni mchango upi unafaa?" with "Jana nilitazama filamu nzuri sana." among the options.', 'Repeat the topic before speaking; link your point to it in the first sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.RS_HABARI.M_KS7_RS_HABARI_DETAIL', 'KISW.G7.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.RS_HABARI', 'Picks one small detail instead of the answer asked for.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lijibu swali lote, si jambo moja dogo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.RS_HABARI.M_KS7_RS_HABARI_OPPOSITE', 'KISW.G7.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.RS_HABARI', 'Picks the opposite of what the text says.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lipatane na matini, si kinyume chake.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
