INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.RS_MSAMIATI.M_KS7_RS_MSAMIATI_NOTSAID', 'KISW.G7.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.RS_MSAMIATI', 'Picks something the text does not say.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lipatikane kwenye matini, si kuongezwa kutoka nje.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.RS_HABARI.M7_HAB_RS_HABARI', 'KISW.G7.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.RS_HABARI', 'Answers a "why" question with a "what" (an event, not its reason).', '{"question":"Kwa nini mhusika alikimbia nyumbani?","wrong_answer":"alikimbia nyumbani","correct_answer":"kwa sababu aliogopa mbwa wa jirani"}'::jsonb, 'The child finds the sentence with the words of the question and copies the event.', 'The question "Kwa nini mhusika alikimbia nyumbani?" with "alikimbia nyumbani" among the options.', 'Underline the question word: nini, nani, wapi, lini, kwa nini; the answer must fit it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.RS_MATUKIO.M7_MAT_RS_MATUKIO', 'KISW.G7.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.RS_MATUKIO', 'Orders the events as they are told in the question or the options, not as they happen in the passage.', '{"question":"Ni tukio lipi lilitokea kwanza katika kifungu?","wrong_answer":"tukio lililotajwa kwanza katika swali","correct_answer":"tukio la kwanza katika kifungu"}'::jsonb, 'The order of the options is taken for the order of the story.', 'The question "Ni tukio lipi lilitokea kwanza katika kifungu?" with "tukio lililotajwa kwanza katika swali" among the options.', 'Number the events in the margin of the passage before looking at the options.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.RS_UTABIRI.M7_UTB_RS_UTABIRI', 'KISW.G7.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.RS_UTABIRI', 'Predicts with no clue from the passage, from what he wishes would happen.', '{"question":"Kutokana na kifungu, nini kitatokea baadaye?","wrong_answer":"mhusika atakuwa tajiri sana","correct_answer":"jibu linalotokana na vidokezo vya kifungu"}'::jsonb, 'Prediction is taken as imagination.', 'The question "Kutokana na kifungu, nini kitatokea baadaye?" with "mhusika atakuwa tajiri sana" among the options.', 'Every prediction needs a clue: "kwa sababu kifungu kinasema..."', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.RS_MSAMIATI.M7_MSM_RS_MSAMIATI', 'KISW.G7.KUSOMA.T1_KUSOMA_KWA_UFAHAMU.RS_MSAMIATI', 'Gives the meaning of a look-alike word, or the everyday meaning where the passage means another.', '{"question":"Katika kifungu, neno \"kupiga\" katika \"alipiga simu\" lina maana gani?","wrong_answer":"kumpiga mtu","correct_answer":"kuwasiliana kwa simu"}'::jsonb, 'The child knows one meaning and does not test it against the sentence.', 'The question "Katika kifungu, neno "kupiga" katika "alipiga simu" lina maana gani?" with "kumpiga mtu" among the options.', 'Put each meaning into the sentence; keep the one that fits.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T1_VIAKIFISHI.HERUFI_KUBWA.M_KS7_HK_JINA', 'KISW.G7.KUANDI.T1_VIAKIFISHI.HERUFI_KUBWA', 'Does not capitalise a name.', '{"question":"Ni sentensi ipi imeandikwa sawa?","wrong_answer":"tuliona nairobi jana.","correct_answer":"Tuliona Nairobi jana."}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "tuliona nairobi jana." next to the right answer and ask the question again in a new sentence.', 'Sentensi huanza kwa herufi kubwa, na majina ya pekee pia.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T1_VIAKIFISHI.HERUFI_KUBWA.M_KS7_HK_KIKOMO', 'KISW.G7.KUANDI.T1_VIAKIFISHI.HERUFI_KUBWA', 'Leaves out the full stop.', '{"question":"Sentensi ya kawaida huisha kwa nini?","wrong_answer":"kiulizi","correct_answer":"kikomo"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "kiulizi" next to the right answer and ask the question again in a new sentence.', 'Sentensi ya kawaida huisha kwa kikomo (.).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T1_VIAKIFISHI.HERUFI_KUBWA.M_KS7_HK_KATIKATI', 'KISW.G7.KUANDI.T1_VIAKIFISHI.HERUFI_KUBWA', 'Capitalises words in the middle for no reason.', '{"question":"Ni sentensi ipi ina herufi kubwa isiyofaa?","wrong_answer":"Mama alinunua Mkate.","correct_answer":"Mama alinunua mkate."}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Mama alinunua Mkate." next to the right answer and ask the question again in a new sentence.', 'Herufi kubwa si kwa nomino ya kawaida katikati ya sentensi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T1_VIAKIFISHI.HERUFI_KUBWA.M7_HK_ABBREV', 'KISW.G7.KUANDI.T1_VIAKIFISHI.HERUFI_KUBWA', 'Leaves out the full stop of an abbreviation, or writes it in a small letter (bw for Bw., s.l.p for S.L.P.).', '{"question":"Ni ipi imeandikwa sawa?","wrong_answer":"bw Otieno, s.l.p 20","correct_answer":"Bw. Otieno, S.L.P. 20"}'::jsonb, 'Abbreviations are copied from phone messages without their marks.', 'The question "Ni ipi imeandikwa sawa?" with "bw Otieno, s.l.p 20" among the options.', 'Make a list of common abbreviations with their capital and full stop (Bw., Bi., Dkt., S.L.P.).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T1_AINA_ZA_NOMINO.NOMINO_PEKEE.M_KS7_NP_KAWAIDA_KUBWA', 'KISW.G7.SARUFI.T1_AINA_ZA_NOMINO.NOMINO_PEKEE', 'Writes a common noun with a capital letter.', '{"question":"Ni nomino ipi ni ya pekee?","wrong_answer":"mji","correct_answer":"Kisumu"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "mji" next to the right answer and ask the question again in a new sentence.', 'Nomino ya pekee ni jina mahususi la mtu au mahali, kama Kisumu.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T1_AINA_ZA_NOMINO.NOMINO_PEKEE.M_KS7_NP_PEKEE_NDOGO', 'KISW.G7.SARUFI.T1_AINA_ZA_NOMINO.NOMINO_PEKEE', 'Writes a proper noun with a small letter.', '{"question":"Nomino ya pekee huandikwa kwa herufi gani mwanzoni?","wrong_answer":"Herufi ndogo","correct_answer":"Herufi kubwa"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Herufi ndogo" next to the right answer and ask the question again in a new sentence.', 'Nomino ya pekee huanza kwa herufi kubwa.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T1_AINA_ZA_NOMINO.NOMINO_PEKEE.M_KS7_NP_JINA_JUMLA', 'KISW.G7.SARUFI.T1_AINA_ZA_NOMINO.NOMINO_PEKEE', 'Thinks a general name like mwalimu is a proper noun.', '{"question":"Ni nomino ipi ni ya kawaida?","wrong_answer":"Wanjiru","correct_answer":"kijiji"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Wanjiru" next to the right answer and ask the question again in a new sentence.', 'Nomino ya kawaida ni jina la jumla, kama kijiji.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T1_AINA_ZA_NOMINO.NOMINO_PEKEE.M7_NP_TITLE_NAME', 'KISW.G7.SARUFI.T1_AINA_ZA_NOMINO.NOMINO_PEKEE', 'Writes a title before a name with a small letter, or a title alone with a capital (daktari Otieno, Daktari alikuja).', '{"question":"Ni sentensi ipi imeandikwa sawa?","wrong_answer":"Tulimwona daktari Otieno jana.","correct_answer":"Tulimwona Daktari Otieno jana."}'::jsonb, 'The child knows names take capitals but treats the title as a common word even when it is part of the name.', 'The question "Ni sentensi ipi imeandikwa sawa?" with "Tulimwona daktari Otieno jana." among the options.', 'A title joined to a name is part of the name: Daktari Otieno, Mwalimu Akinyi; alone it is common: daktari alikuja.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T2_KUSIKILIZA_KWA_KINA.MATAMSHI.M7_MAT_SWAP_T2', 'KISW.G7.KUSIKI.T2_KUSIKILIZA_KWA_KINA.MATAMSHI', 'Hears or says /th/ for /dh/, so dhamini (to sponsor or guarantee) becomes thamini (to value).', '{"question":"Mwalimu anasema: \"dhamini\". Umesikia neno lipi?","wrong_answer":"thamini","correct_answer":"dhamini"}'::jsonb, 'Many Kenyan speakers say z for dh (zahabu) and s for th (sumuni) because their first languages lack these Arabic-origin sounds; the child then cannot tell dh from th either.', 'The question "Mwalimu anasema: "dhamini". Umesikia neno lipi?" with "thamini" among the options.', 'Say the pair slowly with a hand on the throat (or watching the lips); the child says which word was heard before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T2_KUSIKILIZA_KWA_KINA.MATAMSHI.M7_MAT_SPELL_T2', 'KISW.G7.KUSIKI.T2_KUSIKILIZA_KWA_KINA.MATAMSHI', 'Writes the word with the letter of the other sound (thibiti where dhibiti is meant).', '{"question":"Jaza pengo: ___ maana yake ni \"to control\".","wrong_answer":"thibiti","correct_answer":"dhibiti"}'::jsonb, 'The child spells as he speaks; if the two sounds are one sound in his speech, the letter is a guess.', 'The question "Jaza pengo: ___ maana yake ni "to control"." with "thibiti" among the options.', 'Pair each spelling with its meaning on a card; the child sorts the cards by meaning, then by letter.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T2_KUSIKILIZA_KWA_KINA.MATAMSHI.M7_MAT_SAME_T2', 'KISW.G7.KUSIKI.T2_KUSIKILIZA_KWA_KINA.MATAMSHI', 'Thinks the two words are one word said in two ways, with one meaning.', '{"question":"\"dhibiti\" na \"thibiti\" ni maneno yenye maana moja?","wrong_answer":"ndiyo","correct_answer":"hapana"}'::jsonb, 'The child has heard both said by different people for the same thing and takes the difference for an accent.', 'The question ""dhibiti" na "thibiti" ni maneno yenye maana moja?" with "ndiyo" among the options.', 'Use both words in two sentences that cannot swap: the child says which sentence breaks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T2_KUSIKILIZA_KWA_KINA.MATAMSHI.M7_MAT_TWISTER_T2', 'KISW.G7.KUSIKI.T2_KUSIKILIZA_KWA_KINA.MATAMSHI', 'Takes any long sentence for a kitanzandimi, though it does not repeat the target sounds.', '{"question":"Ni kipi ni kitanzandimi?","wrong_answer":"Mboga na matunda hujenga mwili.","correct_answer":"Dhahabu ya thamani ya Dhahiri ilithibitishwa na dhamana ya thelathini."}'::jsonb, 'The child thinks a kitanzandimi is any sentence that is hard to say, not one built by repeating close sounds.', 'The question "Ni kipi ni kitanzandimi?" with "Mboga na matunda hujenga mwili." among the options.', 'Underline the target sounds in the real kitanzandimi; count them; the ordinary sentence has few or none.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T2_KUSIKILIZA_KWA_KINA.MATAMSHI.M7_MAT_SYLL_T2', 'KISW.G7.KUSIKI.T2_KUSIKILIZA_KWA_KINA.MATAMSHI', 'Breaks the word into syllables at the wrong place, so the target sound is lost (dh-amini read as two wrong parts).', '{"question":"Neno \"dhamini\" lina silabi zipi?","wrong_answer":"d-hamini","correct_answer":"dha-mi-ni"}'::jsonb, 'In Kiswahili every syllable ends in a vowel, and a nasal with its consonant (nd, mb, nj, ng) starts one syllable; the child splits by letters, not by sound.', 'The question "Neno "dhamini" lina silabi zipi?" with "d-hamini" among the options.', 'Clap the word: one clap per vowel; the nasal goes with the consonant after it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T2_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M7_MAP_COVER_T2', 'KISW.G7.KUSOMA.T2_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Chooses a book by its cover picture or its thickness only.', '{"question":"Unataka kusoma kuhusu lishe bora. Utachaguaje kitabu?","wrong_answer":"kwa picha nzuri ya jalada","correct_answer":"kwa kusoma anwani, maelezo ya nyuma na ukurasa wa kwanza"}'::jsonb, 'Nobody has shown the child the title, the blurb and the first page as clues.', 'The question "Unataka kusoma kuhusu lishe bora. Utachaguaje kitabu?" with "kwa picha nzuri ya jalada" among the options.', 'Hold up two books; read the title and the back of each aloud; the child chooses and says which clue decided it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T2_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M7_MAP_LEVEL_T2', 'KISW.G7.KUSOMA.T2_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Chooses a text far above his reading level and gives up after a page.', '{"question":"Ukisoma ukurasa wa kwanza wa \"Sahani Yenye Rangi\" na hujui maneno mengi sana, ufanye nini?","wrong_answer":"endelea tu hata kama huelewi","correct_answer":"chagua matini nyingine iliyo ya kiwango chako"}'::jsonb, 'The child thinks a harder book is a better book, or chooses the book a friend chose.', 'The question "Ukisoma ukurasa wa kwanza wa "Sahani Yenye Rangi" na hujui maneno mengi sana, ufanye nini?" with "endelea tu hata kama huelewi" among the options.', 'The five-finger check: on one page, a finger for each unknown word; five fingers means the book is too hard for now.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T2_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M7_MAP_TITLEMSG_T2', 'KISW.G7.KUSOMA.T2_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Gives the title as the message of the text.', '{"question":"Ujumbe wa matini \"Sahani Yenye Rangi\" ni upi?","wrong_answer":"Sahani Yenye Rangi","correct_answer":"Mlo kamili wenye vyakula vya aina mbalimbali hujenga afya."}'::jsonb, 'The title is the only sentence about the whole text that the child is sure of.', 'The question "Ujumbe wa matini "Sahani Yenye Rangi" ni upi?" with "Sahani Yenye Rangi" among the options.', 'Ask what the writer wants the reader to learn or do; the title only names the topic.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T2_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M7_MAP_DETAIL_T2', 'KISW.G7.KUSOMA.T2_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Gives one detail of the text as its message.', '{"question":"Ni ipi ni ujumbe wa matini kuhusu lishe bora?","wrong_answer":"Mama alipika sukumawiki na ugali.","correct_answer":"Mlo kamili wenye vyakula vya aina mbalimbali hujenga afya."}'::jsonb, 'The detail was striking and is remembered; the child has not asked what the whole text is about.', 'The question "Ni ipi ni ujumbe wa matini kuhusu lishe bora?" with "Mama alipika sukumawiki na ugali." among the options.', 'Two boxes: "ujumbe" (one) and "maelezo" (many); the child sorts sentences from the text.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T2_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M7_MAP_KIND_T2', 'KISW.G7.KUSOMA.T2_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Does not tell one kind of text from another (takes a newspaper report for a story, or a poem for a story).', '{"question":"Matini yenye beti na mishororo ni ya aina gani?","wrong_answer":"hadithi","correct_answer":"shairi"}'::jsonb, 'The child has met most texts as "kitabu" and has not been shown the signs of each kind.', 'The question "Matini yenye beti na mishororo ni ya aina gani?" with "hadithi" among the options.', 'Lay out a story, a poem, a newspaper page and a dictionary; the child names one sign of each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T2_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M7_MAP_WORD_T2', 'KISW.G7.KUSOMA.T2_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Guesses a new word from how it looks, not from the sentence it is in (mlo).', '{"question":"Katika matini: \"Mlo kamili una wanga, protini, vitamini na madini.\" Neno \"mlo\" lina maana gani?","wrong_answer":"mlango wa nyumba","correct_answer":"chakula anachokula mtu kwa wakati mmoja"}'::jsonb, 'The child matches the word to a word it looks like instead of reading the sentence around it.', 'The question "Katika matini: "Mlo kamili una wanga, protini, vitamini na madini." Neno "mlo" lina maana gani?" with "mlango wa nyumba" among the options.', 'Cover the word; the child reads the sentence and says what word would fit; then compares.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T2_BARUA_YA_KIRAFIKI_YA.BARUA_MWALIKO.M_KS7_BM_HITIMISHO', 'KISW.G7.KUANDI.T2_BARUA_YA_KIRAFIKI_YA.BARUA_MWALIKO', 'Puts the closing line first.', '{"question":"Barua ya kirafiki huanza kwa nini?","wrong_answer":"jina la mwandishi","correct_answer":"anwani ya mwandishi na tarehe"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jina la mwandishi" next to the right answer and ask the question again in a new sentence.', 'Barua huanza kwa anwani na tarehe, huisha kwa hitimisho na jina.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T2_BARUA_YA_KIRAFIKI_YA.BARUA_MWALIKO.M_KS7_BM_SALAMU', 'KISW.G7.KUANDI.T2_BARUA_YA_KIRAFIKI_YA.BARUA_MWALIKO', 'Uses a formal greeting in a friendly letter.', '{"question":"Ni salamu ipi inafaa barua ya kirafiki?","wrong_answer":"Mkuu wa Shule","correct_answer":"Mpendwa rafiki yangu"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Mkuu wa Shule" next to the right answer and ask the question again in a new sentence.', 'Barua ya kirafiki huanza kwa salamu ya kirafiki.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T2_BARUA_YA_KIRAFIKI_YA.BARUA_MWALIKO.M_KS7_BM_UMUHIMU', 'KISW.G7.KUANDI.T2_BARUA_YA_KIRAFIKI_YA.BARUA_MWALIKO', 'Does not know why an invitation is written.', '{"question":"Mwaliko huandikwa kwa nini?","wrong_answer":"kumkaripia mtu","correct_answer":"kumwita mtu kwenye tukio"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "kumkaripia mtu" next to the right answer and ask the question again in a new sentence.', 'Mwaliko humwita mtu kwenye tukio.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T2_BARUA_YA_KIRAFIKI_YA.KUANDIKA_MWALIKO.M7_INS_FORMAL_T2', 'KISW.G7.KUANDI.T2_BARUA_YA_KIRAFIKI_YA.KUANDIKA_MWALIKO', 'Writes to a friend in the stiff words of an official letter (Mheshimiwa, Kuhusu:, Wako mtiifu).', '{"question":"Ni salamu ipi inafaa katika barua kwa rafiki?","wrong_answer":"Mheshimiwa Bwana,","correct_answer":"Mpendwa rafiki yangu Amina,"}'::jsonb, 'The child has seen official letters at school and thinks every letter is written that way.', 'The question "Ni salamu ipi inafaa katika barua kwa rafiki?" with "Mheshimiwa Bwana," among the options.', 'Put a friendly and an official letter side by side; the child highlights the words that differ.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T2_BARUA_YA_KIRAFIKI_YA.KUANDIKA_MWALIKO.M7_INS_NOASK_T2', 'KISW.G7.KUANDI.T2_BARUA_YA_KIRAFIKI_YA.KUANDIKA_MWALIKO', 'Starts with the news straight after the greeting, with no asking after the friend (maulizo ya hali).', '{"question":"Baada ya salamu, ni sentensi ipi inafuata katika barua ya kirafiki?","wrong_answer":"Nataka kukueleza kuhusu safari yetu.","correct_answer":"Hujambo? Natumai u buheri wa afya."}'::jsonb, 'The child goes to what he wants to say, as in a text message.', 'The question "Baada ya salamu, ni sentensi ipi inafuata katika barua ya kirafiki?" with "Nataka kukueleza kuhusu safari yetu." among the options.', 'Order the parts on cards: anwani, tarehe, salamu, maulizo ya hali, ujumbe, hitimisho, jina.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T2_BARUA_YA_KIRAFIKI_YA.KUANDIKA_MWALIKO.M7_INS_DATE_T2', 'KISW.G7.KUANDI.T2_BARUA_YA_KIRAFIKI_YA.KUANDIKA_MWALIKO', 'Leaves out the date or writes it in the middle of the letter.', '{"question":"Tarehe huandikwa wapi katika barua ya kirafiki?","wrong_answer":"mwishoni, baada ya jina","correct_answer":"chini ya anwani ya mwandishi, upande wa kulia juu"}'::jsonb, 'The date is not part of what the child wants to say, so he forgets it.', 'The question "Tarehe huandikwa wapi katika barua ya kirafiki?" with "mwishoni, baada ya jina" among the options.', 'Label a model letter; the child places a date card on a blank layout.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T2_BARUA_YA_KIRAFIKI_YA.KUANDIKA_MWALIKO.M7_INS_SIGN_T2', 'KISW.G7.KUANDI.T2_BARUA_YA_KIRAFIKI_YA.KUANDIKA_MWALIKO', 'Ends with "Wako mtiifu" and a full name and title, as in an official letter.', '{"question":"Ni hitimisho lipi linafaa katika barua kwa rafiki?","wrong_answer":"Wako mtiifu, Bw. Juma Hamisi","correct_answer":"Ni mimi rafiki yako, Juma"}'::jsonb, 'Again the official model is the only one the child has copied.', 'The question "Ni hitimisho lipi linafaa katika barua kwa rafiki?" with "Wako mtiifu, Bw. Juma Hamisi" among the options.', 'Collect three friendly closings and keep them in the exercise book.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T2_BARUA_YA_KIRAFIKI_YA.BARUA_MWALIKO.M7_BM_NODETAILS', 'KISW.G7.KUANDI.T2_BARUA_YA_KIRAFIKI_YA.BARUA_MWALIKO', 'Writes the invitation without the event details (what, when, where, time).', '{"question":"Ni ujumbe upi kamili wa mwaliko?","wrong_answer":"Nakualika kwenye sherehe yangu.","correct_answer":"Nakualika kwenye sherehe ya kuzaliwa kwangu Jumamosi tarehe 5 saa nane mchana nyumbani kwetu Kakamega."}'::jsonb, 'The child thinks the friend already knows the details.', 'The question "Ni ujumbe upi kamili wa mwaliko?" with "Nakualika kwenye sherehe yangu." among the options.', 'Check the invitation against nini, lini, saa ngapi, wapi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T2_AINA_ZA_NOMINO.NOMINO_MAKUNDI.M_KS7_NM_MOJA', 'KISW.G7.SARUFI.T2_AINA_ZA_NOMINO.NOMINO_MAKUNDI', 'Thinks a collective noun names one thing.', '{"question":"Ni nomino ipi ni ya makundi?","wrong_answer":"mwanafunzi","correct_answer":"kikosi"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "mwanafunzi" next to the right answer and ask the question again in a new sentence.', 'Nomino ya makundi hutaja kundi la viumbe au vitu, kama kikosi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T2_AINA_ZA_NOMINO.NOMINO_MAKUNDI.M_KS7_NM_SHIKIKA', 'KISW.G7.SARUFI.T2_AINA_ZA_NOMINO.NOMINO_MAKUNDI', 'Thinks an abstract noun can be touched.', '{"question":"Ni nomino ipi ni ya dhahania?","wrong_answer":"meza","correct_answer":"upendo"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "meza" next to the right answer and ask the question again in a new sentence.', 'Nomino ya dhahania haishikiki, kama upendo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T2_AINA_ZA_NOMINO.NOMINO_MAKUNDI.M_KS7_NM_KUNDI_DHAHANIA', 'KISW.G7.SARUFI.T2_AINA_ZA_NOMINO.NOMINO_MAKUNDI', 'Mixes collective and abstract nouns.', '{"question":"Neno jeshi ni nomino ya aina gani?","wrong_answer":"dhahania","correct_answer":"makundi"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "dhahania" next to the right answer and ask the question again in a new sentence.', 'Jeshi ni kundi la askari, kwa hiyo ni nomino ya makundi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T2_AINA_ZA_NOMINO.NOMINO_MAKUNDI.M7_NM_AGREE', 'KISW.G7.SARUFI.T2_AINA_ZA_NOMINO.NOMINO_MAKUNDI', 'Agrees the verb with the members of the group, not the group noun (Jeshi la askari wamefika).', '{"question":"Jaza: Jeshi la askari ___ kambini.","wrong_answer":"wamefika","correct_answer":"limefika"}'::jsonb, 'The child thinks of the soldiers, who are people.', 'The question "Jaza: Jeshi la askari ___ kambini." with "wamefika" among the options.', 'Find the head noun (jeshi, LI-YA); the verb agrees with it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T3_TANZU_ZA_FASIHI.FASIHI_TANZU.M_KS7_FT_SIMULIZI', 'KISW.G7.KUSIKI.T3_TANZU_ZA_FASIHI.FASIHI_TANZU', 'Thinks oral literature is written.', '{"question":"Fasihi simulizi hupitishwa kwa njia gani?","wrong_answer":"kwa maandishi","correct_answer":"kwa mdomo"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "kwa maandishi" next to the right answer and ask the question again in a new sentence.', 'Fasihi simulizi hupitishwa kwa mdomo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T3_TANZU_ZA_FASIHI.FASIHI_TANZU.M_KS7_FT_ANDISHI', 'KISW.G7.KUSIKI.T3_TANZU_ZA_FASIHI.FASIHI_TANZU', 'Thinks written literature is spoken.', '{"question":"Fasihi andishi hupitishwa kwa njia gani?","wrong_answer":"kwa mdomo","correct_answer":"kwa maandishi"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "kwa mdomo" next to the right answer and ask the question again in a new sentence.', 'Fasihi andishi huandikwa.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T3_TANZU_ZA_FASIHI.FASIHI_TANZU.M_KS7_FT_TANZU', 'KISW.G7.KUSIKI.T3_TANZU_ZA_FASIHI.FASIHI_TANZU', 'Names a non-literature item as a tanzu.', '{"question":"Ni tanzu ipi ya fasihi simulizi?","wrong_answer":"barua rasmi","correct_answer":"methali"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "barua rasmi" next to the right answer and ask the question again in a new sentence.', 'Methali ni tanzu ya fasihi simulizi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T3_TANZU_ZA_FASIHI.FASIHI_TANZU.M7_FT_TANZU_VIPERA', 'KISW.G7.KUSIKI.T3_TANZU_ZA_FASIHI.FASIHI_TANZU', 'Mixes tanzu (genres: hadithi, ushairi, semi, mazungumzo) with vipera (their kinds: hurafa, methali, vitendawili).', '{"question":"Methali ni utanzu au kipera?","wrong_answer":"utanzu","correct_answer":"kipera cha utanzu wa semi"}'::jsonb, 'Both are lists of kinds of literature.', 'The question "Methali ni utanzu au kipera?" with "utanzu" among the options.', 'Draw a tree: fasihi simulizi -> tanzu -> vipera; place each word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T3_KUSOMA_KWA_KINA.NOVELA_UTANZU.M7_FAS_GENRE_T3', 'KISW.G7.KUSOMA.T3_KUSOMA_KWA_KINA.NOVELA_UTANZU', 'Takes a novela for another kind of text (hadithi fupi) or gives the features of the other kind.', '{"question":"Ni sifa ipi ni ya novela?","wrong_answer":"huwa na beti na mishororo","correct_answer":"ni hadithi ndefu kuliko hadithi fupi yenye wahusika na matukio mengi"}'::jsonb, 'The child has met several kinds of literature and keeps one list of features for all of them.', 'The question "Ni sifa ipi ni ya novela?" with "huwa na beti na mishororo" among the options.', 'Lay a novela and a hadithi fupi side by side and list what only the novela has.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T3_KUSOMA_KWA_KINA.NOVELA_UTANZU.M7_FAS_ORAL_T3', 'KISW.G7.KUSOMA.T3_KUSOMA_KWA_KINA.NOVELA_UTANZU', 'Calls a novela oral literature (fasihi simulizi) because it can be read aloud or acted.', '{"question":"Novela ni utanzu wa fasihi ipi?","wrong_answer":"fasihi simulizi","correct_answer":"fasihi andishi"}'::jsonb, 'Plays are acted and poems are recited, so the child thinks of them as spoken.', 'The question "Novela ni utanzu wa fasihi ipi?" with "fasihi simulizi" among the options.', 'Ask: was it first composed in writing by a known author? Then it is fasihi andishi, even when performed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T3_KUSOMA_KWA_KINA.NOVELA_UTANZU.M7_FAS_ONEFEATURE_T3', 'KISW.G7.KUSOMA.T3_KUSOMA_KWA_KINA.NOVELA_UTANZU', 'Gives one feature only (length, or rhyme) as the whole meaning of a novela.', '{"question":"Eleza maana ya novela.","wrong_answer":"ni kitabu kirefu","correct_answer":"ni hadithi ya kubuni ndefu kuliko hadithi fupi, yenye wahusika, mandhari na ploti"}'::jsonb, 'The child remembers the most visible feature.', 'The question "Eleza maana ya novela." with "ni kitabu kirefu" among the options.', 'Build the definition from three parts: what kind of text, its form, its purpose.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T3_KUSOMA_KWA_KINA.NOVELA_UTANZU.M7_FAS_AUTHOR_T3', 'KISW.G7.KUSOMA.T3_KUSOMA_KWA_KINA.NOVELA_UTANZU', 'Takes the narrator or a character for the author of the novela.', '{"question":"Ni nani mwandishi wa \"Kisima cha Matumaini\"?","wrong_answer":"Neema","correct_answer":"mtunzi aliyetajwa jaladani"}'::jsonb, 'The narrator speaks as "I" and the child takes that voice for the writer.', 'The question "Ni nani mwandishi wa "Kisima cha Matumaini"?" with "Neema" among the options.', 'Find the author''s name on the cover; the narrator and characters are inside the story.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T3_INSHA_ZA_KUBUNI.KUBUNI_VIDOKEZO.M7_INS_VIDOKEZO_T3', 'KISW.G7.KUANDI.T3_INSHA_ZA_KUBUNI.KUBUNI_VIDOKEZO', 'Plans with points (vidokezo) that do not belong to the title, or writes the insha without using the points planned.', '{"question":"Ni kidokezo kipi hakifai kwa insha \"Simba Aliyetoroka Mbugani\"?","wrong_answer":"Bei ya sukari imepanda dukani.","correct_answer":"simba alitoroka"}'::jsonb, 'The child lists whatever comes to mind and does not check each point against the title.', 'The question "Ni kidokezo kipi hakifai kwa insha "Simba Aliyetoroka Mbugani"?" with "Bei ya sukari imepanda dukani." among the options.', 'Write the title at the top of the plan; tick each point only if it helps to tell that story.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T3_INSHA_ZA_KUBUNI.KUBUNI_VIDOKEZO.M7_INS_TITLE_T3', 'KISW.G7.KUANDI.T3_INSHA_ZA_KUBUNI.KUBUNI_VIDOKEZO', 'Writes the title as a full sentence with a full stop, or leaves it out.', '{"question":"Ni anwani ipi imeandikwa ipasavyo?","wrong_answer":"simba aliyetoroka mbugani.","correct_answer":"SIMBA ALIYETOROKA MBUGANI"}'::jsonb, 'The child treats the title as the first sentence of the insha.', 'The question "Ni anwani ipi imeandikwa ipasavyo?" with "simba aliyetoroka mbugani." among the options.', 'Show where the title sits and how it is written (herufi kubwa, no kikomo, often underlined).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T3_INSHA_ZA_KUBUNI.KUBUNI_VIDOKEZO.M7_INS_ORDER_T3', 'KISW.G7.KUANDI.T3_INSHA_ZA_KUBUNI.KUBUNI_VIDOKEZO', 'Puts the events in an order that cannot have happened (the end before the start), with no linking words.', '{"question":"Ni mpangilio upi wa matukio unafaa katika insha \"Simba Aliyetoroka Mbugani\"?","wrong_answer":"simba alirudishwa mbugani, walinzi wa wanyama walifika, wanakijiji walitahadharishwa, simba alitoroka","correct_answer":"simba alitoroka, wanakijiji walitahadharishwa, walinzi wa wanyama walifika, simba alirudishwa mbugani"}'::jsonb, 'The child writes events as they come to mind; nobody has asked for a plan first.', 'The question "Ni mpangilio upi wa matukio unafaa katika insha "Simba Aliyetoroka Mbugani"?" with "simba alirudishwa mbugani, walinzi wa wanyama walifika, wanakijiji walitahadharishwa, simba alitoroka" among the options.', 'Plan with three boxes (mwanzo, kati, mwisho) and linking words (kwanza, kisha, hatimaye) before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T3_INSHA_ZA_KUBUNI.KUBUNI_VIDOKEZO.M7_INS_END_T3', 'KISW.G7.KUANDI.T3_INSHA_ZA_KUBUNI.KUBUNI_VIDOKEZO', 'Ends the insha abruptly ("Mwisho." or "The end") with no closing paragraph (hitimisho).', '{"question":"Ni ipi ni hitimisho bora la insha \"Simba Aliyetoroka Mbugani\"?","wrong_answer":"Mwisho.","correct_answer":"Tangu siku hiyo, nimejifunza mengi kuhusu jambo hili."}'::jsonb, 'Storybooks for young readers end with "Mwisho" and the child copies that.', 'The question "Ni ipi ni hitimisho bora la insha "Simba Aliyetoroka Mbugani"?" with "Mwisho." among the options.', 'Show three endings; the child picks the one that closes the main idea or the lesson.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T3_AINA_ZA_NOMINO.NOMINO_WINGI.M_KS7_NW_KITENZI_JINA', 'KISW.G7.SARUFI.T3_AINA_ZA_NOMINO.NOMINO_WINGI', 'Does not know the ku- verbal noun.', '{"question":"Ni kitenzi-jina kipi?","wrong_answer":"mwimbaji","correct_answer":"kuimba"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "mwimbaji" next to the right answer and ask the question again in a new sentence.', 'Kitenzi-jina huanza kwa ku-, kama kuimba.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T3_AINA_ZA_NOMINO.NOMINO_WINGI.M_KS7_NW_MAJI_MOJA', 'KISW.G7.SARUFI.T3_AINA_ZA_NOMINO.NOMINO_WINGI', 'Treats maji as singular.', '{"question":"Ni nomino ipi ya wingi?","wrong_answer":"kiti","correct_answer":"maji"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "kiti" next to the right answer and ask the question again in a new sentence.', 'Maji ni nomino ya wingi; haina umoja.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T3_AINA_ZA_NOMINO.NOMINO_WINGI.M_KS7_NW_KUSOMA', 'KISW.G7.SARUFI.T3_AINA_ZA_NOMINO.NOMINO_WINGI', 'Calls the verbal noun a main verb only.', '{"question":"Neno kusoma katika \"Kusoma ni muhimu\" ni nini?","wrong_answer":"kitenzi kikuu","correct_answer":"kitenzi-jina"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "kitenzi kikuu" next to the right answer and ask the question again in a new sentence.', 'Hapa kusoma ni jina la jambo, kwa hiyo ni kitenzi-jina.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T3_AINA_ZA_NOMINO.NOMINO_WINGI.M7_NW_KU_AGREE', 'KISW.G7.SARUFI.T3_AINA_ZA_NOMINO.NOMINO_WINGI', 'Gives a verbal noun the agreement of a person (Kusoma kwake anapendeza).', '{"question":"Jaza: Kuimba kwake ___ (kunapendeza / anapendeza).","wrong_answer":"anapendeza","correct_answer":"kunapendeza"}'::jsonb, 'The child thinks of the singer, not the singing.', 'The question "Jaza: Kuimba kwake ___ (kunapendeza / anapendeza)." with "anapendeza" among the options.', 'The verbal noun is in KU-KU: everything agreeing with it takes ku- / kw-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T4_NYIMBO.NYIMBO.M7_FSI_KIND_T4', 'KISW.G7.KUSIKI.T4_NYIMBO.NYIMBO', 'Mixes the two kinds (bembelezi and wimbo wa watoto) and their purposes.', '{"question":"\"Lala mtoto lala, mama yuaja, lala\" ni nyimbo ya aina gani?","wrong_answer":"wimbo wa watoto","correct_answer":"bembelezi"}'::jsonb, 'Both are nyimbo; the child has not fixed what each is for and when it is used.', 'The question ""Lala mtoto lala, mama yuaja, lala" ni nyimbo ya aina gani?" with "wimbo wa watoto" among the options.', 'List for each kind: who uses it, when, and why; sort examples.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T4_NYIMBO.NYIMBO.M7_FSI_WRITTEN_T4', 'KISW.G7.KUSIKI.T4_NYIMBO.NYIMBO', 'Calls nyimbo written literature because it is found in a textbook.', '{"question":"Nyimbo ni utanzu wa fasihi ipi?","wrong_answer":"fasihi andishi","correct_answer":"fasihi simulizi"}'::jsonb, 'The child meets it on the page in class.', 'The question "Nyimbo ni utanzu wa fasihi ipi?" with "fasihi andishi" among the options.', 'Ask: who first made it, and how was it passed on? By mouth, from one generation to the next.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T4_NYIMBO.NYIMBO.M7_FSI_OCCASION_T4', 'KISW.G7.KUSIKI.T4_NYIMBO.NYIMBO', 'Places the nyimbo in the wrong occasion (a lullaby at a work party, a work song at a funeral).', '{"question":"Bembelezi hutumika lini?","wrong_answer":"wakati wowote","correct_answer":"mama anapombembeleza mtoto alale"}'::jsonb, 'The occasion is not stated in the text, and the child does not link form to use.', 'The question "Bembelezi hutumika lini?" with "wakati wowote" among the options.', 'Act out the occasion; which kind fits it?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T4_NYIMBO.NYIMBO.M7_FSI_MESSAGE_T4', 'KISW.G7.KUSIKI.T4_NYIMBO.NYIMBO', 'Gives a line of the text as its message instead of the lesson.', '{"question":"Ujumbe wa \"Lala mtoto lala, mama yuaja, lala\" ni upi?","wrong_answer":"Lala mtoto lala, mama yuaja, lala","correct_answer":"mtoto atulie na alale kwa amani."}'::jsonb, 'Copying a line feels like a safe answer.', 'The question "Ujumbe wa "Lala mtoto lala, mama yuaja, lala" ni upi?" with "Lala mtoto lala, mama yuaja, lala" among the options.', 'Close the text; say the lesson in your own words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T4_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M7_UFS_WORDBYWORD_T4', 'KISW.G7.KUSOMA.T4_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads word by word or syllable by syllable, so the sentence has no meaning when heard.', '{"question":"Ni usomaji upi ni wa ufasaha: \"Misitu, mito na madini ni maliasili ya nchi yetu.\"?","wrong_answer":"Misitu, ... mito ... na ... madini ... ni ... maliasili ... ya ... nchi ... yetu.","correct_answer":"Misitu, mito na madini ni maliasili ya nchi yetu."}'::jsonb, 'The child is still decoding each word and has not yet learnt to read a phrase as one piece.', 'The question "Ni usomaji upi ni wa ufasaha: "Misitu, mito na madini ni maliasili ya nchi yetu."?" with "Misitu, ... mito ... na ... madini ... ni ... maliasili ... ya ... nchi ... yetu." among the options.', 'Echo reading: the teacher reads a phrase, the child repeats it as one breath; then phrase-cut the passage with slashes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T4_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M7_UFS_RACE_T4', 'KISW.G7.KUSOMA.T4_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads as fast as possible and thinks the fastest reader is the best.', '{"question":"Ni kasi ipi ifaayo ya kusoma kifungu darasani?","wrong_answer":"haraka iwezekanavyo","correct_answer":"kasi ya kuzungumza, ili kila neno lisikike"}'::jsonb, 'Reading races in class reward speed; the child has not been asked whether listeners understood.', 'The question "Ni kasi ipi ifaayo ya kusoma kifungu darasani?" with "haraka iwezekanavyo" among the options.', 'Time two readings: one very fast, one at speaking pace; listeners answer one question after each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T4_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M7_UFS_FLAT_T4', 'KISW.G7.KUSOMA.T4_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads a question and an exclamation in the same flat voice as a statement.', '{"question":"Sentensi \"Je, tunatunzaje misitu yetu?\" inasomwa vipi?","wrong_answer":"kwa sauti ileile ya sentensi ya kawaida","correct_answer":"sauti hupanda mwishoni kwa sababu ni swali"}'::jsonb, 'The child looks at the words and not at the mark at the end.', 'The question "Sentensi "Je, tunatunzaje misitu yetu?" inasomwa vipi?" with "kwa sauti ileile ya sentensi ya kawaida" among the options.', 'Read the same words three ways (. ? !); the child points at the mark that matches each reading.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T4_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M7_UFS_NOPAUSE_T4', 'KISW.G7.KUSOMA.T4_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads on through the koma and the kikomo without a pause.', '{"question":"Unasoma: \"Lo, mto umekauka kabisa!\" Unasimama wapi kidogo?","wrong_answer":"hapana mahali, unasoma moja kwa moja","correct_answer":"kwenye koma na kwenye kikomo au alama ya hisi"}'::jsonb, 'The marks are read as decoration; the child has not linked them to breath.', 'The question "Unasoma: "Lo, mto umekauka kabisa!" Unasimama wapi kidogo?" with "hapana mahali, unasoma moja kwa moja" among the options.', 'Clap once at a koma, twice at a kikomo while reading together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T4_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M7_UFS_SOUND_T4', 'KISW.G7.KUSOMA.T4_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Says /l/ for /r/ or /r/ for /l/ while reading (maliasili read as maliasiri).', '{"question":"Neno \"maliasili\" linatamkwa vipi?","wrong_answer":"maliasiri","correct_answer":"maliasili"}'::jsonb, 'The first language of the child does not separate these sounds, so the reading carries the home sound.', 'The question "Neno "maliasili" linatamkwa vipi?" with "maliasiri" among the options.', 'Make a list of the passage words with the hard sound; practise them before reading the passage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T4_INSHA_ZA_KUBUNI.KUBUNI_LUGHA.M7_INS_LUGHA_T4', 'KISW.G7.KUANDI.T4_INSHA_ZA_KUBUNI.KUBUNI_LUGHA', 'Writes in plain, flat words with no language devices (tashbihi, sitiari, methali, nahau) to make the insha vivid.', '{"question":"Ni sentensi ipi ina lugha ya kiubunifu kwa insha \"Mto Uliokauka\"?","wrong_answer":"Mto ulikauka.","correct_answer":"Mto Nzoia, uliokuwa ukitiririka kama nyoka mrefu wa fedha, sasa ulikuwa mchanga mtupu."}'::jsonb, 'The child has not been shown how devices from fasihi can be used in his own writing.', 'The question "Ni sentensi ipi ina lugha ya kiubunifu kwa insha "Mto Uliokauka"?" with "Mto ulikauka." among the options.', 'Collect three devices from a class reader; rewrite one plain sentence with each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T4_INSHA_ZA_KUBUNI.KUBUNI_LUGHA.M7_INS_WAHUSIKA_T4', 'KISW.G7.KUANDI.T4_INSHA_ZA_KUBUNI.KUBUNI_LUGHA', 'Gives the characters no names, no features and no words of their own, so the reader cannot see them.', '{"question":"Ni sentensi ipi inamjenga mhusika vizuri katika insha \"Mto Uliokauka\"?","wrong_answer":"Mtu mmoja alikuja.","correct_answer":"Mzee Juma, mwenye ndevu nyeupe na fimbo ya mpingo, alisimama mlangoni."}'::jsonb, 'The child thinks of the events, not the people in them.', 'The question "Ni sentensi ipi inamjenga mhusika vizuri katika insha "Mto Uliokauka"?" with "Mtu mmoja alikuja." among the options.', 'For each character: a name, one look, one trait shown by an action.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T4_INSHA_ZA_KUBUNI.KUBUNI_LUGHA.M7_INS_MANDHARI_T4', 'KISW.G7.KUANDI.T4_INSHA_ZA_KUBUNI.KUBUNI_LUGHA', 'Gives no setting (time and place) or one that does not fit the events.', '{"question":"Ni mwanzo upi unaonyesha mandhari ya insha \"Mto Uliokauka\"?","wrong_answer":"Kisa hiki kilitokea.","correct_answer":"Ilikuwa jioni ya Ijumaa katika soko la Gikomba, watu wakiwa wamesongamana."}'::jsonb, 'The child starts with the action.', 'The question "Ni mwanzo upi unaonyesha mandhari ya insha "Mto Uliokauka"?" with "Kisa hiki kilitokea." among the options.', 'Answer lini? wapi? hali gani? in the first paragraph.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T4_INSHA_ZA_KUBUNI.KUBUNI_LUGHA.M7_INS_MIX_T4', 'KISW.G7.KUANDI.T4_INSHA_ZA_KUBUNI.KUBUNI_LUGHA', 'Puts English or Sheng words in the insha (tulienda kwa party, mathe, form).', '{"question":"Ni sentensi ipi imeandikwa kwa Kiswahili sanifu?","wrong_answer":"Mathe alinipea form ya kujaza.","correct_answer":"Mama alinipa fomu ya kujaza."}'::jsonb, 'The child speaks a mixed language at home and with friends and does not notice the switch in writing.', 'The question "Ni sentensi ipi imeandikwa kwa Kiswahili sanifu?" with "Mathe alinipea form ya kujaza." among the options.', 'Underline each non-Kiswahili word; find the Kiswahili word together (mama, sherehe, fomu).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T4_NYAKATI_NA_HALI.NYAKATI_MSINGI.M_KS7_NY_LI', 'KISW.G7.SARUFI.T4_NYAKATI_NA_HALI.NYAKATI_MSINGI', 'Mixes the markers -li- and -ta-.', '{"question":"Katika \"Juma alicheza jana\", wakati ni upi?","wrong_answer":"ujao","correct_answer":"uliopita"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "ujao" next to the right answer and ask the question again in a new sentence.', 'Kiambishi -li- huonyesha wakati uliopita.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T4_NYAKATI_NA_HALI.NYAKATI_MSINGI.M_KS7_NY_NA', 'KISW.G7.SARUFI.T4_NYAKATI_NA_HALI.NYAKATI_MSINGI', 'Thinks -na- is past.', '{"question":"Katika \"Mama anapika sasa\", wakati ni upi?","wrong_answer":"uliopita","correct_answer":"uliopo"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "uliopita" next to the right answer and ask the question again in a new sentence.', 'Kiambishi -na- huonyesha wakati uliopo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T4_NYAKATI_NA_HALI.NYAKATI_MSINGI.M_KS7_NY_TA', 'KISW.G7.SARUFI.T4_NYAKATI_NA_HALI.NYAKATI_MSINGI', 'Thinks -ta- is present.', '{"question":"Katika \"Tutasafiri kesho\", wakati ni upi?","wrong_answer":"uliopo","correct_answer":"ujao"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "uliopo" next to the right answer and ask the question again in a new sentence.', 'Kiambishi -ta- huonyesha wakati ujao.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T4_NYAKATI_NA_HALI.NYAKATI_MSINGI.M7_NY_TA_KW', 'KISW.G7.SARUFI.T4_NYAKATI_NA_HALI.NYAKATI_MSINGI', 'Drops the kw- or ku- of a one-syllable verb in the future and past (atala, alila for atakula, alikula).', '{"question":"Jaza: Kesho tu___ (la) wali.","wrong_answer":"tutala","correct_answer":"tutakula"}'::jsonb, 'With longer verbs the stem follows the marker directly, so the child does the same with monosyllabic verbs.', 'The question "Jaza: Kesho tu___ (la) wali." with "tutala" among the options.', 'One-syllable verbs (la, nywa, ja, fa) keep ku- after -li- and -ta-: tutakula, alikunywa, atakuja.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T5_MAZUNGUMZO_MAHUSUSI.MAAMKUZI_JAMII.M7_MJM_RELIGIOUS_REPLY', 'KISW.G7.KUSIKI.T5_MAZUNGUMZO_MAHUSUSI.MAAMKUZI_JAMII', 'Answers a religious greeting with the reply of another (Salaam aleikum - Amina; Bwana asifiwe - Aleikum salaam).', '{"question":"Mtu akikusalimu \"Asalaam aleikum\", unajibu?","wrong_answer":"Amina","correct_answer":"Waaleikum salaam"}'::jsonb, 'The replies are learnt as a list without the greeting each belongs to.', 'The question "Mtu akikusalimu "Asalaam aleikum", unajibu?" with "Amina" among the options.', 'Pair cards: greeting with its reply; practise in pairs.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T5_MAZUNGUMZO_MAHUSUSI.MAAMKUZI_JAMII.M7_MJM_TIME', 'KISW.G7.KUSIKI.T5_MAZUNGUMZO_MAHUSUSI.MAAMKUZI_JAMII', 'Uses the greeting of another part of the day (Habari za asubuhi at 7 p.m.; Usiku mwema on arrival).', '{"question":"Ni saa moja usiku unamtembelea jirani. Unasalimu vipi?","wrong_answer":"Habari za asubuhi","correct_answer":"Habari za jioni (au za usiku)"}'::jsonb, 'The child uses the greeting he uses at school in the morning.', 'The question "Ni saa moja usiku unamtembelea jirani. Unasalimu vipi?" with "Habari za asubuhi" among the options.', 'Clock face game: greeting cards placed by time.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T5_MAZUNGUMZO_MAHUSUSI.MAAMKUZI_JAMII.M7_MJM_BEREAVED', 'KISW.G7.KUSIKI.T5_MAZUNGUMZO_MAHUSUSI.MAAMKUZI_JAMII', 'Greets the bereaved with a cheerful greeting (Habari njema?) instead of words of sympathy (Pole kwa msiba).', '{"question":"Unamtembelea rafiki aliyefiwa na babu. Unaanza kwa?","wrong_answer":"Habari njema rafiki?","correct_answer":"Pole sana kwa msiba."}'::jsonb, 'Habari is the default greeting.', 'The question "Unamtembelea rafiki aliyefiwa na babu. Unaanza kwa?" with "Habari njema rafiki?" among the options.', 'Role-play a condolence visit.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T5_MAZUNGUMZO_MAHUSUSI.MAAMKUZI_JAMII.M7_MJM_AGEMATE', 'KISW.G7.KUSIKI.T5_MAZUNGUMZO_MAHUSUSI.MAAMKUZI_JAMII', 'Uses Shikamoo to an age-mate, or Mambo/Vipi to an elder.', '{"question":"Unamsalimu mwanafunzi mwenzako wa darasa la saba. Ni salamu ipi inafaa?","wrong_answer":"Shikamoo","correct_answer":"Hujambo? / Habari yako?"}'::jsonb, 'The child knows Shikamoo is respectful and uses it everywhere, or the reverse.', 'The question "Unamsalimu mwanafunzi mwenzako wa darasa la saba. Ni salamu ipi inafaa?" with "Shikamoo" among the options.', 'Sort people by age and role; match each to a greeting.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.RS_UFAHAMU5.M_KS7_RS_UFAHAMU5_DETAIL', 'KISW.G7.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.RS_UFAHAMU5', 'Picks one small detail instead of the answer asked for.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lijibu swali lote, si jambo moja dogo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.RS_UFAHAMU5.M_KS7_RS_UFAHAMU5_OPPOSITE', 'KISW.G7.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.RS_UFAHAMU5', 'Picks the opposite of what the text says.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lipatane na matini, si kinyume chake.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.RS_UFAHAMU5.M_KS7_RS_UFAHAMU5_NOTSAID', 'KISW.G7.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.RS_UFAHAMU5', 'Picks something the text does not say.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lipatikane kwenye matini, si kuongezwa kutoka nje.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.RS_UFAHAMU5.M7_UFH_RS_UFAHAMU5', 'KISW.G7.KUSOMA.T5_KUSOMA_KWA_UFAHAMU.RS_UFAHAMU5', 'Writes a summary answer that copies a whole paragraph.', '{"question":"Eleza kwa ufupi aya ya pili inahusu nini.","wrong_answer":"kunakili aya yote","correct_answer":"sentensi moja yenye wazo kuu la aya"}'::jsonb, 'Copying feels safe.', 'The question "Eleza kwa ufupi aya ya pili inahusu nini." with "kunakili aya yote" among the options.', 'Close the passage; say the main idea in one sentence; then check.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T5_INSHA_YA_MAELEKEZO.MAELEKEZO.M7_INS_NOVIFAA_T5', 'KISW.G7.KUANDI.T5_INSHA_YA_MAELEKEZO.MAELEKEZO', 'Starts the steps without saying what is needed (vifaa) or what the instructions are for.', '{"question":"Maelekezo ya \"Jinsi ya Kuripoti Unyanyasaji\" huanza na nini?","wrong_answer":"hatua ya kwanza moja kwa moja","correct_answer":"lengo la maelekezo na vifaa vinavyohitajika"}'::jsonb, 'The child goes straight to doing.', 'The question "Maelekezo ya "Jinsi ya Kuripoti Unyanyasaji" huanza na nini?" with "hatua ya kwanza moja kwa moja" among the options.', 'Plan: lengo, vifaa, hatua, tahadhari.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T5_INSHA_YA_MAELEKEZO.MAELEKEZO.M7_INS_STORYFORM_T5', 'KISW.G7.KUANDI.T5_INSHA_YA_MAELEKEZO.MAELEKEZO', 'Tells what he did in the past (Nilichukua..., nilikoroga...) instead of giving instructions (Chukua..., koroga...).', '{"question":"Ni sentensi ipi inafaa katika insha ya maelekezo?","wrong_answer":"Nilichukua sufuria nikaweka maji.","correct_answer":"Chukua sufuria na uweke maji."}'::jsonb, 'The child turns instructions into a story of his own day.', 'The question "Ni sentensi ipi inafaa katika insha ya maelekezo?" with "Nilichukua sufuria nikaweka maji." among the options.', 'Underline the verbs; change each to the command or -e form (chukua, weka; uchukue).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T5_INSHA_YA_MAELEKEZO.MAELEKEZO.M7_INS_ORDER_M_T5', 'KISW.G7.KUANDI.T5_INSHA_YA_MAELEKEZO.MAELEKEZO', 'Gives the steps in an order that cannot work, with no signal words.', '{"question":"Ni mpangilio upi unafaa katika \"Jinsi ya Kuripoti Unyanyasaji\"?","wrong_answer":"fuatilia hadi usaidiwe, nenda kituo cha polisi kilicho karibu, piga simu 116, mwambie mtu mzima unayemwamini","correct_answer":"mwambie mtu mzima unayemwamini, piga simu 116, nenda kituo cha polisi kilicho karibu, fuatilia hadi usaidiwe"}'::jsonb, 'The child lists steps as he remembers them.', 'The question "Ni mpangilio upi unafaa katika "Jinsi ya Kuripoti Unyanyasaji"?" with "fuatilia hadi usaidiwe, nenda kituo cha polisi kilicho karibu, piga simu 116, mwambie mtu mzima unayemwamini" among the options.', 'Act out the steps; number them; add kwanza, kisha, baadaye, mwishowe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T5_INSHA_YA_MAELEKEZO.MAELEKEZO.M7_INS_NOWARN_T5', 'KISW.G7.KUANDI.T5_INSHA_YA_MAELEKEZO.MAELEKEZO', 'Leaves out safety warnings where the task needs them.', '{"question":"Ni kipi kinakosekana katika maelekezo ya \"Jinsi ya Kuripoti Unyanyasaji\"?","wrong_answer":"anwani","correct_answer":"tahadhari ya usalama"}'::jsonb, 'Warnings are not part of the steps, so they are forgotten.', 'The question "Ni kipi kinakosekana katika maelekezo ya "Jinsi ya Kuripoti Unyanyasaji"?" with "anwani" among the options.', 'Ask at each step: what could go wrong? Write a tahadhari.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T5_NYAKATI_NA_HALI.NYAKATI_KUENDELEA.M_KS7_NK_AKISOMA', 'KISW.G7.SARUFI.T5_NYAKATI_NA_HALI.NYAKATI_KUENDELEA', 'Uses the past continuous for a future event.', '{"question":"Ni sentensi ipi iko katika ujao hali ya kuendelea?","wrong_answer":"Alikuwa akisoma jana","correct_answer":"Atakuwa akisoma kesho"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Alikuwa akisoma jana" next to the right answer and ask the question again in a new sentence.', 'Ujao hali ya kuendelea hutumia atakuwa akisoma.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T5_NYAKATI_NA_HALI.NYAKATI_KUENDELEA.M_KS7_NK_ALIKUWA', 'KISW.G7.SARUFI.T5_NYAKATI_NA_HALI.NYAKATI_KUENDELEA', 'Thinks alikuwa means a finished act.', '{"question":"Alikuwa akipika humaanisha nini?","wrong_answer":"Alimaliza kupika","correct_answer":"Alikuwa katikati ya kupika wakati huo"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Alimaliza kupika" next to the right answer and ask the question again in a new sentence.', 'Alikuwa akipika ni uliopita hali ya kuendelea: tendo lilikuwa likiendelea.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T5_NYAKATI_NA_HALI.NYAKATI_KUENDELEA.M_KS7_NK_PAST_SIMPLE', 'KISW.G7.SARUFI.T5_NYAKATI_NA_HALI.NYAKATI_KUENDELEA', 'Does not tell the simple past from the continuous.', '{"question":"Ni sentensi ipi ni uliopita hali ya kuendelea?","wrong_answer":"Alisoma jana","correct_answer":"Walikuwa wakicheza uwanjani"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Alisoma jana" next to the right answer and ask the question again in a new sentence.', 'Walikuwa wakicheza ni uliopita hali ya kuendelea.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T5_NYAKATI_NA_HALI.NYAKATI_KUENDELEA.M7_NK_KUWA_FORM', 'KISW.G7.SARUFI.T5_NYAKATI_NA_HALI.NYAKATI_KUENDELEA', 'Builds the continuous with the wrong form of the second verb (alikuwa anasoma is accepted; the child writes alikuwa alisoma or atakuwa atasoma).', '{"question":"Jaza: Jana saa nne mimi ni___kuwa ni___soma.","wrong_answer":"nilikuwa nilisoma","correct_answer":"nilikuwa nikisoma / nilikuwa ninasoma"}'::jsonb, 'The child puts the time marker in both verbs.', 'The question "Jaza: Jana saa nne mimi ni___kuwa ni___soma." with "nilikuwa nilisoma" among the options.', 'Only kuwa carries the time (-li-, -ta-); the main verb takes -ki- or -na-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T6_KUSIKILIZA_KWA_KUFAS.LS_MASUALA.M_KS7_LS_MASUALA_DETAIL', 'KISW.G7.KUSIKI.T6_KUSIKILIZA_KWA_KUFAS.LS_MASUALA', 'Picks one small detail instead of the answer asked for.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lijibu swali lote, si jambo moja dogo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T6_KUSIKILIZA_KWA_KUFAS.LS_MASUALA.M_KS7_LS_MASUALA_OPPOSITE', 'KISW.G7.KUSIKI.T6_KUSIKILIZA_KWA_KUFAS.LS_MASUALA', 'Picks the opposite of what the text says.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lipatane na matini, si kinyume chake.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T6_KUSIKILIZA_KWA_KUFAS.LS_MASUALA.M_KS7_LS_MASUALA_NOTSAID', 'KISW.G7.KUSIKI.T6_KUSIKILIZA_KWA_KUFAS.LS_MASUALA', 'Picks something the text does not say.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lipatikane kwenye matini, si kuongezwa kutoka nje.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T6_KUSIKILIZA_KWA_KUFAS.LS_MASUALA.M7_LSM_LS_MASUALA', 'KISW.G7.KUSIKI.T6_KUSIKILIZA_KWA_KUFAS.LS_MASUALA', 'Writes everything he heard instead of the issues raised.', '{"question":"Ulisikiliza habari. Taja masuala mawili yaliyozungumziwa.","wrong_answer":"kila kitu alichosikia","correct_answer":"masuala mawili makuu"}'::jsonb, 'The child fears missing something.', 'The question "Ulisikiliza habari. Taja masuala mawili yaliyozungumziwa." with "kila kitu alichosikia" among the options.', 'While listening, note only key words; after, group them into issues.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T6_KUSOMA_KWA_KINA.NOVELA_MAUDHUI.M7_FAS_SWAP_T6', 'KISW.G7.KUSOMA.T6_KUSOMA_KWA_KINA.NOVELA_MAUDHUI', 'Swaps maudhui (the issues the work is about) and dhamira (what the author aims to teach).', '{"question":"Katika \"Kisima cha Matumaini\", \"kuonya jamii dhidi ya ufisadi na kuhimiza ujasiri\" ni maudhui au dhamira?","wrong_answer":"maudhui","correct_answer":"dhamira"}'::jsonb, 'The two words are taught together and both answer "what is it about?"', 'The question "Katika "Kisima cha Matumaini", "kuonya jamii dhidi ya ufisadi na kuhimiza ujasiri" ni maudhui au dhamira?" with "maudhui" among the options.', 'Maudhui: the issues raised (ufisadi, elimu). Dhamira: the author''s aim (kuonya, kuhimiza). Sort sentences into the two.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T6_KUSOMA_KWA_KINA.NOVELA_MAUDHUI.M7_FAS_TITLE_T6', 'KISW.G7.KUSOMA.T6_KUSOMA_KWA_KINA.NOVELA_MAUDHUI', 'Gives the title or the setting of the work as its maudhui.', '{"question":"Ni ipi ni maudhui katika \"Kisima cha Matumaini\"?","wrong_answer":"Kisima cha Matumaini","correct_answer":"ufisadi na uhaba wa maji"}'::jsonb, 'The title is the only phrase about the whole work the child is sure of.', 'The question "Ni ipi ni maudhui katika "Kisima cha Matumaini"?" with "Kisima cha Matumaini" among the options.', 'Ask what issue the characters face and argue about; that is the maudhui.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T6_KUSOMA_KWA_KINA.NOVELA_MAUDHUI.M7_FAS_EVENT_T6', 'KISW.G7.KUSOMA.T6_KUSOMA_KWA_KINA.NOVELA_MAUDHUI', 'Gives one event of the story as its maudhui.', '{"question":"Maudhui ya \"Kisima cha Matumaini\" ni yapi?","wrong_answer":"Neema anagundua kisima kimefungwa","correct_answer":"ufisadi na uhaba wa maji"}'::jsonb, 'The event is memorable; the child has not moved from what happened to what it is about.', 'The question "Maudhui ya "Kisima cha Matumaini" ni yapi?" with "Neema anagundua kisima kimefungwa" among the options.', 'Ask: this event shows which issue? Write the issue in one or two words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T6_KUSOMA_KWA_KINA.NOVELA_MAUDHUI.M7_FAS_OUTSIDE_T6', 'KISW.G7.KUSOMA.T6_KUSOMA_KWA_KINA.NOVELA_MAUDHUI', 'States a lesson from his own life or religion that the work does not raise.', '{"question":"Kwa mujibu wa \"Kisima cha Matumaini\", mwandishi analenga nini?","wrong_answer":"kutuhimiza tuende kanisani au msikitini kila wiki","correct_answer":"kuonya jamii dhidi ya ufisadi na kuhimiza ujasiri"}'::jsonb, 'The question sounds like a moral question and the child gives a moral he knows.', 'The question "Kwa mujibu wa "Kisima cha Matumaini", mwandishi analenga nini?" with "kutuhimiza tuende kanisani au msikitini kila wiki" among the options.', 'Ask for the part of the text that shows the aim.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T6_INSHA_ZA_KUBUNI.KUBUNI_PICHA.M7_INS_PICHA_T6', 'KISW.G7.KUANDI.T6_INSHA_ZA_KUBUNI.KUBUNI_PICHA', 'Writes a story or a title that does not come from the picture given.', '{"question":"Picha inaonyesha moto katika maabara ya shule. Ni anwani ipi inafaa?","wrong_answer":"Siku ya Kuzaliwa Kwangu","correct_answer":"Moto Katika Maabara ya Shule"}'::jsonb, 'The child writes the story he had in mind before looking.', 'The question "Picha inaonyesha moto katika maabara ya shule. Ni anwani ipi inafaa?" with "Siku ya Kuzaliwa Kwangu" among the options.', 'List five things seen in the picture; the title and the events must use them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T6_INSHA_ZA_KUBUNI.KUBUNI_PICHA.M7_INS_MANDHARI_T6', 'KISW.G7.KUANDI.T6_INSHA_ZA_KUBUNI.KUBUNI_PICHA', 'Gives no setting (time and place) or one that does not fit the events.', '{"question":"Ni mwanzo upi unaonyesha mandhari ya insha \"Moto Katika Maabara ya Shule\"?","wrong_answer":"Kisa hiki kilitokea.","correct_answer":"Ilikuwa jioni ya Ijumaa katika soko la Gikomba, watu wakiwa wamesongamana."}'::jsonb, 'The child starts with the action.', 'The question "Ni mwanzo upi unaonyesha mandhari ya insha "Moto Katika Maabara ya Shule"?" with "Kisa hiki kilitokea." among the options.', 'Answer lini? wapi? hali gani? in the first paragraph.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T6_INSHA_ZA_KUBUNI.KUBUNI_PICHA.M7_INS_DETAIL_T6', 'KISW.G7.KUANDI.T6_INSHA_ZA_KUBUNI.KUBUNI_PICHA', 'Describes with empty words (kizuri sana, kibaya) and no detail that makes a picture.', '{"question":"Ni sentensi ipi inajenga picha dhahiri kuhusu \"Moto Katika Maabara ya Shule\"?","wrong_answer":"Kulikuwa na moto.","correct_answer":"Moshi mzito mweusi ulifuka kutoka dirisha la maabara huku wanafunzi wakikimbia nje."}'::jsonb, 'The child knows the thing well and assumes the reader sees it too.', 'The question "Ni sentensi ipi inajenga picha dhahiri kuhusu "Moto Katika Maabara ya Shule"?" with "Kulikuwa na moto." among the options.', 'Five senses chart: what do you see, hear, smell, touch, taste? Turn one row into a sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T6_INSHA_ZA_KUBUNI.KUBUNI_PICHA.M7_INS_ORDER_T6', 'KISW.G7.KUANDI.T6_INSHA_ZA_KUBUNI.KUBUNI_PICHA', 'Puts the events in an order that cannot have happened (the end before the start), with no linking words.', '{"question":"Ni mpangilio upi wa matukio unafaa katika insha \"Moto Katika Maabara ya Shule\"?","wrong_answer":"wazima moto walifika, wanafunzi walitoka kwa mpangilio, kengele ililia, moto ulianza maabarani","correct_answer":"moto ulianza maabarani, kengele ililia, wanafunzi walitoka kwa mpangilio, wazima moto walifika"}'::jsonb, 'The child writes events as they come to mind; nobody has asked for a plan first.', 'The question "Ni mpangilio upi wa matukio unafaa katika insha "Moto Katika Maabara ya Shule"?" with "wazima moto walifika, wanafunzi walitoka kwa mpangilio, kengele ililia, moto ulianza maabarani" among the options.', 'Plan with three boxes (mwanzo, kati, mwisho) and linking words (kwanza, kisha, hatimaye) before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T6_VITENZI.VITENZI_VIKUU.M_KS7_VV_KISAIDIZI_KUU', 'KISW.G7.SARUFI.T6_VITENZI.VITENZI_VIKUU', 'Calls the helping verb the main verb.', '{"question":"Katika \"Alikuwa akisoma\", kitenzi kikuu ni kipi?","wrong_answer":"alikuwa","correct_answer":"akisoma"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "alikuwa" next to the right answer and ask the question again in a new sentence.', 'Kitenzi kikuu hubeba tendo: akisoma.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T6_VITENZI.VITENZI_VIKUU.M_KS7_VV_KUU_KISAIDIZI', 'KISW.G7.SARUFI.T6_VITENZI.VITENZI_VIKUU', 'Calls the main verb the helping verb.', '{"question":"Katika \"Atakuwa akifanya kazi\", kitenzi kisaidizi ni kipi?","wrong_answer":"akifanya","correct_answer":"atakuwa"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "akifanya" next to the right answer and ask the question again in a new sentence.', 'Kitenzi kisaidizi hutangulia kikuu: atakuwa.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T6_VITENZI.VITENZI_VIKUU.M_KS7_VV_SENTENSI', 'KISW.G7.SARUFI.T6_VITENZI.VITENZI_VIKUU', 'Thinks a sentence has only one verb word.', '{"question":"Katika \"Walikuwa wakicheza\", kuna vitenzi vingapi?","wrong_answer":"kimoja","correct_answer":"viwili: walikuwa na wakicheza"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "kimoja" next to the right answer and ask the question again in a new sentence.', 'Sentensi hii ina kisaidizi na kikuu.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T6_VITENZI.VITENZI_VIKUU.M7_VV_KUWA_MAIN', 'KISW.G7.SARUFI.T6_VITENZI.VITENZI_VIKUU', 'Thinks "kuwa" is always a helping verb, even where it is the only verb (Alikuwa mgonjwa).', '{"question":"Katika \"Alikuwa mgonjwa\", \"alikuwa\" ni kitenzi gani?","wrong_answer":"kisaidizi","correct_answer":"kikuu (kishirikishi)"}'::jsonb, 'Kuwa is taught first as a helping verb.', 'The question "Katika "Alikuwa mgonjwa", "alikuwa" ni kitenzi gani?" with "kisaidizi" among the options.', 'Check: is there another verb it helps? If not, kuwa is the main verb here.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T7_KUSIKILIZA_KWA_UFAHA.LS_UJUMBE.M_KS7_LS_UJUMBE_DETAIL', 'KISW.G7.KUSIKI.T7_KUSIKILIZA_KWA_UFAHA.LS_UJUMBE', 'Picks one small detail instead of the answer asked for.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lijibu swali lote, si jambo moja dogo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T7_KUSIKILIZA_KWA_UFAHA.LS_UJUMBE.M_KS7_LS_UJUMBE_OPPOSITE', 'KISW.G7.KUSIKI.T7_KUSIKILIZA_KWA_UFAHA.LS_UJUMBE', 'Picks the opposite of what the text says.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lipatane na matini, si kinyume chake.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T7_KUSIKILIZA_KWA_UFAHA.LS_UJUMBE.M_KS7_LS_UJUMBE_NOTSAID', 'KISW.G7.KUSIKI.T7_KUSIKILIZA_KWA_UFAHA.LS_UJUMBE', 'Picks something the text does not say.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lipatikane kwenye matini, si kuongezwa kutoka nje.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T7_KUSIKILIZA_KWA_UFAHA.LS_UJUMBE.M7_LSU_LS_UJUMBE', 'KISW.G7.KUSIKI.T7_KUSIKILIZA_KWA_UFAHA.LS_UJUMBE', 'Gives the first sentence he heard as the message.', '{"question":"Ujumbe wa ufahamu wa kusikiliza ni upi?","wrong_answer":"sentensi ya kwanza aliyosikia","correct_answer":"funzo kuu la habari yote"}'::jsonb, 'The opening is remembered best.', 'The question "Ujumbe wa ufahamu wa kusikiliza ni upi?" with "sentensi ya kwanza aliyosikia" among the options.', 'Listen to the end; then ask what the speaker wants us to know or do.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T7_UFUPISHO.UFUPISHO.M_KS7_UF_NAKALA', 'KISW.G7.KUSOMA.T7_UFUPISHO.UFUPISHO', 'Thinks a summary copies the passage.', '{"question":"Ufupisho ni nini?","wrong_answer":"kunakili habari yote","correct_answer":"kutoa habari kuu kwa ufupi"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "kunakili habari yote" next to the right answer and ask the question again in a new sentence.', 'Ufupisho ni kutoa habari kuu bila kupoteza maana.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T7_UFUPISHO.UFUPISHO.M_KS7_UF_MAANA', 'KISW.G7.KUSOMA.T7_UFUPISHO.UFUPISHO', 'Thinks a summary may change the meaning.', '{"question":"Ufupisho unapaswa kuwa vipi?","wrong_answer":"upoteze maana ya habari","correct_answer":"uhifadhi maana ya habari"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "upoteze maana ya habari" next to the right answer and ask the question again in a new sentence.', 'Ufupisho huhifadhi maana ya habari.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T7_UFUPISHO.UFUPISHO.M_KS7_UF_HABARI_KUU', 'KISW.G7.KUSOMA.T7_UFUPISHO.UFUPISHO', 'Picks a detail as the main idea.', '{"question":"Habari kuu ya aya ni ipi?","wrong_answer":"mfano mdogo uliotolewa","correct_answer":"wazo kuu la aya nzima"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "mfano mdogo uliotolewa" next to the right answer and ask the question again in a new sentence.', 'Habari kuu ni wazo kuu la aya nzima.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T7_UFUPISHO.UFUPISHO.M7_UF_ORDER', 'KISW.G7.KUSOMA.T7_UFUPISHO.UFUPISHO', 'Writes the points of the summary in a different order from the passage, so the ideas no longer follow.', '{"question":"Hoja za ufupisho zipangwe vipi?","wrong_answer":"kama zinavyokujia","correct_answer":"kwa mpangilio ule ule wa kifungu"}'::jsonb, 'The child writes the points he remembers best first.', 'The question "Hoja za ufupisho zipangwe vipi?" with "kama zinavyokujia" among the options.', 'Number the main point of each paragraph in the margin; write them in that order.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T7_INSHA_ZA_KUBUNI.MAELEZO_MSAMIATI.M7_INS_MSAMIATI_T7', 'KISW.G7.KUANDI.T7_INSHA_ZA_KUBUNI.MAELEZO_MSAMIATI', 'Uses vague or repeated words (kitu, kizuri, sana sana) where an exact word is needed.', '{"question":"Ni sentensi ipi ina msamiati ufaao kuhusu \"Siku ya Huduma kwa Jamii Shuleni\"?","wrong_answer":"Tulifanya vitu vingi vizuri.","correct_answer":"Tulipanda miche mia moja ya mikaratusi kando ya uzio wa shule."}'::jsonb, 'The child writes as he talks and has a small store of exact words.', 'The question "Ni sentensi ipi ina msamiati ufaao kuhusu "Siku ya Huduma kwa Jamii Shuleni"?" with "Tulifanya vitu vingi vizuri." among the options.', 'Keep a theme word bank; replace every "kitu" and "kizuri" from it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T7_INSHA_ZA_KUBUNI.MAELEZO_MSAMIATI.M7_INS_DETAIL_T7', 'KISW.G7.KUANDI.T7_INSHA_ZA_KUBUNI.MAELEZO_MSAMIATI', 'Describes with empty words (kizuri sana, kibaya) and no detail that makes a picture.', '{"question":"Ni sentensi ipi inajenga picha dhahiri kuhusu \"Siku ya Huduma kwa Jamii Shuleni\"?","wrong_answer":"Tulifanya vitu vingi vizuri.","correct_answer":"Tulipanda miche mia moja ya mikaratusi kando ya uzio wa shule."}'::jsonb, 'The child knows the thing well and assumes the reader sees it too.', 'The question "Ni sentensi ipi inajenga picha dhahiri kuhusu "Siku ya Huduma kwa Jamii Shuleni"?" with "Tulifanya vitu vingi vizuri." among the options.', 'Five senses chart: what do you see, hear, smell, touch, taste? Turn one row into a sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T7_INSHA_ZA_KUBUNI.MAELEZO_MSAMIATI.M7_INS_STORY_T7', 'KISW.G7.KUANDI.T7_INSHA_ZA_KUBUNI.MAELEZO_MSAMIATI', 'Tells a story of what happened where the insha should explain or describe.', '{"question":"Ni sentensi ipi inafaa katika insha ya maelezo kuhusu \"Siku ya Huduma kwa Jamii Shuleni\"?","wrong_answer":"Siku moja tulienda sokoni tukapotea.","correct_answer":"Tulipanda miche mia moja ya mikaratusi kando ya uzio wa shule."}'::jsonb, 'Stories are the kind of writing the child has done most and he falls back on it.', 'The question "Ni sentensi ipi inafaa katika insha ya maelezo kuhusu "Siku ya Huduma kwa Jamii Shuleni"?" with "Siku moja tulienda sokoni tukapotea." among the options.', 'Ask what the reader should know about the topic at the end: what it is, how it works or is done.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T7_INSHA_ZA_KUBUNI.MAELEZO_MSAMIATI.M7_INS_OFFTOPIC_T7', 'KISW.G7.KUANDI.T7_INSHA_ZA_KUBUNI.MAELEZO_MSAMIATI', 'Puts in points that are not about the title.', '{"question":"Katika insha ya maelezo yenye anwani \"Siku ya Huduma kwa Jamii Shuleni\", ni sentensi ipi haifai?","wrong_answer":"Rafiki yangu ana baiskeli mpya ya rangi ya bluu.","correct_answer":"Tulipanda miche mia moja ya mikaratusi kando ya uzio wa shule."}'::jsonb, 'The child adds whatever he remembers so the insha is long enough.', 'The question "Katika insha ya maelezo yenye anwani "Siku ya Huduma kwa Jamii Shuleni", ni sentensi ipi haifai?" with "Rafiki yangu ana baiskeli mpya ya rangi ya bluu." among the options.', 'Read each sentence and ask: does it tell the reader about the title? Cross out the ones that do not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T7_VITENZI_VISHIRIKISHI.VISHIRIKISHI.M_KS7_VS_NI_SI', 'KISW.G7.SARUFI.T7_VITENZI_VISHIRIKISHI.VISHIRIKISHI', 'Mixes ni and si.', '{"question":"Ni kitenzi kishirikishi kipi cha kukanusha?","wrong_answer":"ni","correct_answer":"si"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "ni" next to the right answer and ask the question again in a new sentence.', 'Si ni kishirikishi cha kukanusha; ni cha kuthibitisha.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T7_VITENZI_VISHIRIKISHI.VISHIRIKISHI.M_KS7_VS_YUKO', 'KISW.G7.SARUFI.T7_VITENZI_VISHIRIKISHI.VISHIRIKISHI', 'Uses yuko for a plural subject.', '{"question":"Kamilisha: Wanafunzi ___ darasani.","wrong_answer":"yuko","correct_answer":"wako"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "yuko" next to the right answer and ask the question again in a new sentence.', 'Wanafunzi ni wengi, kwa hiyo tunasema wako.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T7_VITENZI_VISHIRIKISHI.VISHIRIKISHI.M_KS7_VS_SIO', 'KISW.G7.SARUFI.T7_VITENZI_VISHIRIKISHI.VISHIRIKISHI', 'Does not know that si- is negative.', '{"question":"Neno sio katika \"Huyu sio mwalimu\" linaonyesha nini?","wrong_answer":"kuthibitisha","correct_answer":"kukanusha"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "kuthibitisha" next to the right answer and ask the question again in a new sentence.', 'Sio ni kishirikishi cha kukanusha.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T7_VITENZI_VISHIRIKISHI.VISHIRIKISHI.M7_VS_NDIYE_CLASS', 'KISW.G7.SARUFI.T7_VITENZI_VISHIRIKISHI.VISHIRIKISHI', 'Uses ndiye for things or ndio for one person (Kitabu ndiye changu).', '{"question":"Jaza: Kitabu hiki ___ changu.","wrong_answer":"ndiye","correct_answer":"ndicho"}'::jsonb, 'Ndiye is the first form learnt and is used for everything.', 'The question "Jaza: Kitabu hiki ___ changu." with "ndiye" among the options.', 'Ndi- + the class pronoun: ndiye (mtu), ndicho (kitu), ndio (miti, nk.).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T8_KUZUNGUMZA_ILI_KUPAS.KUPASHA_HABARI.M7_ORL_NOFACTS_T8', 'KISW.G7.KUSIKI.T8_KUZUNGUMZA_ILI_KUPAS.KUPASHA_HABARI', 'Gives news without the facts the listener needs (who, what, when, where).', '{"question":"Unapasha habari ya mkutano. Ni ipi kamili?","wrong_answer":"Kuna mkutano.","correct_answer":"Kutakuwa na mkutano wa wazazi Jumamosi saa nne asubuhi ukumbini."}'::jsonb, 'The child knows the facts and forgets the listener does not.', 'The question "Unapasha habari ya mkutano. Ni ipi kamili?" with "Kuna mkutano." among the options.', 'Check the news against nani, nini, lini, wapi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T8_KUZUNGUMZA_ILI_KUPAS.KUPASHA_HABARI.M7_ORL_OPINION_T8', 'KISW.G7.KUSIKI.T8_KUZUNGUMZA_ILI_KUPAS.KUPASHA_HABARI', 'Mixes his opinion with the facts when giving information.', '{"question":"Ni sentensi ipi ni habari tu?","wrong_answer":"Mkutano utakuwa wa kuchosha sana.","correct_answer":"Mkutano utaanza saa nne."}'::jsonb, 'Telling news and judging it are done together in chat.', 'The question "Ni sentensi ipi ni habari tu?" with "Mkutano utakuwa wa kuchosha sana." among the options.', 'Mark each sentence fact or opinion.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T8_KUZUNGUMZA_ILI_KUPAS.KUPASHA_HABARI.M7_ORL_SLANG_T8', 'KISW.G7.KUSIKI.T8_KUZUNGUMZA_ILI_KUPAS.KUPASHA_HABARI', 'Uses Sheng or English words in a formal talk.', '{"question":"Ni sentensi ipi inafaa katika mazungumzo rasmi?","wrong_answer":"Ma-guys, hii issue ni serious.","correct_answer":"Wenzangu, suala hili ni zito."}'::jsonb, 'The child talks as with friends.', 'The question "Ni sentensi ipi inafaa katika mazungumzo rasmi?" with "Ma-guys, hii issue ni serious." among the options.', 'Record and replay; replace each non-Kiswahili word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T8_KUZUNGUMZA_ILI_KUPAS.KUPASHA_HABARI.M7_ORL_EYES_T8', 'KISW.G7.KUSIKI.T8_KUZUNGUMZA_ILI_KUPAS.KUPASHA_HABARI', 'Listens or speaks without looking at the other person (looks down or away).', '{"question":"Ni ishara ipi inaonyesha unasikiliza kwa makini?","wrong_answer":"kuangalia chini muda wote","correct_answer":"kumwangalia mzungumzaji na kutikisa kichwa"}'::jsonb, 'Looking away is a sign of respect at home for some children; in class talk it reads as not listening.', 'The question "Ni ishara ipi inaonyesha unasikiliza kwa makini?" with "kuangalia chini muda wote" among the options.', 'Practise in pairs: listen with eyes on the speaker and nods; then swap.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T8_KUSOMA_KWA_KINA.NOVELA_MANDHARI.M7_FAS_PLACEONLY_T8', 'KISW.G7.KUSOMA.T8_KUSOMA_KWA_KINA.NOVELA_MANDHARI', 'Gives only the place as mandhari, and leaves out the time and the social setting.', '{"question":"Mandhari ya \"Kisima cha Matumaini\" ni yapi?","wrong_answer":"kijiji cha Mwangaza","correct_answer":"kijiji cha Mwangaza, wakati wa kiangazi kirefu"}'::jsonb, 'Mandhari is first taught as "mahali".', 'The question "Mandhari ya "Kisima cha Matumaini" ni yapi?" with "kijiji cha Mwangaza" among the options.', 'Make three boxes: mahali, wakati, hali ya kijamii; fill each from the text.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T8_KUSOMA_KWA_KINA.NOVELA_MANDHARI.M7_FAS_PLOT_LIST_T8', 'KISW.G7.KUSOMA.T8_KUSOMA_KWA_KINA.NOVELA_MANDHARI', 'Gives a list of the characters, or a summary of the message, as the ploti.', '{"question":"Ploti ya \"Kisima cha Matumaini\" ni nini?","wrong_answer":"orodha ya wahusika: Neema na Baraka","correct_answer":"mfuatano wa matukio tangu mwanzo hadi mwisho"}'::jsonb, 'Ploti is a new word and the child grabs what he knows about the work.', 'The question "Ploti ya "Kisima cha Matumaini" ni nini?" with "orodha ya wahusika: Neema na Baraka" among the options.', 'Ploti is the chain of events with cause: because A, then B. Build it with event cards and arrows.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T8_KUSOMA_KWA_KINA.NOVELA_MANDHARI.M7_FAS_PLOT_ORDER_T8', 'KISW.G7.KUSOMA.T8_KUSOMA_KWA_KINA.NOVELA_MANDHARI', 'Puts the events of the ploti in the order he remembers them, not the order of the story.', '{"question":"Ni tukio lipi huja kwanza katika ploti ya \"Kisima cha Matumaini\"?","wrong_answer":"Neema anagundua kisima kimefungwa","correct_answer":"tukio la mwanzo kabisa la kazi"}'::jsonb, 'The climax is remembered first.', 'The question "Ni tukio lipi huja kwanza katika ploti ya "Kisima cha Matumaini"?" with "Neema anagundua kisima kimefungwa" among the options.', 'Number the events on the page; then check the order against the chapters or scenes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T8_KUSOMA_KWA_KINA.NOVELA_MANDHARI.M7_FAS_NOUSE_T8', 'KISW.G7.KUSOMA.T8_KUSOMA_KWA_KINA.NOVELA_MANDHARI', 'Names the mandhari but cannot say why it matters to the story (it is "just where it happened").', '{"question":"Mandhari ya kijiji cha Mwangaza yana umuhimu gani katika \"Kisima cha Matumaini\"?","wrong_answer":"ni mahali tu hadithi ilipotokea","correct_answer":"yanaonyesha hali ya wahusika na kuchangia ufisadi na uhaba wa maji"}'::jsonb, 'Setting has been taught as a fact to find, not as a tool of the author.', 'The question "Mandhari ya kijiji cha Mwangaza yana umuhimu gani katika "Kisima cha Matumaini"?" with "ni mahali tu hadithi ilipotokea" among the options.', 'Ask: could the story happen the same way anywhere else? What does this place add?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T8_VIAKIFISHI.KIULIZI_KOMA.M_KS7_KK_KIKOMO', 'KISW.G7.KUANDI.T8_VIAKIFISHI.KIULIZI_KOMA', 'Ends a question with a full stop.', '{"question":"Swali huisha kwa nini?","wrong_answer":"kikomo","correct_answer":"kiulizi"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "kikomo" next to the right answer and ask the question again in a new sentence.', 'Swali huisha kwa kiulizi (?).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T8_VIAKIFISHI.KIULIZI_KOMA.M_KS7_KK_KOMA', 'KISW.G7.KUANDI.T8_VIAKIFISHI.KIULIZI_KOMA', 'Does not use the comma in a list.', '{"question":"Ni sentensi ipi ina koma sahihi?","wrong_answer":"Nilinunua, mkate maziwa na sukari.","correct_answer":"Nilinunua mkate, maziwa na sukari."}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Nilinunua, mkate maziwa na sukari." next to the right answer and ask the question again in a new sentence.', 'Koma hutenganisha vitu katika orodha.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T8_VIAKIFISHI.KIULIZI_KOMA.M_KS7_KK_SALAMU', 'KISW.G7.KUANDI.T8_VIAKIFISHI.KIULIZI_KOMA', 'Omits the comma after a greeting word.', '{"question":"Ni salamu ipi ina koma?","wrong_answer":"Mpendwa rafiki yangu","correct_answer":"Mpendwa rafiki yangu,"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Mpendwa rafiki yangu" next to the right answer and ask the question again in a new sentence.', 'Salamu ya barua huishia kwa koma.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T8_VIAKIFISHI.KIULIZI_KOMA.M7_KK_JE_COMMA', 'KISW.G7.KUANDI.T8_VIAKIFISHI.KIULIZI_KOMA', 'Leaves out the comma after "Je" at the start of a question (Je umefika?).', '{"question":"Ni ipi imeandikwa sawa?","wrong_answer":"Je umefika nyumbani?","correct_answer":"Je, umefika nyumbani?"}'::jsonb, 'Je is short and seems to need no mark.', 'The question "Ni ipi imeandikwa sawa?" with "Je umefika nyumbani?" among the options.', 'Rule: Je, + question + ?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T8_NGELI_NA_UPATANISHO_.NGELI_AWA_UI.M_KS7_GA_MTI_AWA', 'KISW.G7.SARUFI.T8_NGELI_NA_UPATANISHO_.NGELI_AWA_UI', 'Puts mti in A-WA.', '{"question":"Mti ni wa ngeli gani?","wrong_answer":"A-WA","correct_answer":"U-I"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "A-WA" next to the right answer and ask the question again in a new sentence.', 'Mti ni wa ngeli ya U-I; wingi wake ni miti.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T8_NGELI_NA_UPATANISHO_.NGELI_AWA_UI.M_KS7_GA_MTOTO_UI', 'KISW.G7.SARUFI.T8_NGELI_NA_UPATANISHO_.NGELI_AWA_UI', 'Puts mtoto in U-I.', '{"question":"Mtoto ni wa ngeli gani?","wrong_answer":"U-I","correct_answer":"A-WA"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "U-I" next to the right answer and ask the question again in a new sentence.', 'Mtoto ni mtu, kwa hiyo ni wa ngeli ya A-WA.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T8_NGELI_NA_UPATANISHO_.NGELI_AWA_UI.M_KS7_GA_UPATANISHO', 'KISW.G7.SARUFI.T8_NGELI_NA_UPATANISHO_.NGELI_AWA_UI', 'Uses the wrong agreement prefix.', '{"question":"Chagua sentensi sahihi.","wrong_answer":"Mti unakua na mtoto anakua zinakua","correct_answer":"Mti unakua na watoto wanakua"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Mti unakua na mtoto anakua zinakua" next to the right answer and ask the question again in a new sentence.', 'A-WA: a-, wa-. U-I: u-, i-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T8_NGELI_NA_UPATANISHO_.NGELI_AWA_UI.M7_GA_ANIMAL_THING', 'KISW.G7.SARUFI.T8_NGELI_NA_UPATANISHO_.NGELI_AWA_UI', 'Gives an animal the agreement of a thing (Mbwa imeumwa) because the noun has no m- or wa-.', '{"question":"Jaza: Mbwa wangu ___ (ameumwa / imeumwa).","wrong_answer":"imeumwa","correct_answer":"ameumwa"}'::jsonb, 'Mbwa looks like an N- noun (I-ZI), so the child uses i-.', 'The question "Jaza: Mbwa wangu ___ (ameumwa / imeumwa)." with "imeumwa" among the options.', 'All animals take A-WA agreement whatever their prefix: mbwa ameumwa, mbwa wameumwa.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T9_KUSIKILIZA_KWA_KINA.MATAMSHI.M7_MAT_SWAP_T9', 'KISW.G7.KUSIKI.T9_KUSIKILIZA_KWA_KINA.MATAMSHI', 'Hears or says /nd/ for /d/, so doa (a stain) becomes ndoa (a marriage).', '{"question":"Mwalimu anasema: \"doa\". Umesikia neno lipi?","wrong_answer":"ndoa","correct_answer":"doa"}'::jsonb, 'The nasal (n- or m-) before d is soft and quick; a child who does not hear it writes and says the word without it, or adds it where it does not belong, and the meaning changes.', 'The question "Mwalimu anasema: "doa". Umesikia neno lipi?" with "ndoa" among the options.', 'Say the pair slowly with a hand on the throat (or watching the lips); the child says which word was heard before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T9_KUSIKILIZA_KWA_KINA.MATAMSHI.M7_MAT_SPELL_T9', 'KISW.G7.KUSIKI.T9_KUSIKILIZA_KWA_KINA.MATAMSHI', 'Writes the word with the letter of the other sound (ndama where dama is meant).', '{"question":"Jaza pengo: ___ maana yake ni \"draughts (the board game)\".","wrong_answer":"ndama","correct_answer":"dama"}'::jsonb, 'The child spells as he speaks; if the two sounds are one sound in his speech, the letter is a guess.', 'The question "Jaza pengo: ___ maana yake ni "draughts (the board game)"." with "ndama" among the options.', 'Pair each spelling with its meaning on a card; the child sorts the cards by meaning, then by letter.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T9_KUSIKILIZA_KWA_KINA.MATAMSHI.M7_MAT_SAME_T9', 'KISW.G7.KUSIKI.T9_KUSIKILIZA_KWA_KINA.MATAMSHI', 'Thinks the two words are one word said in two ways, with one meaning.', '{"question":"\"dama\" na \"ndama\" ni maneno yenye maana moja?","wrong_answer":"ndiyo","correct_answer":"hapana"}'::jsonb, 'The child has heard both said by different people for the same thing and takes the difference for an accent.', 'The question ""dama" na "ndama" ni maneno yenye maana moja?" with "ndiyo" among the options.', 'Use both words in two sentences that cannot swap: the child says which sentence breaks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T9_KUSIKILIZA_KWA_KINA.MATAMSHI.M7_MAT_TWISTER_T9', 'KISW.G7.KUSIKI.T9_KUSIKILIZA_KWA_KINA.MATAMSHI', 'Takes any long sentence for a kitanzandimi, though it does not repeat the target sounds.', '{"question":"Ni kipi ni kitanzandimi?","wrong_answer":"Simu yangu mpya ina kamera nzuri.","correct_answer":"Ndege wa Dadi alidondoka ndani ya ndoo ya dada."}'::jsonb, 'The child thinks a kitanzandimi is any sentence that is hard to say, not one built by repeating close sounds.', 'The question "Ni kipi ni kitanzandimi?" with "Simu yangu mpya ina kamera nzuri." among the options.', 'Underline the target sounds in the real kitanzandimi; count them; the ordinary sentence has few or none.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T9_KUSIKILIZA_KWA_KINA.MATAMSHI.M7_MAT_SYLL_T9', 'KISW.G7.KUSIKI.T9_KUSIKILIZA_KWA_KINA.MATAMSHI', 'Splits the syllable with the nasal wrongly (n-doa instead of keeping the nasal with its consonant).', '{"question":"Neno \"ndoa\" lina silabi zipi?","wrong_answer":"n-doa","correct_answer":"ndo-a"}'::jsonb, 'In Kiswahili every syllable ends in a vowel, and a nasal with its consonant (nd, mb, nj, ng) starts one syllable; the child splits by letters, not by sound.', 'The question "Neno "ndoa" lina silabi zipi?" with "n-doa" among the options.', 'Clap the word: one clap per vowel; the nasal goes with the consonant after it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.RS_USHAWISHI.M_KS7_RS_USHAWISHI_DETAIL', 'KISW.G7.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.RS_USHAWISHI', 'Picks one small detail instead of the answer asked for.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lijibu swali lote, si jambo moja dogo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.RS_USHAWISHI.M_KS7_RS_USHAWISHI_OPPOSITE', 'KISW.G7.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.RS_USHAWISHI', 'Picks the opposite of what the text says.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lipatane na matini, si kinyume chake.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.RS_USHAWISHI.M_KS7_RS_USHAWISHI_NOTSAID', 'KISW.G7.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.RS_USHAWISHI', 'Picks something the text does not say.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lipatikane kwenye matini, si kuongezwa kutoka nje.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.RS_USHAWISHI.M7_USH_RS_USHAWISHI', 'KISW.G7.KUSOMA.T9_KUSOMA_KWA_UFAHAMU.RS_USHAWISHI', 'Takes the writer''s claim for a proven fact and does not see the persuading words.', '{"question":"Katika kifungu, \"Kila mtu mwenye busara hutumia simu hii\" ni nini?","wrong_answer":"ukweli uliothibitishwa","correct_answer":"mbinu ya ushawishi"}'::jsonb, 'Strong claims look like facts.', 'The question "Katika kifungu, "Kila mtu mwenye busara hutumia simu hii" ni nini?" with "ukweli uliothibitishwa" among the options.', 'Mark words that push the reader (kila mtu, bora zaidi, usikose).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T9_INSHA_ZA_KUBUNI.KUBUNI_AYA.M7_INS_AYA_T9', 'KISW.G7.KUANDI.T9_INSHA_ZA_KUBUNI.KUBUNI_AYA', 'Puts several ideas in one paragraph, or one idea across many tiny paragraphs, so no idea is built up.', '{"question":"Aya nzuri ya insha \"Ujumbe Uliobadilisha Maisha Yangu\" ina nini?","wrong_answer":"mawazo mengi tofauti","correct_answer":"wazo moja kuu linalokuzwa kwa maelezo na mifano"}'::jsonb, 'Paragraphs are made where the child pauses, not where an idea ends.', 'The question "Aya nzuri ya insha "Ujumbe Uliobadilisha Maisha Yangu" ina nini?" with "mawazo mengi tofauti" among the options.', 'Topic sentence first; then two or three sentences that develop only it; a link to the next paragraph.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T9_INSHA_ZA_KUBUNI.KUBUNI_AYA.M7_INS_MTAZAMO_T9', 'KISW.G7.KUANDI.T9_INSHA_ZA_KUBUNI.KUBUNI_AYA', 'Switches between "I" and "he" for the narrator, or between views, in one insha.', '{"question":"Ni lipi ni kosa katika insha moja?","wrong_answer":"kuanza \"nilikwenda...\" kisha \"alikwenda...\" kwa msimulizi yuleyule","correct_answer":"kutumia nafsi moja ya msimulizi tangu mwanzo hadi mwisho"}'::jsonb, 'The child forgets who is telling the story.', 'The question "Ni lipi ni kosa katika insha moja?" with "kuanza "nilikwenda..." kisha "alikwenda..." kwa msimulizi yuleyule" among the options.', 'Decide the narrator before writing; circle every verb of the narrator and check the person.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T9_INSHA_ZA_KUBUNI.KUBUNI_AYA.M7_INS_HISIA_T9', 'KISW.G7.KUANDI.T9_INSHA_ZA_KUBUNI.KUBUNI_AYA', 'States feelings with one word (nilihuzunika) and never shows them, so the reader feels nothing.', '{"question":"Ni sentensi ipi inamgusa msomaji zaidi?","wrong_answer":"Nilihuzunika.","correct_answer":"Machozi yalinitiririka nilipoona kibanda chetu kikiteketea."}'::jsonb, 'Showing a feeling needs words for the body and the scene.', 'The question "Ni sentensi ipi inamgusa msomaji zaidi?" with "Nilihuzunika." among the options.', 'Turn "nilihuzunika" into what the body did and what was seen.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T9_INSHA_ZA_KUBUNI.KUBUNI_AYA.M7_INS_ORDER_T9', 'KISW.G7.KUANDI.T9_INSHA_ZA_KUBUNI.KUBUNI_AYA', 'Puts the events in an order that cannot have happened (the end before the start), with no linking words.', '{"question":"Ni mpangilio upi wa matukio unafaa katika insha \"Ujumbe Uliobadilisha Maisha Yangu\"?","wrong_answer":"tuliripoti kwa polisi, tuligundua ni utapeli, nilimwonyesha mama, nilipokea ujumbe","correct_answer":"nilipokea ujumbe, nilimwonyesha mama, tuligundua ni utapeli, tuliripoti kwa polisi"}'::jsonb, 'The child writes events as they come to mind; nobody has asked for a plan first.', 'The question "Ni mpangilio upi wa matukio unafaa katika insha "Ujumbe Uliobadilisha Maisha Yangu"?" with "tuliripoti kwa polisi, tuligundua ni utapeli, nilimwonyesha mama, nilipokea ujumbe" among the options.', 'Plan with three boxes (mwanzo, kati, mwisho) and linking words (kwanza, kisha, hatimaye) before writing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T9_NGELI_NA_UPATANISHO_.NGELI_KIVI_LIYA.M_KS7_GK_KITABU', 'KISW.G7.SARUFI.T9_NGELI_NA_UPATANISHO_.NGELI_KIVI_LIYA', 'Puts kitabu in LI-YA.', '{"question":"Kitabu ni cha ngeli gani?","wrong_answer":"LI-YA","correct_answer":"KI-VI"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "LI-YA" next to the right answer and ask the question again in a new sentence.', 'Kitabu ni cha ngeli ya KI-VI; wingi wake ni vitabu.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T9_NGELI_NA_UPATANISHO_.NGELI_KIVI_LIYA.M_KS7_GK_JIWE', 'KISW.G7.SARUFI.T9_NGELI_NA_UPATANISHO_.NGELI_KIVI_LIYA', 'Puts jiwe in KI-VI.', '{"question":"Jiwe ni la ngeli gani?","wrong_answer":"KI-VI","correct_answer":"LI-YA"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "KI-VI" next to the right answer and ask the question again in a new sentence.', 'Jiwe ni la ngeli ya LI-YA; wingi wake ni mawe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T9_NGELI_NA_UPATANISHO_.NGELI_KIVI_LIYA.M_KS7_GK_UPATANISHO', 'KISW.G7.SARUFI.T9_NGELI_NA_UPATANISHO_.NGELI_KIVI_LIYA', 'Uses the wrong agreement prefix.', '{"question":"Chagua sentensi sahihi.","wrong_answer":"Kitabu kimeanguka na vitabu limeanguka","correct_answer":"Kitabu kimeanguka na vitabu vimeanguka"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Kitabu kimeanguka na vitabu limeanguka" next to the right answer and ask the question again in a new sentence.', 'KI-VI: ki-, vi-. LI-YA: li-, ya-.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T9_NGELI_NA_UPATANISHO_.NGELI_KIVI_LIYA.M7_GK_CH_NOUNS', 'KISW.G7.SARUFI.T9_NGELI_NA_UPATANISHO_.NGELI_KIVI_LIYA', 'Misses that ch- nouns (chakula, choo, chumba) are KI-VI and puts them elsewhere (chakula imeiva).', '{"question":"Jaza: Chakula ___ (kimeiva / imeiva).","wrong_answer":"imeiva","correct_answer":"kimeiva"}'::jsonb, 'The ki- prefix is hidden as ch- before a vowel.', 'The question "Jaza: Chakula ___ (kimeiva / imeiva)." with "imeiva" among the options.', 'Show the plural: chakula -> vyakula, chumba -> vyumba: ch-/vy- is ki-/vi- before a vowel.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T10_NYIMBO.NYIMBO.M7_FSI_KIND_T10', 'KISW.G7.KUSIKI.T10_NYIMBO.NYIMBO', 'Mixes the two kinds (wimbo wa kazi and wimbo wa dini) and their purposes.', '{"question":"\"Tupige jembe pamoja, shamba letu litastawi\" ni nyimbo ya aina gani?","wrong_answer":"wimbo wa dini","correct_answer":"wimbo wa kazi"}'::jsonb, 'Both are nyimbo; the child has not fixed what each is for and when it is used.', 'The question ""Tupige jembe pamoja, shamba letu litastawi" ni nyimbo ya aina gani?" with "wimbo wa dini" among the options.', 'List for each kind: who uses it, when, and why; sort examples.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T10_NYIMBO.NYIMBO.M7_FSI_WRITTEN_T10', 'KISW.G7.KUSIKI.T10_NYIMBO.NYIMBO', 'Calls nyimbo written literature because it is found in a textbook.', '{"question":"Nyimbo ni utanzu wa fasihi ipi?","wrong_answer":"fasihi andishi","correct_answer":"fasihi simulizi"}'::jsonb, 'The child meets it on the page in class.', 'The question "Nyimbo ni utanzu wa fasihi ipi?" with "fasihi andishi" among the options.', 'Ask: who first made it, and how was it passed on? By mouth, from one generation to the next.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T10_NYIMBO.NYIMBO.M7_FSI_OCCASION_T10', 'KISW.G7.KUSIKI.T10_NYIMBO.NYIMBO', 'Places the nyimbo in the wrong occasion (a lullaby at a work party, a work song at a funeral).', '{"question":"Wimbo wa kazi hutumika lini?","wrong_answer":"wakati wowote","correct_answer":"watu wanapolima au kufanya kazi pamoja"}'::jsonb, 'The occasion is not stated in the text, and the child does not link form to use.', 'The question "Wimbo wa kazi hutumika lini?" with "wakati wowote" among the options.', 'Act out the occasion; which kind fits it?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T10_NYIMBO.NYIMBO.M7_FSI_MESSAGE_T10', 'KISW.G7.KUSIKI.T10_NYIMBO.NYIMBO', 'Gives a line of the text as its message instead of the lesson.', '{"question":"Ujumbe wa \"Tupige jembe pamoja, shamba letu litastawi\" ni upi?","wrong_answer":"Tupige jembe pamoja, shamba letu litastawi","correct_answer":"kazi ya pamoja huwa nyepesi na huleta mafanikio."}'::jsonb, 'Copying a line feels like a safe answer.', 'The question "Ujumbe wa "Tupige jembe pamoja, shamba letu litastawi" ni upi?" with "Tupige jembe pamoja, shamba letu litastawi" among the options.', 'Close the text; say the lesson in your own words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T10_KUSOMA_KWA_KINA.NOVELA_WAHUSIKA.M7_FAS_MAINMINOR_T10', 'KISW.G7.KUSOMA.T10_KUSOMA_KWA_KINA.NOVELA_WAHUSIKA', 'Takes a minor character who appears often for the main character.', '{"question":"Mhusika mkuu katika \"Kisima cha Matumaini\" ni nani?","wrong_answer":"Baraka","correct_answer":"Neema"}'::jsonb, 'The child counts appearances, not who the story is about.', 'The question "Mhusika mkuu katika "Kisima cha Matumaini" ni nani?" with "Baraka" among the options.', 'Ask whose problem the story follows from start to end.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T10_KUSOMA_KWA_KINA.NOVELA_WAHUSIKA.M7_FAS_NOEVIDENCE_T10', 'KISW.G7.KUSOMA.T10_KUSOMA_KWA_KINA.NOVELA_WAHUSIKA', 'Gives a trait with no action from the text to show it.', '{"question":"Neema ni jasiri. Ni ushahidi upi unaothibitisha?","wrong_answer":"ni jasiri kwa sababu ni mhusika mzuri","correct_answer":"alienda kwa chifu peke yake kuripoti wizi wa maji"}'::jsonb, 'The child knows a trait must be named but not that it must be shown.', 'The question "Neema ni jasiri. Ni ushahidi upi unaothibitisha?" with "ni jasiri kwa sababu ni mhusika mzuri" among the options.', 'Use the frame: trait + "kwa sababu" + an action from the text.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T10_KUSOMA_KWA_KINA.NOVELA_WAHUSIKA.M7_FAS_LOOKS_T10', 'KISW.G7.KUSOMA.T10_KUSOMA_KWA_KINA.NOVELA_WAHUSIKA', 'Gives how the character looks (mrefu, mrembo) when the character''s nature is asked.', '{"question":"Taja sifa ya kitabia ya Neema.","wrong_answer":"mrefu na mwembamba","correct_answer":"jasiri"}'::jsonb, 'Describing people starts with appearance in lower grades.', 'The question "Taja sifa ya kitabia ya Neema." with "mrefu na mwembamba" among the options.', 'Two columns: sura (looks) and tabia (character); sort the words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T10_KUSOMA_KWA_KINA.NOVELA_WAHUSIKA.M7_FAS_LESSON_T10', 'KISW.G7.KUSOMA.T10_KUSOMA_KWA_KINA.NOVELA_WAHUSIKA', 'Takes the behaviour of a bad character as the lesson to copy.', '{"question":"Tunajifunza nini kutokana na matendo ya Bwana Tajiri?","wrong_answer":"tufanye kama yeye ili tufanikiwe","correct_answer":"tuepuke tabia mbaya kama zake kwa sababu zina madhara"}'::jsonb, 'The bad character often wins for a while, and the child sees the gain, not the end.', 'The question "Tunajifunza nini kutokana na matendo ya Bwana Tajiri?" with "tufanye kama yeye ili tufanikiwe" among the options.', 'Follow the character to the end of the work: what did his actions bring?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T10_BARUA_RASMI_YA_KUOMB.BARUA_MSAMAHA.M_KS7_BS_ANWANI', 'KISW.G7.KUANDI.T10_BARUA_RASMI_YA_KUOMB.BARUA_MSAMAHA', 'Gives one address in a formal letter.', '{"question":"Barua rasmi ina anwani ngapi?","wrong_answer":"moja","correct_answer":"mbili: ya mwandishi na ya mwandikiwa"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "moja" next to the right answer and ask the question again in a new sentence.', 'Barua rasmi ina anwani mbili.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T10_BARUA_RASMI_YA_KUOMB.BARUA_MSAMAHA.M_KS7_BS_KICHWA', 'KISW.G7.KUANDI.T10_BARUA_RASMI_YA_KUOMB.BARUA_MSAMAHA', 'Leaves out the heading of a formal letter.', '{"question":"Barua rasmi huwa na nini kabla ya ujumbe?","wrong_answer":"hakuna kitu","correct_answer":"kichwa cha barua"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "hakuna kitu" next to the right answer and ask the question again in a new sentence.', 'Barua rasmi ina kichwa cha barua.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T10_BARUA_RASMI_YA_KUOMB.BARUA_MSAMAHA.M_KS7_BS_LUGHA', 'KISW.G7.KUANDI.T10_BARUA_RASMI_YA_KUOMB.BARUA_MSAMAHA', 'Uses slang in a formal letter.', '{"question":"Lugha ya barua rasmi ni ipi?","wrong_answer":"ya mtaani","correct_answer":"ya heshima na sanifu"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "ya mtaani" next to the right answer and ask the question again in a new sentence.', 'Barua rasmi hutumia lugha ya heshima na sanifu.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T10_BARUA_RASMI_YA_KUOMB.KUANDIKA_MSAMAHA.M7_INS_ONEADDR_T10', 'KISW.G7.KUANDI.T10_BARUA_RASMI_YA_KUOMB.KUANDIKA_MSAMAHA', 'Writes only one address, or puts the receiver''s address at the top right.', '{"question":"Barua rasmi ina anwani ngapi?","wrong_answer":"moja, ya mwandishi","correct_answer":"mbili: ya mwandishi (kulia juu) na ya mpokeaji (kushoto)"}'::jsonb, 'The friendly letter has one address and the child carries it over.', 'The question "Barua rasmi ina anwani ngapi?" with "moja, ya mwandishi" among the options.', 'Label both addresses on a model; the child writes his own and the receiver''s on a blank layout.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T10_BARUA_RASMI_YA_KUOMB.KUANDIKA_MSAMAHA.M7_INS_NOREF_T10', 'KISW.G7.KUANDI.T10_BARUA_RASMI_YA_KUOMB.KUANDIKA_MSAMAHA', 'Leaves out the subject line (KUH: or YAH:) or writes it as a long sentence.', '{"question":"Ni kichwa kipi kinafaa katika barua rasmi kuhusu ombi la msamaha kwa kuchelewa shuleni?","wrong_answer":"Nimeandika barua hii kwa sababu ninataka kukueleza mambo mengi.","correct_answer":"KUH: OMBI LA MSAMAHA KWA KUCHELEWA SHULENI"}'::jsonb, 'The child does not know the reader of an official letter needs the subject before reading.', 'The question "Ni kichwa kipi kinafaa katika barua rasmi kuhusu ombi la msamaha kwa kuchelewa shuleni?" with "Nimeandika barua hii kwa sababu ninataka kukueleza mambo mengi." among the options.', 'Underline the KUH: line on three real letters; it is short and in capitals.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T10_BARUA_RASMI_YA_KUOMB.KUANDIKA_MSAMAHA.M7_INS_CASUAL_T10', 'KISW.G7.KUANDI.T10_BARUA_RASMI_YA_KUOMB.KUANDIKA_MSAMAHA', 'Uses friendly words in an official letter (Mpendwa rafiki, Hujambo?, Wako akupendaye).', '{"question":"Ni salamu ipi inafaa katika barua kwa Mwalimu Mkuu?","wrong_answer":"Hujambo mwalimu wangu mpendwa!","correct_answer":"Kwa Mwalimu Mkuu,"}'::jsonb, 'The friendly letter is the first letter learnt and its words come first.', 'The question "Ni salamu ipi inafaa katika barua kwa Mwalimu Mkuu?" with "Hujambo mwalimu wangu mpendwa!" among the options.', 'Sort salamu and closing cards into "kirafiki" and "rasmi".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T10_BARUA_RASMI_YA_KUOMB.KUANDIKA_MSAMAHA.M7_INS_SIGNOFF_T10', 'KISW.G7.KUANDI.T10_BARUA_RASMI_YA_KUOMB.KUANDIKA_MSAMAHA', 'Ends with only a first name and no signature, or with "Ni mimi rafiki yako".', '{"question":"Barua rasmi humalizika vipi?","wrong_answer":"Ni mimi rafiki yako, Wanjiku","correct_answer":"Wako mtiifu, sahihi, na jina kamili: Wanjiku Kamau"}'::jsonb, 'The friendly closing is a habit.', 'The question "Barua rasmi humalizika vipi?" with "Ni mimi rafiki yako, Wanjiku" among the options.', 'Model the closing block (Wako mtiifu, sahihi, jina kamili) and have the child copy it once.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T10_BARUA_RASMI_YA_KUOMB.BARUA_MSAMAHA.M7_BS_NOAPOLOGY', 'KISW.G7.KUANDI.T10_BARUA_RASMI_YA_KUOMB.BARUA_MSAMAHA', 'Explains or blames others at length but never actually says sorry or promises to change.', '{"question":"Ni sentensi ipi ni kiini cha barua ya kuomba msamaha?","wrong_answer":"Basi la shule lilichelewa na dereva alikuwa mzembe.","correct_answer":"Naomba msamaha kwa kuchelewa, na naahidi kufika mapema siku zijazo."}'::jsonb, 'The child wants to defend himself.', 'The question "Ni sentensi ipi ni kiini cha barua ya kuomba msamaha?" with "Basi la shule lilichelewa na dereva alikuwa mzembe." among the options.', 'Plan: what happened (briefly), the apology, the promise.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T10_VINYUME.VINYUME.M_KS7_VN_MAANA', 'KISW.G7.SARUFI.T10_VINYUME.VINYUME', 'Thinks an antonym is a synonym.', '{"question":"Kinyume cha neno ni nini?","wrong_answer":"Neno lenye maana sawa","correct_answer":"Neno lenye maana kinyume"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Neno lenye maana sawa" next to the right answer and ask the question again in a new sentence.', 'Kinyume cha neno ni neno lenye maana kinyume, kama kubwa na dogo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T10_VINYUME.VINYUME.M_KS7_VN_KIVUMISHI', 'KISW.G7.SARUFI.T10_VINYUME.VINYUME', 'Gives the wrong antonym of an adjective.', '{"question":"Kinyume cha mrefu ni kipi?","wrong_answer":"mnene","correct_answer":"mfupi"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "mnene" next to the right answer and ask the question again in a new sentence.', 'Kinyume cha mrefu ni mfupi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T10_VINYUME.VINYUME.M_KS7_VN_NOMINO', 'KISW.G7.SARUFI.T10_VINYUME.VINYUME', 'Gives the wrong antonym of a noun.', '{"question":"Kinyume cha mchana ni kipi?","wrong_answer":"asubuhi","correct_answer":"usiku"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "asubuhi" next to the right answer and ask the question again in a new sentence.', 'Kinyume cha mchana ni usiku.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T10_VINYUME.VINYUME.M7_VN_AGREE', 'KISW.G7.SARUFI.T10_VINYUME.VINYUME', 'Gives the right opposite stem but drops the class prefix (mti mrefu -> mti fupi).', '{"question":"Kinyume cha \"mti mrefu\" ni?","wrong_answer":"mti fupi","correct_answer":"mti mfupi"}'::jsonb, 'The child changes only the stem he looked up.', 'The question "Kinyume cha "mti mrefu" ni?" with "mti fupi" among the options.', 'Keep the noun''s prefix on the new adjective.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T11_KUZUNGUMZA_KWA_KUAMB.ISHARA.M7_ORL_MISMATCH_T11', 'KISW.G7.KUSIKI.T11_KUZUNGUMZA_KWA_KUAMB.ISHARA', 'Uses a gesture that says the opposite of the words (shakes the head while saying yes).', '{"question":"Unasema \"Ndiyo, nimekubali.\" Ishara ipi inafaa?","wrong_answer":"kutikisa kichwa kushoto kulia","correct_answer":"kutikisa kichwa juu chini"}'::jsonb, 'Gestures are habits and not checked.', 'The question "Unasema "Ndiyo, nimekubali." Ishara ipi inafaa?" with "kutikisa kichwa kushoto kulia" among the options.', 'Mirror game: say a line, partner checks the gesture.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T11_KUZUNGUMZA_KWA_KUAMB.ISHARA.M7_ORL_TOOMANY_T11', 'KISW.G7.KUSIKI.T11_KUZUNGUMZA_KWA_KUAMB.ISHARA', 'Uses so many gestures that they distract from the words.', '{"question":"Ni lipi bora unapozungumza?","wrong_answer":"kusogeza mikono kila neno","correct_answer":"ishara chache zinazosisitiza hoja muhimu"}'::jsonb, 'The child thinks more gestures is better.', 'The question "Ni lipi bora unapozungumza?" with "kusogeza mikono kila neno" among the options.', 'Choose three key words to gesture on.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T11_KUZUNGUMZA_KWA_KUAMB.ISHARA.M7_ORL_EYES_T11', 'KISW.G7.KUSIKI.T11_KUZUNGUMZA_KWA_KUAMB.ISHARA', 'Listens or speaks without looking at the other person (looks down or away).', '{"question":"Ni ishara ipi inaonyesha unasikiliza kwa makini?","wrong_answer":"kuangalia chini muda wote","correct_answer":"kumwangalia mzungumzaji na kutikisa kichwa"}'::jsonb, 'Looking away is a sign of respect at home for some children; in class talk it reads as not listening.', 'The question "Ni ishara ipi inaonyesha unasikiliza kwa makini?" with "kuangalia chini muda wote" among the options.', 'Practise in pairs: listen with eyes on the speaker and nods; then swap.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T11_KUZUNGUMZA_KWA_KUAMB.ISHARA.M7_ORL_SLANG_T11', 'KISW.G7.KUSIKI.T11_KUZUNGUMZA_KWA_KUAMB.ISHARA', 'Uses Sheng or English words in a formal talk.', '{"question":"Ni sentensi ipi inafaa katika mazungumzo rasmi?","wrong_answer":"Ma-guys, hii issue ni serious.","correct_answer":"Wenzangu, suala hili ni zito."}'::jsonb, 'The child talks as with friends.', 'The question "Ni sentensi ipi inafaa katika mazungumzo rasmi?" with "Ma-guys, hii issue ni serious." among the options.', 'Record and replay; replace each non-Kiswahili word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T11_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M7_MAP_COVER_T11', 'KISW.G7.KUSOMA.T11_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Chooses a book by its cover picture or its thickness only.', '{"question":"Unataka kusoma kuhusu majukumu ya watoto. Utachaguaje kitabu?","wrong_answer":"kwa picha nzuri ya jalada","correct_answer":"kwa kusoma anwani, maelezo ya nyuma na ukurasa wa kwanza"}'::jsonb, 'Nobody has shown the child the title, the blurb and the first page as clues.', 'The question "Unataka kusoma kuhusu majukumu ya watoto. Utachaguaje kitabu?" with "kwa picha nzuri ya jalada" among the options.', 'Hold up two books; read the title and the back of each aloud; the child chooses and says which clue decided it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T11_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M7_MAP_LEVEL_T11', 'KISW.G7.KUSOMA.T11_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Chooses a text far above his reading level and gives up after a page.', '{"question":"Ukisoma ukurasa wa kwanza wa \"Kazi za Juma\" na hujui maneno mengi sana, ufanye nini?","wrong_answer":"endelea tu hata kama huelewi","correct_answer":"chagua matini nyingine iliyo ya kiwango chako"}'::jsonb, 'The child thinks a harder book is a better book, or chooses the book a friend chose.', 'The question "Ukisoma ukurasa wa kwanza wa "Kazi za Juma" na hujui maneno mengi sana, ufanye nini?" with "endelea tu hata kama huelewi" among the options.', 'The five-finger check: on one page, a finger for each unknown word; five fingers means the book is too hard for now.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T11_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M7_MAP_TITLEMSG_T11', 'KISW.G7.KUSOMA.T11_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Gives the title as the message of the text.', '{"question":"Ujumbe wa matini \"Kazi za Juma\" ni upi?","wrong_answer":"Kazi za Juma","correct_answer":"Watoto wakitimiza majukumu yao, familia hustawi."}'::jsonb, 'The title is the only sentence about the whole text that the child is sure of.', 'The question "Ujumbe wa matini "Kazi za Juma" ni upi?" with "Kazi za Juma" among the options.', 'Ask what the writer wants the reader to learn or do; the title only names the topic.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T11_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M7_MAP_DETAIL_T11', 'KISW.G7.KUSOMA.T11_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Gives one detail of the text as its message.', '{"question":"Ni ipi ni ujumbe wa matini kuhusu majukumu ya watoto?","wrong_answer":"Juma alichota maji kisimani.","correct_answer":"Watoto wakitimiza majukumu yao, familia hustawi."}'::jsonb, 'The detail was striking and is remembered; the child has not asked what the whole text is about.', 'The question "Ni ipi ni ujumbe wa matini kuhusu majukumu ya watoto?" with "Juma alichota maji kisimani." among the options.', 'Two boxes: "ujumbe" (one) and "maelezo" (many); the child sorts sentences from the text.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T11_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M7_MAP_KIND_T11', 'KISW.G7.KUSOMA.T11_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Does not tell one kind of text from another (takes a newspaper report for a story, or a poem for a story).', '{"question":"Matini yenye beti na mishororo ni ya aina gani?","wrong_answer":"hadithi","correct_answer":"shairi"}'::jsonb, 'The child has met most texts as "kitabu" and has not been shown the signs of each kind.', 'The question "Matini yenye beti na mishororo ni ya aina gani?" with "hadithi" among the options.', 'Lay out a story, a poem, a newspaper page and a dictionary; the child names one sign of each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T11_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA.M7_MAP_WORD_T11', 'KISW.G7.KUSOMA.T11_KUSOMA_KWA_MAPANA.MATINI_YA_KUCHAGUA', 'Guesses a new word from how it looks, not from the sentence it is in (jukumu).', '{"question":"Katika matini: \"Kila mtoto nyumbani ana jukumu lake.\" Neno \"jukumu\" lina maana gani?","wrong_answer":"chumba cha kulala","correct_answer":"kazi ambayo mtu anapaswa kuifanya"}'::jsonb, 'The child matches the word to a word it looks like instead of reading the sentence around it.', 'The question "Katika matini: "Kila mtoto nyumbani ana jukumu lake." Neno "jukumu" lina maana gani?" with "chumba cha kulala" among the options.', 'Cover the word; the child reads the sentence and says what word would fit; then compares.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T11_INSHA_ZA_KUBUNI.MAELEZO_MPANGILIO.M7_INS_STEPS_T11', 'KISW.G7.KUANDI.T11_INSHA_ZA_KUBUNI.MAELEZO_MPANGILIO', 'Gives the steps of how to do something in a mixed-up order.', '{"question":"Ni mpangilio upi unafaa katika maelezo ya \"Majukumu Yangu Nyumbani\"?","wrong_answer":"kujiandaa kwenda shule, kuchota maji, kufagia uwanja, kutandika kitanda","correct_answer":"kutandika kitanda, kufagia uwanja, kuchota maji, kujiandaa kwenda shule"}'::jsonb, 'The child remembers the steps as a set, not as a sequence.', 'The question "Ni mpangilio upi unafaa katika maelezo ya "Majukumu Yangu Nyumbani"?" with "kujiandaa kwenda shule, kuchota maji, kufagia uwanja, kutandika kitanda" among the options.', 'Act out the steps; number them; write them with kwanza, kisha, mwishowe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T11_INSHA_ZA_KUBUNI.MAELEZO_MPANGILIO.M7_INS_PARAS_T11', 'KISW.G7.KUANDI.T11_INSHA_ZA_KUBUNI.MAELEZO_MPANGILIO', 'Writes the whole insha as one paragraph with no utangulizi, kiini and hitimisho.', '{"question":"Insha \"Majukumu Yangu Nyumbani\" ina sehemu zipi?","wrong_answer":"aya moja ndefu","correct_answer":"utangulizi, kiini (aya kadhaa) na hitimisho"}'::jsonb, 'The child writes until the space is full and has not planned the parts.', 'The question "Insha "Majukumu Yangu Nyumbani" ina sehemu zipi?" with "aya moja ndefu" among the options.', 'Fold the page into three; one part in each; one idea per paragraph in the middle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T11_INSHA_ZA_KUBUNI.MAELEZO_MPANGILIO.M7_INS_OFFTOPIC_T11', 'KISW.G7.KUANDI.T11_INSHA_ZA_KUBUNI.MAELEZO_MPANGILIO', 'Puts in points that are not about the title.', '{"question":"Katika insha ya maelezo yenye anwani \"Majukumu Yangu Nyumbani\", ni sentensi ipi haifai?","wrong_answer":"Rafiki yangu ana baiskeli mpya ya rangi ya bluu.","correct_answer":"Kwanza, ninaamka saa kumi na moja na kutandika kitanda changu."}'::jsonb, 'The child adds whatever he remembers so the insha is long enough.', 'The question "Katika insha ya maelezo yenye anwani "Majukumu Yangu Nyumbani", ni sentensi ipi haifai?" with "Rafiki yangu ana baiskeli mpya ya rangi ya bluu." among the options.', 'Read each sentence and ask: does it tell the reader about the title? Cross out the ones that do not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T11_INSHA_ZA_KUBUNI.MAELEZO_MPANGILIO.M7_INS_MSAMIATI_T11', 'KISW.G7.KUANDI.T11_INSHA_ZA_KUBUNI.MAELEZO_MPANGILIO', 'Uses vague or repeated words (kitu, kizuri, sana sana) where an exact word is needed.', '{"question":"Ni sentensi ipi ina msamiati ufaao kuhusu \"Majukumu Yangu Nyumbani\"?","wrong_answer":"Ninafanya kazi nyingi nyumbani.","correct_answer":"Kwanza, ninaamka saa kumi na moja na kutandika kitanda changu."}'::jsonb, 'The child writes as he talks and has a small store of exact words.', 'The question "Ni sentensi ipi ina msamiati ufaao kuhusu "Majukumu Yangu Nyumbani"?" with "Ninafanya kazi nyingi nyumbani." among the options.', 'Keep a theme word bank; replace every "kitu" and "kizuri" from it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T11_MNYAMBULIKO_WA_VITEN.KAULI.M_KS7_KA_KUTENDEA', 'KISW.G7.SARUFI.T11_MNYAMBULIKO_WA_VITEN.KAULI', 'Confuses kutendea with kutendwa.', '{"question":"Ni kitenzi kipi katika kauli ya kutendea?","wrong_answer":"pikwa","correct_answer":"pikia"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "pikwa" next to the right answer and ask the question again in a new sentence.', 'Kutendea huonyesha kwa ajili ya nani, kama pikia.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T11_MNYAMBULIKO_WA_VITEN.KAULI.M_KS7_KA_KUTENDWA', 'KISW.G7.SARUFI.T11_MNYAMBULIKO_WA_VITEN.KAULI', 'Does not know the passive.', '{"question":"Ni kitenzi kipi katika kauli ya kutendwa?","wrong_answer":"pikia","correct_answer":"pikwa"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "pikia" next to the right answer and ask the question again in a new sentence.', 'Kutendwa huonyesha anayepokea tendo, kama pikwa.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T11_MNYAMBULIKO_WA_VITEN.KAULI.M_KS7_KA_KUTENDA', 'KISW.G7.SARUFI.T11_MNYAMBULIKO_WA_VITEN.KAULI', 'Calls the base form a different voice.', '{"question":"Ni kitenzi kipi katika kauli ya kutenda?","wrong_answer":"pikwa","correct_answer":"pika"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "pikwa" next to the right answer and ask the question again in a new sentence.', 'Kutenda ni umbo la kawaida, kama pika.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T11_MNYAMBULIKO_WA_VITEN.KAULI.M7_KA_IWA_EWA', 'KISW.G7.SARUFI.T11_MNYAMBULIKO_WA_VITEN.KAULI', 'Uses -iwa where -ewa is needed after e or o (somiwa for somewa), or the reverse.', '{"question":"Kauli ya kutendwa ya \"soma\" ni?","wrong_answer":"somiwa","correct_answer":"somwa"}'::jsonb, 'The vowel rule of extended verbs is not yet fixed.', 'The question "Kauli ya kutendwa ya "soma" ni?" with "somiwa" among the options.', 'Sort stems by vowel: o/e take -e- (someka, somea), a/i/u take -i- (pikika, pikia); the passive of soma is somwa.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T12_KUSIKILIZA_KWA_MAKIN.LS_HOJA.M_KS7_LS_HOJA_DETAIL', 'KISW.G7.KUSIKI.T12_KUSIKILIZA_KWA_MAKIN.LS_HOJA', 'Picks one small detail instead of the answer asked for.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lijibu swali lote, si jambo moja dogo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T12_KUSIKILIZA_KWA_MAKIN.LS_HOJA.M_KS7_LS_HOJA_OPPOSITE', 'KISW.G7.KUSIKI.T12_KUSIKILIZA_KWA_MAKIN.LS_HOJA', 'Picks the opposite of what the text says.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lipatane na matini, si kinyume chake.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T12_KUSIKILIZA_KWA_MAKIN.LS_HOJA.M_KS7_LS_HOJA_NOTSAID', 'KISW.G7.KUSIKI.T12_KUSIKILIZA_KWA_MAKIN.LS_HOJA', 'Picks something the text does not say.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lipatikane kwenye matini, si kuongezwa kutoka nje.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T12_KUSIKILIZA_KWA_MAKIN.LS_HOJA.M7_LSH_LS_HOJA', 'KISW.G7.KUSIKI.T12_KUSIKILIZA_KWA_MAKIN.LS_HOJA', 'Lists details as the main points of what he heard.', '{"question":"Taja hoja muhimu katika habari uliyosikiliza.","wrong_answer":"tarehe na majina yaliyotajwa","correct_answer":"mambo makuu ambayo mzungumzaji alieleza"}'::jsonb, 'Names and numbers are easy to note.', 'The question "Taja hoja muhimu katika habari uliyosikiliza." with "tarehe na majina yaliyotajwa" among the options.', 'Ask: if the listener knew only this, would he know the main points?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T12_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M7_UFS_WORDBYWORD_T12', 'KISW.G7.KUSOMA.T12_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads word by word or syllable by syllable, so the sentence has no meaning when heard.', '{"question":"Ni usomaji upi ni wa ufasaha: \"Kunawa mikono kwa sabuni huzuia kuenea kwa magonjwa.\"?","wrong_answer":"Kunawa ... mikono ... kwa ... sabuni ... huzuia ... kuenea ... kwa ... magonjwa.","correct_answer":"Kunawa mikono kwa sabuni huzuia kuenea kwa magonjwa."}'::jsonb, 'The child is still decoding each word and has not yet learnt to read a phrase as one piece.', 'The question "Ni usomaji upi ni wa ufasaha: "Kunawa mikono kwa sabuni huzuia kuenea kwa magonjwa."?" with "Kunawa ... mikono ... kwa ... sabuni ... huzuia ... kuenea ... kwa ... magonjwa." among the options.', 'Echo reading: the teacher reads a phrase, the child repeats it as one breath; then phrase-cut the passage with slashes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T12_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M7_UFS_RACE_T12', 'KISW.G7.KUSOMA.T12_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads as fast as possible and thinks the fastest reader is the best.', '{"question":"Ni kasi ipi ifaayo ya kusoma kifungu darasani?","wrong_answer":"haraka iwezekanavyo","correct_answer":"kasi ya kuzungumza, ili kila neno lisikike"}'::jsonb, 'Reading races in class reward speed; the child has not been asked whether listeners understood.', 'The question "Ni kasi ipi ifaayo ya kusoma kifungu darasani?" with "haraka iwezekanavyo" among the options.', 'Time two readings: one very fast, one at speaking pace; listeners answer one question after each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T12_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M7_UFS_FLAT_T12', 'KISW.G7.KUSOMA.T12_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads a question and an exclamation in the same flat voice as a statement.', '{"question":"Sentensi \"Je, umepata chanjo zote?\" inasomwa vipi?","wrong_answer":"kwa sauti ileile ya sentensi ya kawaida","correct_answer":"sauti hupanda mwishoni kwa sababu ni swali"}'::jsonb, 'The child looks at the words and not at the mark at the end.', 'The question "Sentensi "Je, umepata chanjo zote?" inasomwa vipi?" with "kwa sauti ileile ya sentensi ya kawaida" among the options.', 'Read the same words three ways (. ? !); the child points at the mark that matches each reading.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T12_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M7_UFS_NOPAUSE_T12', 'KISW.G7.KUSOMA.T12_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Reads on through the koma and the kikomo without a pause.', '{"question":"Unasoma: \"Ole wetu, ugonjwa umeenea kijijini!\" Unasimama wapi kidogo?","wrong_answer":"hapana mahali, unasoma moja kwa moja","correct_answer":"kwenye koma na kwenye kikomo au alama ya hisi"}'::jsonb, 'The marks are read as decoration; the child has not linked them to breath.', 'The question "Unasoma: "Ole wetu, ugonjwa umeenea kijijini!" Unasimama wapi kidogo?" with "hapana mahali, unasoma moja kwa moja" among the options.', 'Clap once at a koma, twice at a kikomo while reading together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T12_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI.M7_UFS_SOUND_T12', 'KISW.G7.KUSOMA.T12_KUSOMA_KWA_UFASAHA.KUSOMA_KWA_SAUTI', 'Says /l/ for /r/ or /r/ for /l/ while reading (dalili read as darili).', '{"question":"Neno \"dalili\" linatamkwa vipi?","wrong_answer":"darili","correct_answer":"dalili"}'::jsonb, 'The first language of the child does not separate these sounds, so the reading carries the home sound.', 'The question "Neno "dalili" linatamkwa vipi?" with "darili" among the options.', 'Make a list of the passage words with the hard sound; practise them before reading the passage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T12_HOTUBA_YA_KUPASHA_HA.HOTUBA_KUPASHA.M7_INS_ITIFAKI_T12', 'KISW.G7.KUANDI.T12_HOTUBA_YA_KUPASHA_HA.HOTUBA_KUPASHA', 'Starts the speech with no greeting of the guests in order (itifaki).', '{"question":"Hotuba huanza vipi?","wrong_answer":"moja kwa moja na hoja ya kwanza","correct_answer":"kwa itifaki: Mheshimiwa mgeni rasmi, walimu, wazazi..."}'::jsonb, 'The child writes a speech like an insha.', 'The question "Hotuba huanza vipi?" with "moja kwa moja na hoja ya kwanza" among the options.', 'Model the itifaki line and the order of rank.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T12_HOTUBA_YA_KUPASHA_HA.HOTUBA_KUPASHA.M7_INS_ESSAY_T12', 'KISW.G7.KUANDI.T12_HOTUBA_YA_KUPASHA_HA.HOTUBA_KUPASHA', 'Writes about the listeners in the third person instead of speaking to them (Wanafunzi wanapaswa... instead of Wanafunzi wenzangu, tunapaswa...).', '{"question":"Ni sentensi ipi inafaa katika hotuba?","wrong_answer":"Wanafunzi wanapaswa kunawa mikono.","correct_answer":"Wanafunzi wenzangu, tunapaswa kunawa mikono."}'::jsonb, 'The speech is written, so it takes the voice of an essay.', 'The question "Ni sentensi ipi inafaa katika hotuba?" with "Wanafunzi wanapaswa kunawa mikono." among the options.', 'Read the draft aloud to the class; change every "wao" to "sisi" or "nyinyi".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T12_HOTUBA_YA_KUPASHA_HA.HOTUBA_KUPASHA.M7_INS_NOTHANKS_T12', 'KISW.G7.KUANDI.T12_HOTUBA_YA_KUPASHA_HA.HOTUBA_KUPASHA', 'Ends without thanking the audience or closing (Asanteni kwa kunisikiliza).', '{"question":"Hotuba humalizika vipi?","wrong_answer":"kwa hoja ya mwisho tu","correct_answer":"kwa muhtasari na \"Asanteni kwa kunisikiliza\""}'::jsonb, 'The child stops when the points run out.', 'The question "Hotuba humalizika vipi?" with "kwa hoja ya mwisho tu" among the options.', 'Model a closing: a call to act and thanks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T12_HOTUBA_YA_KUPASHA_HA.HOTUBA_KUPASHA.M7_INS_FACTLESS_T12', 'KISW.G7.KUANDI.T12_HOTUBA_YA_KUPASHA_HA.HOTUBA_KUPASHA', 'Gives an information speech with no facts the listener can use (dates, places, steps).', '{"question":"Ni sentensi ipi inafaa katika hotuba ya kupasha habari kuhusu chanjo dhidi ya surua?","wrong_answer":"Ugonjwa huu ni mbaya sana.","correct_answer":"Chanjo itatolewa katika zahanati ya Ruaka kuanzia Jumatatu ijayo."}'::jsonb, 'The child gives feelings, not information.', 'The question "Ni sentensi ipi inafaa katika hotuba ya kupasha habari kuhusu chanjo dhidi ya surua?" with "Ugonjwa huu ni mbaya sana." among the options.', 'Check the speech against nani, nini, lini, wapi, vipi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T12_AINA_ZA_SENTENSI.SENTENSI.M_KS7_ST_AMBATANO_MOJA', 'KISW.G7.SARUFI.T12_AINA_ZA_SENTENSI.SENTENSI', 'Thinks a compound sentence has one idea.', '{"question":"Sentensi ambatano ina nini?","wrong_answer":"Wazo moja tu","correct_answer":"Mawazo mawili au zaidi yaliyounganishwa"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Wazo moja tu" next to the right answer and ask the question again in a new sentence.', 'Sentensi ambatano huunganisha mawazo mawili au zaidi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T12_AINA_ZA_SENTENSI.SENTENSI.M_KS7_ST_KIUNGANISHI', 'KISW.G7.SARUFI.T12_AINA_ZA_SENTENSI.SENTENSI', 'Does not see the conjunction.', '{"question":"Ni sentensi ipi ni ambatano?","wrong_answer":"Mama anapika.","correct_answer":"Mama anapika na baba analima."}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Mama anapika." next to the right answer and ask the question again in a new sentence.', 'Kiunganishi na huunganisha mawazo mawili.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T12_AINA_ZA_SENTENSI.SENTENSI.M_KS7_ST_SAHILI_NYINGI', 'KISW.G7.SARUFI.T12_AINA_ZA_SENTENSI.SENTENSI', 'Calls a long simple sentence compound.', '{"question":"Ni sentensi ipi ni sahili?","wrong_answer":"Alikuja lakini aliondoka.","correct_answer":"Mtoto mwerevu anasoma kitabu kikubwa."}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Alikuja lakini aliondoka." next to the right answer and ask the question again in a new sentence.', 'Sentensi sahili ina wazo moja, hata ikiwa ndefu.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T12_AINA_ZA_SENTENSI.SENTENSI.M7_ST_COMMA_SPLICE', 'KISW.G7.SARUFI.T12_AINA_ZA_SENTENSI.SENTENSI', 'Joins two full ideas with only a comma, no joining word (Mama alipika, baba alilima).', '{"question":"Unganisha vizuri: \"Mama alipika. Baba alilima.\"","wrong_answer":"Mama alipika, baba alilima.","correct_answer":"Mama alipika na baba alilima."}'::jsonb, 'In speech the pause joins them.', 'The question "Unganisha vizuri: "Mama alipika. Baba alilima."" with "Mama alipika, baba alilima." among the options.', 'A compound sentence needs a joining word between the two ideas.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T13_WAHUSIKA_KATIKA_NYIM.WAHUSIKA_NYIMBO.M7_FSI_MAIN_T13', 'KISW.G7.KUSIKI.T13_WAHUSIKA_KATIKA_NYIM.WAHUSIKA_NYIMBO', 'Names a character who only appears once as the main one.', '{"question":"Mhusika mkuu katika nyimbo hii ni nani?","wrong_answer":"mhusika aliyetajwa mara moja","correct_answer":"Sungura"}'::jsonb, 'The child picks the most striking name.', 'The question "Mhusika mkuu katika nyimbo hii ni nani?" with "mhusika aliyetajwa mara moja" among the options.', 'Ask whom the whole text is about.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T13_WAHUSIKA_KATIKA_NYIM.WAHUSIKA_NYIMBO.M7_FSI_NOEVID_T13', 'KISW.G7.KUSIKI.T13_WAHUSIKA_KATIKA_NYIM.WAHUSIKA_NYIMBO', 'Gives a trait with no line or action as evidence.', '{"question":"Sungura ni mpatanishi. Thibitisha.","wrong_answer":"kwa sababu ni mzuri","correct_answer":"aliwaita Tembo na Kiboko wazungumze"}'::jsonb, 'Naming the trait feels like the answer.', 'The question "Sungura ni mpatanishi. Thibitisha." with "kwa sababu ni mzuri" among the options.', 'Frame: sifa + kwa sababu + action.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T13_WAHUSIKA_KATIKA_NYIM.WAHUSIKA_NYIMBO.M7_FSI_ANIMAL_T13', 'KISW.G7.KUSIKI.T13_WAHUSIKA_KATIKA_NYIM.WAHUSIKA_NYIMBO', 'Takes an animal character literally, not as standing for people (Sungura is just a hare).', '{"question":"Katika nyimbo, Sungura anawakilisha nini?","wrong_answer":"mnyama wa porini tu","correct_answer":"watu wenye tabia kama zake katika jamii"}'::jsonb, 'Animal characters look like animal facts.', 'The question "Katika nyimbo, Sungura anawakilisha nini?" with "mnyama wa porini tu" among the options.', 'Ask which people in the community behave like this character.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T13_WAHUSIKA_KATIKA_NYIM.WAHUSIKA_NYIMBO.M7_FSI_LESSON_T13', 'KISW.G7.KUSIKI.T13_WAHUSIKA_KATIKA_NYIM.WAHUSIKA_NYIMBO', 'Draws the wrong lesson from a character (copy the trickster because he won).', '{"question":"Tunajifunza nini kutokana na mhusika mjanja aliyeadhibiwa mwishoni?","wrong_answer":"tuwe wajanja ili tushinde","correct_answer":"ujanja wa kudanganya huleta adhabu"}'::jsonb, 'The trick is remembered; the ending is not.', 'The question "Tunajifunza nini kutokana na mhusika mjanja aliyeadhibiwa mwishoni?" with "tuwe wajanja ili tushinde" among the options.', 'Trace the character to the end: what did he gain and lose?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T13_KUSOMA_KWA_KINA.NOVELA_MBINU.M7_FAS_SIMMET_T13', 'KISW.G7.KUSOMA.T13_KUSOMA_KWA_KINA.NOVELA_MBINU', 'Calls a comparison with kama a sitiari, or one without kama a tashbihi.', '{"question":"\"Bwana Tajiri ni fisi\" ni mbinu gani?","wrong_answer":"tashbihi","correct_answer":"sitiari"}'::jsonb, 'Both compare; the child has not fixed which one uses kama, mithili ya or kana kwamba.', 'The question ""Bwana Tajiri ni fisi" ni mbinu gani?" with "tashbihi" among the options.', 'Circle kama, mithili ya, kana kwamba: present means tashbihi; absent means sitiari.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T13_KUSOMA_KWA_KINA.NOVELA_MBINU.M7_FAS_NAMEONLY_T13', 'KISW.G7.KUSOMA.T13_KUSOMA_KWA_KINA.NOVELA_MBINU', 'Names the device but cannot say what it does in the work.', '{"question":"Mbinu ya sitiari katika \"Bwana Tajiri ni fisi\" ina umuhimu gani?","wrong_answer":"ni sitiari","correct_answer":"inaonyesha ulafi wake wa mali"}'::jsonb, 'Devices have been taught as labels to find.', 'The question "Mbinu ya sitiari katika "Bwana Tajiri ni fisi" ina umuhimu gani?" with "ni sitiari" among the options.', 'Always add "inasaidia..." after the label: picture, feeling, stress, humour.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T13_KUSOMA_KWA_KINA.NOVELA_MBINU.M7_FAS_LITERAL_T13', 'KISW.G7.KUSOMA.T13_KUSOMA_KWA_KINA.NOVELA_MBINU', 'Reads a figure of speech literally.', '{"question":"\"Bwana Tajiri ni fisi\" ina maana gani?","wrong_answer":"maana ya maneno kama yalivyo","correct_answer":"inaonyesha ulafi wake wa mali"}'::jsonb, 'The child reads the words, not the picture.', 'The question ""Bwana Tajiri ni fisi" ina maana gani?" with "maana ya maneno kama yalivyo" among the options.', 'Ask: is this really true? If not, what does the writer want us to see?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T13_KUSOMA_KWA_KINA.NOVELA_MBINU.M7_FAS_TAKRIRI_T13', 'KISW.G7.KUSOMA.T13_KUSOMA_KWA_KINA.NOVELA_MBINU', 'Does not notice repetition (takriri) or rhetorical questions as devices.', '{"question":"\"Nitarudi, nitarudi, nitarudi!\" ni mbinu gani?","wrong_answer":"kosa la uchapishaji","correct_answer":"takriri: kurudia neno kusisitiza"}'::jsonb, 'Repetition looks like a mistake to a child taught not to repeat words.', 'The question ""Nitarudi, nitarudi, nitarudi!" ni mbinu gani?" with "kosa la uchapishaji" among the options.', 'Read the line aloud; what feeling does the repetition add?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T13_INSHA_ZA_KUBUNI.MAELEZO_SIFA_MTU.M7_INS_STORY_T13', 'KISW.G7.KUANDI.T13_INSHA_ZA_KUBUNI.MAELEZO_SIFA_MTU', 'Tells a story of what happened where the insha should describe the person, place or thing.', '{"question":"Ni sentensi ipi inafaa katika insha ya wasifu kuhusu \"Mpatanishi wa Kijiji Chetu\"?","wrong_answer":"Siku moja tulienda sokoni tukapotea.","correct_answer":"Mzee Kiprono, mwenye sauti tulivu na macho ya upole, husikiliza pande zote kabla ya kusema neno."}'::jsonb, 'Stories are the kind of writing the child has done most and he falls back on it.', 'The question "Ni sentensi ipi inafaa katika insha ya wasifu kuhusu "Mpatanishi wa Kijiji Chetu"?" with "Siku moja tulienda sokoni tukapotea." among the options.', 'Ask what the reader should know about the topic at the end: what it looks like, what it is for.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T13_INSHA_ZA_KUBUNI.MAELEZO_SIFA_MTU.M7_INS_DETAIL_T13', 'KISW.G7.KUANDI.T13_INSHA_ZA_KUBUNI.MAELEZO_SIFA_MTU', 'Describes with empty words (kizuri sana, kibaya) and no detail that makes a picture.', '{"question":"Ni sentensi ipi inajenga picha dhahiri kuhusu \"Mpatanishi wa Kijiji Chetu\"?","wrong_answer":"Mzee Kiprono ni mzuri.","correct_answer":"Mzee Kiprono, mwenye sauti tulivu na macho ya upole, husikiliza pande zote kabla ya kusema neno."}'::jsonb, 'The child knows the thing well and assumes the reader sees it too.', 'The question "Ni sentensi ipi inajenga picha dhahiri kuhusu "Mpatanishi wa Kijiji Chetu"?" with "Mzee Kiprono ni mzuri." among the options.', 'Five senses chart: what do you see, hear, smell, touch, taste? Turn one row into a sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T13_INSHA_ZA_KUBUNI.MAELEZO_SIFA_MTU.M7_INS_AGREE_T13', 'KISW.G7.KUANDI.T13_INSHA_ZA_KUBUNI.MAELEZO_SIFA_MTU', 'Uses a describing word that does not agree with its noun (bendera mzuri, miti mrefu).', '{"question":"Ni sentensi ipi ni sahihi?","wrong_answer":"Ana tabia mwema.","correct_answer":"Ana tabia njema."}'::jsonb, 'The child uses one form of the adjective (m-) for every noun, as he hears it for people.', 'The question "Ni sentensi ipi ni sahihi?" with "Ana tabia mwema." among the options.', 'Find the noun first, then its ngeli, then the prefix of the adjective.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T13_INSHA_ZA_KUBUNI.MAELEZO_SIFA_MTU.M7_INS_OFFTOPIC_T13', 'KISW.G7.KUANDI.T13_INSHA_ZA_KUBUNI.MAELEZO_SIFA_MTU', 'Puts in points that are not about the title.', '{"question":"Katika insha ya wasifu yenye anwani \"Mpatanishi wa Kijiji Chetu\", ni sentensi ipi haifai?","wrong_answer":"Rafiki yangu ana baiskeli mpya ya rangi ya bluu.","correct_answer":"Mzee Kiprono, mwenye sauti tulivu na macho ya upole, husikiliza pande zote kabla ya kusema neno."}'::jsonb, 'The child adds whatever he remembers so the insha is long enough.', 'The question "Katika insha ya wasifu yenye anwani "Mpatanishi wa Kijiji Chetu", ni sentensi ipi haifai?" with "Rafiki yangu ana baiskeli mpya ya rangi ya bluu." among the options.', 'Read each sentence and ask: does it tell the reader about the title? Cross out the ones that do not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T13_INSHA_ZA_KUBUNI.MAELEZO_SIFA_MTU.M7_INS_LUGHA_T13', 'KISW.G7.KUANDI.T13_INSHA_ZA_KUBUNI.MAELEZO_SIFA_MTU', 'Writes in plain, flat words with no language devices (tashbihi, sitiari, methali, nahau) to make the insha vivid.', '{"question":"Ni sentensi ipi ina lugha ya kiubunifu kwa insha \"Mpatanishi wa Kijiji Chetu\"?","wrong_answer":"Mzee Kiprono ni mzuri.","correct_answer":"Mzee Kiprono, mwenye sauti tulivu na macho ya upole, husikiliza pande zote kabla ya kusema neno."}'::jsonb, 'The child has not been shown how devices from fasihi can be used in his own writing.', 'The question "Ni sentensi ipi ina lugha ya kiubunifu kwa insha "Mpatanishi wa Kijiji Chetu"?" with "Mzee Kiprono ni mzuri." among the options.', 'Collect three devices from a class reader; rewrite one plain sentence with each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T13_UKANUSHAJI_KWA_KUZIN.UKANUSHAJI.M_KS7_UK_ULIOPO', 'KISW.G7.SARUFI.T13_UKANUSHAJI_KWA_KUZIN.UKANUSHAJI', 'Negates the present with ha-ku-.', '{"question":"Kanusha: Anasoma.","wrong_answer":"Hakusoma","correct_answer":"Hasomi"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Hakusoma" next to the right answer and ask the question again in a new sentence.', 'Ukanushaji wa uliopo ni hasomi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T13_UKANUSHAJI_KWA_KUZIN.UKANUSHAJI.M_KS7_UK_ULIOPITA', 'KISW.G7.SARUFI.T13_UKANUSHAJI_KWA_KUZIN.UKANUSHAJI', 'Negates the past without -ku-.', '{"question":"Kanusha: Alisoma.","wrong_answer":"Hasomi","correct_answer":"Hakusoma"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Hasomi" next to the right answer and ask the question again in a new sentence.', 'Ukanushaji wa uliopita ni hakusoma.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T13_UKANUSHAJI_KWA_KUZIN.UKANUSHAJI.M_KS7_UK_UJAO', 'KISW.G7.SARUFI.T13_UKANUSHAJI_KWA_KUZIN.UKANUSHAJI', 'Negates the future wrongly.', '{"question":"Kanusha: Atasoma.","wrong_answer":"Hakusoma","correct_answer":"Hatasoma"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Hakusoma" next to the right answer and ask the question again in a new sentence.', 'Ukanushaji wa ujao ni hatasoma.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T13_UKANUSHAJI_KWA_KUZIN.UKANUSHAJI.M7_UK_ME_JA', 'KISW.G7.SARUFI.T13_UKANUSHAJI_KWA_KUZIN.UKANUSHAJI', 'Negates -me- with -ku- (hakusoma for hajasoma), mixing the past and the perfect.', '{"question":"Kanusha: \"Amesoma kitabu.\"","wrong_answer":"Hakusoma kitabu.","correct_answer":"Hajasoma kitabu."}'::jsonb, 'Both -li- and -me- feel like "past".', 'The question "Kanusha: "Amesoma kitabu."" with "Hakusoma kitabu." among the options.', 'Pair them: -li- -> -ku- (hakusoma); -me- -> -ja- (hajasoma: not yet).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T14_LUGHA_KATIKA_NYIMBO.LUGHA_NYIMBO.M7_FSI_DEVICE_T14', 'KISW.G7.KUSIKI.T14_LUGHA_KATIKA_NYIMBO.LUGHA_NYIMBO', 'Does not see a device of language (repetition, simile, sound words) or calls it a mistake.', '{"question":"\"senti senti hujaza kibubu\" ni kipengele gani cha lugha?","wrong_answer":"kosa la lugha","correct_answer":"takriri na methali"}'::jsonb, 'The child has been told not to repeat words or use sounds in writing.', 'The question ""senti senti hujaza kibubu" ni kipengele gani cha lugha?" with "kosa la lugha" among the options.', 'Read aloud; what does the device add for the listener?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T14_LUGHA_KATIKA_NYIMBO.LUGHA_NYIMBO.M7_FSI_LITERAL_T14', 'KISW.G7.KUSIKI.T14_LUGHA_KATIKA_NYIMBO.LUGHA_NYIMBO', 'Reads a figure of speech literally.', '{"question":"\"senti senti hujaza kibubu\" ina maana gani?","wrong_answer":"maana ya maneno kama yalivyo","correct_answer":"husisitiza kuweka akiba kidogo kidogo"}'::jsonb, 'The child reads words, not pictures.', 'The question ""senti senti hujaza kibubu" ina maana gani?" with "maana ya maneno kama yalivyo" among the options.', 'Ask: is this really true? If not, what is meant?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T14_LUGHA_KATIKA_NYIMBO.LUGHA_NYIMBO.M7_FSI_USE_T14', 'KISW.G7.KUSIKI.T14_LUGHA_KATIKA_NYIMBO.LUGHA_NYIMBO', 'Names a device but cannot say why it matters (it makes the text nice).', '{"question":"Kipengele cha takriri na methali kina umuhimu gani?","wrong_answer":"kinapamba tu","correct_answer":"husisitiza kuweka akiba kidogo kidogo"}'::jsonb, 'Devices are taught as labels.', 'The question "Kipengele cha takriri na methali kina umuhimu gani?" with "kinapamba tu" among the options.', 'Always add what it does: picture, rhythm, memory, stress, feeling.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T14_LUGHA_KATIKA_NYIMBO.LUGHA_NYIMBO.M7_FSI_AUDIENCE_T14', 'KISW.G7.KUSIKI.T14_LUGHA_KATIKA_NYIMBO.LUGHA_NYIMBO', 'Does not see the call-and-response or the audience''s part as part of the language.', '{"question":"Msikilizaji anaposema \"Tega!\" au kuitikia wimbo, hiyo ni nini?","wrong_answer":"kelele zisizo na maana","correct_answer":"ushirikishaji wa hadhira, sehemu ya utungo"}'::jsonb, 'Written texts have no audience part.', 'The question "Msikilizaji anaposema "Tega!" au kuitikia wimbo, hiyo ni nini?" with "kelele zisizo na maana" among the options.', 'Perform it in class with and without the response; what is lost?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T14_KUSOMA_KWA_UFAHAMU.RS_MJADALA.M_KS7_RS_MJADALA_DETAIL', 'KISW.G7.KUSOMA.T14_KUSOMA_KWA_UFAHAMU.RS_MJADALA', 'Picks one small detail instead of the answer asked for.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lijibu swali lote, si jambo moja dogo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T14_KUSOMA_KWA_UFAHAMU.RS_MJADALA.M_KS7_RS_MJADALA_OPPOSITE', 'KISW.G7.KUSOMA.T14_KUSOMA_KWA_UFAHAMU.RS_MJADALA', 'Picks the opposite of what the text says.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lipatane na matini, si kinyume chake.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T14_KUSOMA_KWA_UFAHAMU.RS_MJADALA.M_KS7_RS_MJADALA_NOTSAID', 'KISW.G7.KUSOMA.T14_KUSOMA_KWA_UFAHAMU.RS_MJADALA', 'Picks something the text does not say.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lipatikane kwenye matini, si kuongezwa kutoka nje.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T14_KUSOMA_KWA_UFAHAMU.RS_MJADALA.M7_MJD_RS_MJADALA', 'KISW.G7.KUSOMA.T14_KUSOMA_KWA_UFAHAMU.RS_MJADALA', 'Gives only one side of the debate when both views are asked.', '{"question":"Kifungu kina mitazamo ipi kuhusu suala hili?","wrong_answer":"mtazamo wa upande mmoja tu","correct_answer":"mitazamo ya pande zote mbili"}'::jsonb, 'The child agrees with one side and reads only it.', 'The question "Kifungu kina mitazamo ipi kuhusu suala hili?" with "mtazamo wa upande mmoja tu" among the options.', 'Two columns: wanaounga mkono / wanaopinga; fill both.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T14_INSHA_YA_MAELEKEZO.MAELEKEZO.M7_INS_NOVIFAA_T14', 'KISW.G7.KUANDI.T14_INSHA_YA_MAELEKEZO.MAELEKEZO', 'Starts the steps without saying what is needed (vifaa) or what the instructions are for.', '{"question":"Maelekezo ya \"Jinsi ya Kufungua Akaunti ya Akiba\" huanza na nini?","wrong_answer":"hatua ya kwanza moja kwa moja","correct_answer":"lengo la maelekezo na vifaa vinavyohitajika"}'::jsonb, 'The child goes straight to doing.', 'The question "Maelekezo ya "Jinsi ya Kufungua Akaunti ya Akiba" huanza na nini?" with "hatua ya kwanza moja kwa moja" among the options.', 'Plan: lengo, vifaa, hatua, tahadhari.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T14_INSHA_YA_MAELEKEZO.MAELEKEZO.M7_INS_STORYFORM_T14', 'KISW.G7.KUANDI.T14_INSHA_YA_MAELEKEZO.MAELEKEZO', 'Tells what he did in the past (Nilichukua..., nilikoroga...) instead of giving instructions (Chukua..., koroga...).', '{"question":"Ni sentensi ipi inafaa katika insha ya maelekezo?","wrong_answer":"Nilichukua sufuria nikaweka maji.","correct_answer":"Chukua sufuria na uweke maji."}'::jsonb, 'The child turns instructions into a story of his own day.', 'The question "Ni sentensi ipi inafaa katika insha ya maelekezo?" with "Nilichukua sufuria nikaweka maji." among the options.', 'Underline the verbs; change each to the command or -e form (chukua, weka; uchukue).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T14_INSHA_YA_MAELEKEZO.MAELEKEZO.M7_INS_ORDER_M_T14', 'KISW.G7.KUANDI.T14_INSHA_YA_MAELEKEZO.MAELEKEZO', 'Gives the steps in an order that cannot work, with no signal words.', '{"question":"Ni mpangilio upi unafaa katika \"Jinsi ya Kufungua Akaunti ya Akiba\"?","wrong_answer":"weka pesa ya kwanza, jaza fomu, andaa kitambulisho, chagua benki au SACCO","correct_answer":"chagua benki au SACCO, andaa kitambulisho, jaza fomu, weka pesa ya kwanza"}'::jsonb, 'The child lists steps as he remembers them.', 'The question "Ni mpangilio upi unafaa katika "Jinsi ya Kufungua Akaunti ya Akiba"?" with "weka pesa ya kwanza, jaza fomu, andaa kitambulisho, chagua benki au SACCO" among the options.', 'Act out the steps; number them; add kwanza, kisha, baadaye, mwishowe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T14_INSHA_YA_MAELEKEZO.MAELEKEZO.M7_INS_NOWARN_T14', 'KISW.G7.KUANDI.T14_INSHA_YA_MAELEKEZO.MAELEKEZO', 'Leaves out safety warnings where the task needs them.', '{"question":"Ni kipi kinakosekana katika maelekezo ya \"Jinsi ya Kufungua Akaunti ya Akiba\"?","wrong_answer":"anwani","correct_answer":"tahadhari ya usalama"}'::jsonb, 'Warnings are not part of the steps, so they are forgotten.', 'The question "Ni kipi kinakosekana katika maelekezo ya "Jinsi ya Kufungua Akaunti ya Akiba"?" with "anwani" among the options.', 'Ask at each step: what could go wrong? Write a tahadhari.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T14_UKUBWA_WA_NOMINO.UKUBWA.M_KS7_UB_UDOGO', 'KISW.G7.SARUFI.T14_UKUBWA_WA_NOMINO.UKUBWA', 'Mixes augmentative and diminutive.', '{"question":"Jibwa ni nini?","wrong_answer":"mbwa mdogo","correct_answer":"mbwa mkubwa"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "mbwa mdogo" next to the right answer and ask the question again in a new sentence.', 'Jibwa ni mbwa mkubwa: hali ya ukubwa.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T14_UKUBWA_WA_NOMINO.UKUBWA.M_KS7_UB_KIAMBISHI', 'KISW.G7.SARUFI.T14_UKUBWA_WA_NOMINO.UKUBWA', 'Does not know the ji- prefix.', '{"question":"Ni kiambishi kipi cha ukubwa?","wrong_answer":"ki-","correct_answer":"ji-"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "ki-" next to the right answer and ask the question again in a new sentence.', 'Kiambishi cha ukubwa ni ji-, kama jitu.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T14_UKUBWA_WA_NOMINO.UKUBWA.M_KS7_UB_JUMBA', 'KISW.G7.SARUFI.T14_UKUBWA_WA_NOMINO.UKUBWA', 'Does not know jumba.', '{"question":"Jumba ni nini?","wrong_answer":"nyumba ndogo","correct_answer":"nyumba kubwa"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "nyumba ndogo" next to the right answer and ask the question again in a new sentence.', 'Jumba ni nyumba kubwa.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T14_UKUBWA_WA_NOMINO.UKUBWA.M7_UB_PLURAL', 'KISW.G7.SARUFI.T14_UKUBWA_WA_NOMINO.UKUBWA', 'Makes the plural of the big form with the plural of the ordinary noun (jibwa -> mbwa wakubwa) instead of ma- (majibwa).', '{"question":"Wingi wa \"jibwa\" ni?","wrong_answer":"mbwa wakubwa","correct_answer":"majibwa"}'::jsonb, 'The child goes back to the ordinary noun to make the plural.', 'The question "Wingi wa "jibwa" ni?" with "mbwa wakubwa" among the options.', 'Big forms are in LI-YA: the plural takes ma- (majibwa, majumba).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T15_KUSIKILIZA_HABARI_NA.LS_HABARI.M_KS7_LS_HABARI_DETAIL', 'KISW.G7.KUSIKI.T15_KUSIKILIZA_HABARI_NA.LS_HABARI', 'Picks one small detail instead of the answer asked for.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lijibu swali lote, si jambo moja dogo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T15_KUSIKILIZA_HABARI_NA.LS_HABARI.M_KS7_LS_HABARI_OPPOSITE', 'KISW.G7.KUSIKI.T15_KUSIKILIZA_HABARI_NA.LS_HABARI', 'Picks the opposite of what the text says.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lipatane na matini, si kinyume chake.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T15_KUSIKILIZA_HABARI_NA.LS_HABARI.M_KS7_LS_HABARI_NOTSAID', 'KISW.G7.KUSIKI.T15_KUSIKILIZA_HABARI_NA.LS_HABARI', 'Picks something the text does not say.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lipatikane kwenye matini, si kuongezwa kutoka nje.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSIKI.T15_KUSIKILIZA_HABARI_NA.LS_HABARI.M7_LSB_LS_HABARI', 'KISW.G7.KUSIKI.T15_KUSIKILIZA_HABARI_NA.LS_HABARI', 'Predicts what will happen without using what he heard.', '{"question":"Kutokana na habari uliyosikiliza, nini kitatokea?","wrong_answer":"chochote anachotaka","correct_answer":"jambo linalotokana na vidokezo vilivyosikika"}'::jsonb, 'Prediction is taken as wishing.', 'The question "Kutokana na habari uliyosikiliza, nini kitatokea?" with "chochote anachotaka" among the options.', 'Every prediction cites a clue heard.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T15_UFUPISHO.RS_UFUPISHO.M_KS7_RS_UFUPISHO_DETAIL', 'KISW.G7.KUSOMA.T15_UFUPISHO.RS_UFUPISHO', 'Picks one small detail instead of the answer asked for.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lijibu swali lote, si jambo moja dogo.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
