INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T15_UFUPISHO.RS_UFUPISHO.M_KS7_RS_UFUPISHO_NOTSAID', 'KISW.G7.KUSOMA.T15_UFUPISHO.RS_UFUPISHO', 'Picks something the text does not say.', '{"question":"Ni jibu lipi linalopatana na matini?","wrong_answer":"jibu lisilopatana na matini","correct_answer":"jibu ambalo matini inaunga mkono"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "jibu lisilopatana na matini" next to the right answer and ask the question again in a new sentence.', 'Jibu lazima lipatikane kwenye matini, si kuongezwa kutoka nje.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUSOMA.T15_UFUPISHO.RS_UFUPISHO.M7_UFU_RS_UFUPISHO', 'KISW.G7.KUSOMA.T15_UFUPISHO.RS_UFUPISHO', 'Keeps the examples and numbers in the summary and leaves out a main point.', '{"question":"Ni lipi liingie katika ufupisho wa kifungu?","wrong_answer":"mfano mmoja wa kifungu","correct_answer":"hoja kuu ya kila aya"}'::jsonb, 'Examples are concrete and easy to keep.', 'The question "Ni lipi liingie katika ufupisho wa kifungu?" with "mfano mmoja wa kifungu" among the options.', 'Underline the main point of each paragraph; cross out examples.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T15_KUANDIKA_KIDIJITALI.BARUAPEPE_RAFIKI.M7_INS_NOSUBJ_T15', 'KISW.G7.KUANDI.T15_KUANDIKA_KIDIJITALI.BARUAPEPE_RAFIKI', 'Leaves the subject box empty or writes the whole message in it.', '{"question":"Katika baruapepe, kisanduku cha \"Kichwa\" kinaandikwa nini?","wrong_answer":"ujumbe wote","correct_answer":"maneno machache yanayotaja ujumbe, kama \"Ushauri Kuhusu Maadili Mtandaoni\""}'::jsonb, 'The child has used chat apps that have no subject line.', 'The question "Katika baruapepe, kisanduku cha "Kichwa" kinaandikwa nini?" with "ujumbe wote" among the options.', 'Show an inbox: the subject is all the reader sees before opening.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T15_KUANDIKA_KIDIJITALI.BARUAPEPE_RAFIKI.M7_INS_ADDR_T15', 'KISW.G7.KUANDI.T15_KUANDIKA_KIDIJITALI.BARUAPEPE_RAFIKI', 'Writes a postal address and a date at the top, as in a paper letter.', '{"question":"Baruapepe huanza vipi?","wrong_answer":"S.L.P. 120, Nakuru, na tarehe juu kulia","correct_answer":"salamu kwa mpokeaji, kama \"Habari Amina,\""}'::jsonb, 'The paper letter is the model the child knows.', 'The question "Baruapepe huanza vipi?" with "S.L.P. 120, Nakuru, na tarehe juu kulia" among the options.', 'Compare a paper letter and an email; the email programme adds the address and date.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T15_KUANDIKA_KIDIJITALI.BARUAPEPE_RAFIKI.M7_INS_TOFIELD_T15', 'KISW.G7.KUANDI.T15_KUANDIKA_KIDIJITALI.BARUAPEPE_RAFIKI', 'Puts the receiver''s name, not the email address, in the "Kwa" box.', '{"question":"Kisanduku cha \"Kwa\" kinaandikwa nini?","wrong_answer":"Amina Otieno","correct_answer":"amina.otieno@mfano.co.ke"}'::jsonb, 'The child writes the person as on an envelope.', 'The question "Kisanduku cha "Kwa" kinaandikwa nini?" with "Amina Otieno" among the options.', 'Show what an email address looks like (jina@mahali); practise reading it aloud.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.KUANDI.T15_KUANDIKA_KIDIJITALI.BARUAPEPE_RAFIKI.M7_INS_TEXTSPEAK_T15', 'KISW.G7.KUANDI.T15_KUANDIKA_KIDIJITALI.BARUAPEPE_RAFIKI', 'Writes in short chat forms (sawa, poa, nkt, 2moro) and no closing.', '{"question":"Ni sentensi ipi inafaa katika baruapepe?","wrong_answer":"Poa, tutaonana 2moro.","correct_answer":"Asante. Tutaonana kesho."}'::jsonb, 'Chat habits come into the email.', 'The question "Ni sentensi ipi inafaa katika baruapepe?" with "Poa, tutaonana 2moro." among the options.', 'Rewrite one chat message as a short email with a greeting and a closing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T15_USEMI_HALISI_NA_USEM.USEMI.M_KS7_US_MTU', 'KISW.G7.SARUFI.T15_USEMI_HALISI_NA_USEM.USEMI', 'Keeps "mimi" in reported speech.', '{"question":"Badilisha: Juma alisema, \"Mimi nitaenda.\" (usemi wa taarifa)","wrong_answer":"Juma alisema kwamba mimi nitaenda.","correct_answer":"Juma alisema kwamba atakwenda."}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Juma alisema kwamba mimi nitaenda." next to the right answer and ask the question again in a new sentence.', 'Katika usemi wa taarifa mtu hubadilika: mimi huwa yeye.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T15_USEMI_HALISI_NA_USEM.USEMI.M_KS7_US_ALAMA', 'KISW.G7.SARUFI.T15_USEMI_HALISI_NA_USEM.USEMI', 'Keeps quotation marks in reported speech.', '{"question":"Ni usemi upi ni wa taarifa?","wrong_answer":"Juma alisema, \"Nitakuja.\"","correct_answer":"Juma alisema kwamba atakuja."}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Juma alisema, "Nitakuja."" next to the right answer and ask the question again in a new sentence.', 'Usemi wa taarifa hauna alama za usemi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T15_USEMI_HALISI_NA_USEM.USEMI.M_KS7_US_WAKATI', 'KISW.G7.SARUFI.T15_USEMI_HALISI_NA_USEM.USEMI', 'Does not change the tense.', '{"question":"Usemi halisi una nini?","wrong_answer":"Maneno ya msemaji bila alama","correct_answer":"Maneno kamili ya msemaji katika alama za usemi"}'::jsonb, 'The child mixes up two rules that are taught close together.', 'Offer "Maneno ya msemaji bila alama" next to the right answer and ask the question again in a new sentence.', 'Usemi halisi ni maneno kamili ya msemaji katika alama za usemi.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('KISW.G7.SARUFI.T15_USEMI_HALISI_NA_USEM.USEMI.M7_US_KESHO', 'KISW.G7.SARUFI.T15_USEMI_HALISI_NA_USEM.USEMI', 'Keeps the time and place words of the speaker unchanged in reported speech (kesho, hapa, leo).', '{"question":"Badilisha: Juma alisema, \"Nitakuja kesho.\"","wrong_answer":"Juma alisema kwamba atakuja kesho.","correct_answer":"Juma alisema kwamba angekuja siku iliyofuata."}'::jsonb, 'The child changes the person and the tense and stops there.', 'The question "Badilisha: Juma alisema, "Nitakuja kesho."" with "Juma alisema kwamba atakuja kesho." among the options.', 'Change time and place words too: leo -> siku hiyo, kesho -> siku iliyofuata, hapa -> pale.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
